// Nuvemath — 9-sinf, II qism (Geometriya 9) nazariyasi, t1–t9. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '9-2';

  // ---------- t1. 8-sinfni takrorlash: Pifagor teoremasi va yuzlar ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Yangi yil — eski qurollar bilan', 'Новый год — со старыми инструментами', 'A new year with old tools'), p: [
      L('9-sinf geometriyasi planimetriya kursining yakunlovchi qismi. Bu yil biz o‘xshash uchburchaklar, tekislikdagi almashtirishlar, uchburchak trigonometriyasi va aylana bilan ishlaymiz. Lekin har bir yangi mavzu ostida 8-sinfda o‘rganilgan ikki «ustun» turadi: <b>Pifagor teoremasi</b> va <b>yuzlar formulalari</b>. Ularsiz o‘xshashlikda noma’lum tomonni ham, sinus orqali yuzni ham topib bo‘lmaydi.', 'Геометрия 9 класса — завершающая часть курса планиметрии. В этом году мы будем работать с подобными треугольниками, преобразованиями плоскости, тригонометрией треугольника и окружностью. Но под каждой новой темой стоят две «колонны» из 8 класса: <b>теорема Пифагора</b> и <b>формулы площадей</b>. Без них не найти ни неизвестную сторону при подобии, ни площадь через синус.', 'Grade 9 geometry is the final part of the plane geometry course. This year we work with similar triangles, transformations of the plane, triangle trigonometry and the circle. But every new topic stands on two “pillars” from grade 8: <b>Pythagoras’ theorem</b> and the <b>area formulas</b>. Without them we cannot find a missing side in similar figures or an area through the sine.'),
      L('Tasavvur qiling: siz televizor sotib olmoqchisiz va do‘konda «55 dyuym» deb yozilgan. Bu ekranning eni ham, bo‘yi ham emas, balki <b>diagonali</b>! Eni va bo‘yini bilish uchun Pifagor teoremasi kerak. Xonangiz poliga laminat yotqizish uchun esa yuzni hisoblash kerak. Ko‘rinib turibdiki, bu formulalar faqat darslik uchun emas.', 'Представьте: вы покупаете телевизор, и в магазине написано «55 дюймов». Это не ширина и не высота экрана, а его <b>диагональ</b>! Чтобы узнать ширину и высоту, нужна теорема Пифагора. А чтобы уложить ламинат в комнате, нужно вычислить площадь. Как видите, эти формулы нужны не только для учебника.', 'Imagine you are buying a television and the shop says “55 inches”. That is neither the width nor the height of the screen but its <b>diagonal</b>! To find the width and height you need Pythagoras’ theorem. To lay laminate on your bedroom floor you need to compute an area. Clearly these formulas are not just for the textbook.'),
      L('Bu mavzuda biz Pifagor teoremasi va uning teskarisini, Pifagor uchliklarini, uchburchak, parallelogramm, romb va trapetsiya yuzlari formulalarini takrorlaymiz, ularning qayerdan kelib chiqishini eslaymiz va aralash masalalarni yechamiz. Takrorlash — bu zerikarli qaytarish emas: biz har bir formulani yangi ko‘z bilan ko‘ramiz va 9-sinfda ular qanday kerak bo‘lishini oldindan bilib olamiz.', 'В этой теме мы повторим теорему Пифагора и обратную ей, пифагоровы тройки, формулы площадей треугольника, параллелограмма, ромба и трапеции, вспомним, откуда они берутся, и решим смешанные задачи. Повторение — это не скучное заучивание: мы посмотрим на каждую формулу свежим взглядом и заранее узнаем, где она понадобится в 9 классе.', 'In this topic we review Pythagoras’ theorem and its converse, Pythagorean triples, and the area formulas for the triangle, parallelogram, rhombus and trapezium; we recall where they come from and solve mixed problems. Review is not boring repetition: we look at each formula with fresh eyes and find out in advance where it will be needed in grade 9.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('To‘g‘ri burchakli uchburchakda to‘g‘ri burchakka yopishgan tomonlar <b>katetlar</b> (a va b), to‘g‘ri burchak qarshisidagi eng uzun tomon esa <b>gipotenuza</b> (c) deyiladi. Shaklning <b>yuzi</b> — u egallagan tekislik qismining kattaligi; u kvadrat birliklarda o‘lchanadi: cm<sup>2</sup>, m<sup>2</sup>, ga.', 'В прямоугольном треугольнике стороны, образующие прямой угол, — <b>катеты</b> (a и b), а самая длинная сторона против прямого угла — <b>гипотенуза</b> (c). <b>Площадь</b> фигуры — величина занимаемой ею части плоскости; она измеряется в квадратных единицах: см<sup>2</sup>, м<sup>2</sup>, га.', 'In a right triangle the sides forming the right angle are the <b>legs</b> (a and b), and the longest side, opposite the right angle, is the <b>hypotenuse</b> (c). The <b>area</b> of a figure is the size of the part of the plane it covers; it is measured in square units: cm<sup>2</sup>, m<sup>2</sup>, hectares.')
    ], list: [
      L('<b>Yuz aksiomalari:</b> teng shakllarning yuzlari teng; shakl bo‘laklarga bo‘linsa, uning yuzi bo‘laklar yuzlari yig‘indisiga teng; tomoni 1 bo‘lgan kvadrat yuzi 1.', '<b>Свойства площади:</b> равные фигуры имеют равные площади; если фигура разбита на части, её площадь равна сумме площадей частей; площадь квадрата со стороной 1 равна 1.', '<b>Area axioms:</b> congruent figures have equal areas; if a figure is cut into pieces, its area is the sum of the pieces’ areas; a square of side 1 has area 1.'),
      L('<b>Balandlik</b> — uchdan qarama-qarshi tomonga (yoki uning davomiga) tushirilgan perpendikulyar. Uchburchakda uchta balandlik bor.', '<b>Высота</b> — перпендикуляр из вершины на противоположную сторону (или её продолжение). У треугольника три высоты.', 'A <b>height (altitude)</b> is the perpendicular from a vertex to the opposite side (or its extension). A triangle has three heights.'),
      L('<b>Pifagor uchligi</b> — a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup> ni qanoatlantiruvchi uchta natural son: 3, 4, 5; 5, 12, 13; 8, 15, 17; 7, 24, 25.', '<b>Пифагорова тройка</b> — три натуральных числа, для которых a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>: 3, 4, 5; 5, 12, 13; 8, 15, 17; 7, 24, 25.', 'A <b>Pythagorean triple</b> is three whole numbers with a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>: 3, 4, 5; 5, 12, 13; 8, 15, 17; 7, 24, 25.'),
      L('<b>Teng dosh shakllar</b> — yuzlari teng shakllar. Ular teng bo‘lishi shart emas: 2 × 8 to‘g‘ri to‘rtburchak va 4 × 4 kvadrat teng dosh.', '<b>Равновеликие фигуры</b> — фигуры с равными площадями. Они не обязаны быть равными: прямоугольник 2 × 8 и квадрат 4 × 4 равновелики.', '<b>Equal-area figures</b> need not be congruent: a 2 × 8 rectangle and a 4 × 4 square have the same area.')
    ] },
    { kind: 'history', h: L('Tarixdan: Bobil sopol taxtachasidan Yevklidgacha', 'Из истории: от вавилонской таблички до Евклида', 'History: from a Babylonian tablet to Euclid'), p: [
      L('Teorema Pifagor nomi bilan atalsa-da, uni undan ancha oldin bilishgan. Miloddan avvalgi XVIII asrga oid Bobil sopol taxtachasi <b>«Plimpton 322»</b> da Pifagor uchliklari ro‘yxati bor, masalan 119, 120, 169. Qadimgi Misrda arqonni 12 ta teng bo‘lakka tugun bilan bo‘lib, 3, 4, 5 uchburchak yasashgan va dalada to‘g‘ri burchak hosil qilishgan. Xitoyning «Chjoubi» kitobida ham 3, 4, 5 uchburchak chizmasi bor.', 'Хотя теорема носит имя Пифагора, её знали задолго до него. На вавилонской глиняной табличке <b>«Плимптон 322»</b> (XVIII век до н. э.) есть список пифагоровых троек, например 119, 120, 169. В Древнем Египте верёвку узлами делили на 12 равных частей, складывали треугольник 3, 4, 5 и получали прямой угол на поле. В китайской книге «Чжоуби» тоже есть чертёж треугольника 3, 4, 5.', 'Although the theorem bears Pythagoras’ name, it was known long before him. The Babylonian clay tablet <b>Plimpton 322</b> (18th century BC) lists Pythagorean triples such as 119, 120, 169. In ancient Egypt a rope was knotted into 12 equal parts and laid out as a 3, 4, 5 triangle to mark a right angle in the field. The Chinese book Zhoubi also shows a drawing of a 3, 4, 5 triangle.'),
      L('Miloddan avvalgi VI asrda yashagan <b>Pifagor</b> maktabi, rivoyatlarga ko‘ra, teoremaning umumiy isbotini bergan. Miloddan avvalgi 300-yil atrofida <b>Yevklid</b> «Negizlar» asarining I kitobini aynan shu teorema (47-taklif) va uning teskarisi (48-taklif) bilan yakunlagan. Yuzlar haqidagi ta’limot ham Yevklidda tizimga solingan: u parallelogramm va uchburchak yuzlarini taqqoslagan. O‘rta asrlarda <b>al-Xorazmiy</b> «Al-jabr» kitobining geometriya bo‘limida uchburchak, to‘rtburchak va doira yuzlarini hisoblash qoidalarini amaliy masalalar bilan bayon qilgan.', 'Школа <b>Пифагора</b> (VI век до н. э.), по преданию, дала общее доказательство теоремы. Около 300 года до н. э. <b>Евклид</b> завершил первую книгу «Начал» именно этой теоремой (предложение 47) и обратной ей (предложение 48). Учение о площадях тоже приведено у Евклида в систему: он сравнивал площади параллелограммов и треугольников. В Средние века <b>аль-Хорезми</b> в геометрическом разделе «Книги об алгебре» изложил правила вычисления площадей треугольника, четырёхугольника и круга на практических задачах.', 'According to tradition, the school of <b>Pythagoras</b> (6th century BC) gave a general proof. Around 300 BC <b>Euclid</b> ended Book I of the Elements with exactly this theorem (Proposition 47) and its converse (Proposition 48). Euclid also organised the theory of area, comparing parallelograms and triangles. In the Middle Ages <b>al-Khwarizmi</b>, in the geometry section of his book on algebra, set out rules for the areas of triangles, quadrilaterals and circles through practical problems.')
    ] },
    { kind: 'rule', h: L('Pifagor teoremasi va uning teskarisi', 'Теорема Пифагора и обратная теорема', 'Pythagoras’ theorem and its converse'), p: [
      L('<b>Teorema.</b> To‘g‘ri burchakli uchburchakda gipotenuza kvadrati katetlar kvadratlari yig‘indisiga teng: <b>c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup></b>.', '<b>Теорема.</b> В прямоугольном треугольнике квадрат гипотенузы равен сумме квадратов катетов: <b>c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup></b>.', '<b>Theorem.</b> In a right triangle the square of the hypotenuse equals the sum of the squares of the legs: <b>c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup></b>.'),
      L('<b>Isbot g‘oyasi (yuzlar orqali).</b> Tomoni a + b bo‘lgan kvadrat olamiz va uning ichiga katetlari a va b bo‘lgan to‘rtta teng uchburchakni burchaklarga joylaymiz. O‘rtada tomoni c bo‘lgan kvadrat qoladi. Katta kvadrat yuzini ikki usulda yozamiz: (a + b)<sup>2</sup> = 4 · ½ab + c<sup>2</sup>. Qavslarni ochsak: a<sup>2</sup> + 2ab + b<sup>2</sup> = 2ab + c<sup>2</sup>, ya’ni a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>. Ko‘rib turibsizki, isbotning o‘zi yuz tushunchasiga tayanadi!', '<b>Идея доказательства (через площади).</b> Возьмём квадрат со стороной a + b и разместим в его углах четыре равных треугольника с катетами a и b. В середине останется квадрат со стороной c. Запишем площадь большого квадрата двумя способами: (a + b)<sup>2</sup> = 4 · ½ab + c<sup>2</sup>. Раскрыв скобки: a<sup>2</sup> + 2ab + b<sup>2</sup> = 2ab + c<sup>2</sup>, то есть a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>. Как видите, само доказательство опирается на понятие площади!', '<b>Proof idea (with areas).</b> Take a square of side a + b and place four equal triangles with legs a and b in its corners. A square of side c is left in the middle. Write the big square’s area two ways: (a + b)<sup>2</sup> = 4 · ½ab + c<sup>2</sup>. Expanding: a<sup>2</sup> + 2ab + b<sup>2</sup> = 2ab + c<sup>2</sup>, so a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>. Notice that the proof itself rests on the idea of area!'),
      L('<b>Teskari teorema.</b> Agar uchburchakda bir tomon kvadrati qolgan ikki tomon kvadratlari yig‘indisiga teng bo‘lsa, bu uchburchak to‘g‘ri burchakli. Bundan tashqari: agar c<sup>2</sup> &gt; a<sup>2</sup> + b<sup>2</sup> bo‘lsa, c qarshisidagi burchak o‘tmas, c<sup>2</sup> &lt; a<sup>2</sup> + b<sup>2</sup> bo‘lsa — o‘tkir. Bu fakt kosinuslar teoremasida yana uchraydi.', '<b>Обратная теорема.</b> Если в треугольнике квадрат одной стороны равен сумме квадратов двух других, треугольник прямоугольный. Кроме того: если c<sup>2</sup> &gt; a<sup>2</sup> + b<sup>2</sup>, угол против c тупой, если c<sup>2</sup> &lt; a<sup>2</sup> + b<sup>2</sup> — острый. Этот факт снова встретится в теореме косинусов.', '<b>Converse.</b> If in a triangle the square of one side equals the sum of the squares of the other two, the triangle is right-angled. Moreover: if c<sup>2</sup> &gt; a<sup>2</sup> + b<sup>2</sup>, the angle opposite c is obtuse; if c<sup>2</sup> &lt; a<sup>2</sup> + b<sup>2</sup>, it is acute. This fact returns in the cosine rule.')
    ] },
    { kind: 'rule', h: L('Yuzlar formulalari va ularning kelib chiqishi', 'Формулы площадей и их происхождение', 'Area formulas and where they come from'), p: [
      L('<b>Parallelogramm:</b> S = a · h. Parallelogrammdan bir uchburchakni kesib, qarama-qarshi tomonga ko‘chirsak, asosi a va balandligi h bo‘lgan to‘g‘ri to‘rtburchak hosil bo‘ladi. Yuz o‘zgarmaydi, chunki biz shaklni faqat qayta joylashtirdik.', '<b>Параллелограмм:</b> S = a · h. Если отрезать от параллелограмма треугольник и перенести его к противоположной стороне, получится прямоугольник с основанием a и высотой h. Площадь не меняется — мы лишь переложили части.', '<b>Parallelogram:</b> S = a · h. Cut a triangle off one end and slide it to the other end: you get a rectangle with base a and height h. The area is unchanged because we only rearranged the pieces.'),
      L('<b>Uchburchak:</b> S = ½ a h. Ikkita teng uchburchakni yonma-yon qo‘ysak, parallelogramm hosil bo‘ladi, demak bitta uchburchak uning yarmi. To‘g‘ri burchakli uchburchakda katetlar bir-biriga balandlik: S = ½ ab. Bundan gipotenuzaga tushirilgan balandlik: h = ab / c.', '<b>Треугольник:</b> S = ½ a h. Два равных треугольника, приложенные друг к другу, дают параллелограмм, значит, один треугольник — его половина. В прямоугольном треугольнике катеты являются высотами друг к другу: S = ½ ab. Отсюда высота к гипотенузе: h = ab / c.', '<b>Triangle:</b> S = ½ a h. Two equal triangles placed together form a parallelogram, so one triangle is half of it. In a right triangle the legs are heights to each other: S = ½ ab. Hence the height to the hypotenuse is h = ab / c.'),
      L('<b>Romb</b> (va diagonallari perpendikulyar har qanday to‘rtburchak): S = ½ d<sub>1</sub>d<sub>2</sub>. <b>Trapetsiya:</b> S = (a + b) / 2 · h — diagonal trapetsiyani balandligi bir xil bo‘lgan ikki uchburchakka bo‘ladi: ½ah + ½bh. <b>Geron formulasi:</b> S = √(p(p − a)(p − b)(p − c)), bu yerda p — yarim perimetr; u faqat uch tomon ma’lum bo‘lganda qo‘l keladi.', '<b>Ромб</b> (и любой четырёхугольник с перпендикулярными диагоналями): S = ½ d<sub>1</sub>d<sub>2</sub>. <b>Трапеция:</b> S = (a + b) / 2 · h — диагональ делит трапецию на два треугольника с одинаковой высотой: ½ah + ½bh. <b>Формула Герона:</b> S = √(p(p − a)(p − b)(p − c)), где p — полупериметр; она выручает, когда известны только три стороны.', '<b>Rhombus</b> (and any quadrilateral with perpendicular diagonals): S = ½ d<sub>1</sub>d<sub>2</sub>. <b>Trapezium:</b> S = (a + b) / 2 · h — a diagonal splits it into two triangles with the same height: ½ah + ½bh. <b>Heron’s formula:</b> S = √(p(p − a)(p − b)(p − c)), where p is the semi-perimeter; it helps when only the three sides are known.')
    ] },
    { kind: 'steps', h: L('Aralash masalani yechish tartibi', 'Порядок решения смешанной задачи', 'How to attack a mixed problem'), list: [
      L('1. Chizma chizing va berilganlarni belgilang. To‘g‘ri burchaklarni alohida belgi bilan ko‘rsating.', '1. Сделайте чертёж и отметьте данные. Прямые углы отметьте специальным значком.', '1. Draw a figure and mark the given data. Mark right angles with a special sign.'),
      L('2. Yuz formulasini tanlang va unda nima yetishmayotganini aniqlang: ko‘pincha bu balandlik bo‘ladi.', '2. Выберите формулу площади и определите, чего в ней не хватает: чаще всего это высота.', '2. Choose an area formula and find what is missing: very often it is the height.'),
      L('3. Yetishmagan kesmani topish uchun to‘g‘ri burchakli uchburchak qidiring yoki uni balandlik tushirib hosil qiling.', '3. Чтобы найти недостающий отрезок, ищите прямоугольный треугольник или создайте его, опустив высоту.', '3. To find the missing length, look for a right triangle, or make one by dropping a height.'),
      L('4. Shu uchburchakka Pifagor teoremasini qo‘llang: gipotenuza kvadratidan katet kvadratini ayirib, ildiz chiqaring.', '4. Примените к этому треугольнику теорему Пифагора: из квадрата гипотенузы вычтите квадрат катета и извлеките корень.', '4. Apply Pythagoras to that triangle: subtract the leg’s square from the hypotenuse’s square and take the root.'),
      L('5. Topilgan qiymatni formulaga qo‘ying va javobni kvadrat birliklarda yozing. Natija aqlga muvofiqligini tekshiring.', '5. Подставьте найденное в формулу и запишите ответ в квадратных единицах. Проверьте, разумен ли результат.', '5. Substitute into the formula and give the answer in square units. Check that the result is sensible.')
    ], after: [
      L('Maslahat: Pifagor uchliklarini (3, 4, 5; 5, 12, 13; 8, 15, 17) yod bilsangiz, ko‘p masalalarda ildiz chiqarmasdan javobni darhol ko‘rasiz. Ularga karrali sonlar ham uchlik: 6, 8, 10; 9, 12, 15.', 'Совет: если помнить пифагоровы тройки (3, 4, 5; 5, 12, 13; 8, 15, 17), во многих задачах ответ виден сразу, без извлечения корня. Кратные им тоже тройки: 6, 8, 10; 9, 12, 15.', 'Tip: if you know the Pythagorean triples (3, 4, 5; 5, 12, 13; 8, 15, 17) by heart, you will see many answers at once without taking roots. Their multiples are triples too: 6, 8, 10; 9, 12, 15.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('To‘g‘ri burchakli uchburchakning katetlari 9 cm va 12 cm. Gipotenuzani, yuzni va gipotenuzaga tushirilgan balandlikni toping.', 'Катеты прямоугольного треугольника 9 см и 12 см. Найдите гипотенузу, площадь и высоту к гипотенузе.', 'A right triangle has legs 9 cm and 12 cm. Find the hypotenuse, the area and the height to the hypotenuse.'),
        s: L('c<sup>2</sup> = 81 + 144 = 225, c = 15 cm (bu 3, 4, 5 uchligining 3 barobari). S = ½ · 9 · 12 = 54 cm<sup>2</sup>. Yuzni gipotenuza orqali ham yozamiz: 54 = ½ · 15 · h, h = 108 / 15 = 7,2 cm.', 'c<sup>2</sup> = 81 + 144 = 225, c = 15 см (это тройка 3, 4, 5, умноженная на 3). S = ½ · 9 · 12 = 54 см<sup>2</sup>. Запишем площадь и через гипотенузу: 54 = ½ · 15 · h, h = 108 / 15 = 7,2 см.', 'c<sup>2</sup> = 81 + 144 = 225, so c = 15 cm (the 3, 4, 5 triple times 3). S = ½ · 9 · 12 = 54 cm<sup>2</sup>. Writing the area with the hypotenuse as base: 54 = ½ · 15 · h, so h = 108 / 15 = 7.2 cm.') },
      { q: L('Teng yonli uchburchakning asosi 16 cm, yon tomoni 10 cm. Uning yuzini toping.', 'Основание равнобедренного треугольника 16 см, боковая сторона 10 см. Найдите его площадь.', 'An isosceles triangle has base 16 cm and equal sides 10 cm. Find its area.'),
        s: L('Asosga tushirilgan balandlik uni teng ikkiga bo‘ladi: 8 cm. To‘g‘ri burchakli uchburchakda h<sup>2</sup> = 10<sup>2</sup> − 8<sup>2</sup> = 36, h = 6 cm. S = ½ · 16 · 6 = 48 cm<sup>2</sup>.', 'Высота к основанию делит его пополам: 8 см. В прямоугольном треугольнике h<sup>2</sup> = 10<sup>2</sup> − 8<sup>2</sup> = 36, h = 6 см. S = ½ · 16 · 6 = 48 см<sup>2</sup>.', 'The height to the base bisects it: 8 cm. In the right triangle h<sup>2</sup> = 10<sup>2</sup> − 8<sup>2</sup> = 36, so h = 6 cm. S = ½ · 16 · 6 = 48 cm<sup>2</sup>.') },
      { q: L('Rombning tomoni 13 cm, bir diagonali 24 cm. Ikkinchi diagonalni va yuzni toping.', 'Сторона ромба 13 см, одна диагональ 24 см. Найдите вторую диагональ и площадь.', 'A rhombus has side 13 cm and one diagonal 24 cm. Find the other diagonal and the area.'),
        s: L('Romb diagonallari perpendikulyar va kesishish nuqtasida teng ikkiga bo‘linadi. Yarim diagonallar: 12 va x; 12<sup>2</sup> + x<sup>2</sup> = 13<sup>2</sup>, x = 5. Ikkinchi diagonal 10 cm. S = ½ · 24 · 10 = 120 cm<sup>2</sup>.', 'Диагонали ромба перпендикулярны и делятся точкой пересечения пополам. Половины диагоналей: 12 и x; 12<sup>2</sup> + x<sup>2</sup> = 13<sup>2</sup>, x = 5. Вторая диагональ 10 см. S = ½ · 24 · 10 = 120 см<sup>2</sup>.', 'The diagonals of a rhombus are perpendicular and bisect each other. Half-diagonals: 12 and x; 12<sup>2</sup> + x<sup>2</sup> = 13<sup>2</sup>, so x = 5. The other diagonal is 10 cm. S = ½ · 24 · 10 = 120 cm<sup>2</sup>.') },
      { q: L('Teng yonli trapetsiyaning asoslari 22 va 10, yon tomoni 10. Yuzini toping.', 'Основания равнобедренной трапеции 22 и 10, боковая сторона 10. Найдите площадь.', 'An isosceles trapezium has bases 22 and 10 and legs 10. Find its area.'),
        s: L('Kichik asos uchlaridan balandliklar tushiramiz. Katta asosdan har ikki chetda (22 − 10) / 2 = 6 qoladi. h<sup>2</sup> = 10<sup>2</sup> − 6<sup>2</sup> = 64, h = 8. S = (22 + 10) / 2 · 8 = 16 · 8 = 128.', 'Опустим высоты из концов меньшего основания. По краям большего основания остаётся по (22 − 10) / 2 = 6. h<sup>2</sup> = 10<sup>2</sup> − 6<sup>2</sup> = 64, h = 8. S = (22 + 10) / 2 · 8 = 16 · 8 = 128.', 'Drop heights from the ends of the shorter base. Each end of the longer base has (22 − 10) / 2 = 6 left over. h<sup>2</sup> = 10<sup>2</sup> − 6<sup>2</sup> = 64, so h = 8. S = (22 + 10) / 2 · 8 = 16 · 8 = 128.') },
      { q: L('Tomonlari 7, 24 va 25 bo‘lgan uchburchak to‘g‘ri burchaklimi? Yuzini toping.', 'Является ли треугольник со сторонами 7, 24 и 25 прямоугольным? Найдите площадь.', 'Is the triangle with sides 7, 24 and 25 right-angled? Find its area.'),
        s: L('7<sup>2</sup> + 24<sup>2</sup> = 49 + 576 = 625 = 25<sup>2</sup>. Teskari teoremaga ko‘ra uchburchak to‘g‘ri burchakli, katetlari 7 va 24. S = ½ · 7 · 24 = 84. Geron formulasi bilan tekshiramiz: p = 28, S = √(28 · 21 · 4 · 3) = √7056 = 84.', '7<sup>2</sup> + 24<sup>2</sup> = 49 + 576 = 625 = 25<sup>2</sup>. По обратной теореме треугольник прямоугольный, катеты 7 и 24. S = ½ · 7 · 24 = 84. Проверим по Герону: p = 28, S = √(28 · 21 · 4 · 3) = √7056 = 84.', '7<sup>2</sup> + 24<sup>2</sup> = 49 + 576 = 625 = 25<sup>2</sup>. By the converse it is right-angled with legs 7 and 24. S = ½ · 7 · 24 = 84. Check with Heron: p = 28, S = √(28 · 21 · 4 · 3) = √7056 = 84.') }
    ] },
    { kind: 'table', h: L('Yuzlar formulalari jadvali', 'Таблица формул площадей', 'Table of area formulas'), table: {
      head: [L('Shakl', 'Фигура', 'Figure'), L('Formula', 'Формула', 'Formula'), L('Nima kerak', 'Что нужно', 'What you need')],
      rows: [
        [L('kvadrat', 'квадрат', 'square'), L('S = a<sup>2</sup> yoki d<sup>2</sup>/2', 'S = a<sup>2</sup> или d<sup>2</sup>/2', 'S = a<sup>2</sup> or d<sup>2</sup>/2'), L('tomon yoki diagonal', 'сторона или диагональ', 'side or diagonal')],
        [L('to‘g‘ri to‘rtburchak', 'прямоугольник', 'rectangle'), 'S = ab', L('ikki qo‘shni tomon', 'две смежные стороны', 'two adjacent sides')],
        [L('parallelogramm', 'параллелограмм', 'parallelogram'), 'S = a · h', L('tomon va unga balandlik', 'сторона и высота к ней', 'a side and its height')],
        [L('uchburchak', 'треугольник', 'triangle'), L('S = ½ a h', 'S = ½ a h', 'S = ½ a h'), L('tomon va unga balandlik', 'сторона и высота к ней', 'a side and its height')],
        [L('to‘g‘ri burchakli uchburchak', 'прямоугольный треугольник', 'right triangle'), L('S = ½ ab', 'S = ½ ab', 'S = ½ ab'), L('ikki katet', 'два катета', 'the two legs')],
        [L('romb', 'ромб', 'rhombus'), L('S = ½ d<sub>1</sub>d<sub>2</sub>', 'S = ½ d<sub>1</sub>d<sub>2</sub>', 'S = ½ d<sub>1</sub>d<sub>2</sub>'), L('ikki diagonal', 'две диагонали', 'both diagonals')],
        [L('trapetsiya', 'трапеция', 'trapezium'), 'S = (a + b)/2 · h', L('asoslar va balandlik', 'основания и высота', 'bases and height')],
        [L('ixtiyoriy uchburchak', 'любой треугольник', 'any triangle'), L('Geron: √(p(p − a)(p − b)(p − c))', 'Герон: √(p(p − a)(p − b)(p − c))', 'Heron: √(p(p − a)(p − b)(p − c))'), L('uch tomon', 'три стороны', 'three sides')]
      ] }, after: [
      L('9-sinfda bu jadvalga yana bitta qator qo‘shiladi: S = ½ ab sin C — ikki tomon va ular orasidagi burchak bo‘yicha yuz. Uni t9 mavzusida isbotlaymiz.', 'В 9 классе к таблице добавится ещё одна строка: S = ½ ab sin C — площадь по двум сторонам и углу между ними. Мы докажем её в теме t9.', 'In grade 9 one more row joins this table: S = ½ ab sin C, the area from two sides and the angle between them. We prove it in topic t9.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Gipotenuzani adashtirish.</b> c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> da c — har doim to‘g‘ri burchak qarshisidagi eng uzun tomon. Katet topilayotganda kvadratlar <i>ayiriladi</i>: b<sup>2</sup> = c<sup>2</sup> − a<sup>2</sup>.', '<b>Путать гипотенузу.</b> В c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> c — всегда самая длинная сторона против прямого угла. При поиске катета квадраты <i>вычитаются</i>: b<sup>2</sup> = c<sup>2</sup> − a<sup>2</sup>.', '<b>Mixing up the hypotenuse.</b> In c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>, c is always the longest side, opposite the right angle. When finding a leg you <i>subtract</i> squares: b<sup>2</sup> = c<sup>2</sup> − a<sup>2</sup>.'),
      L('<b>√(a<sup>2</sup> + b<sup>2</sup>) = a + b deb yozish.</b> Bu katta xato: √(9 + 16) = 5, lekin 3 + 4 = 7.', '<b>Писать √(a<sup>2</sup> + b<sup>2</sup>) = a + b.</b> Грубая ошибка: √(9 + 16) = 5, а 3 + 4 = 7.', '<b>Writing √(a<sup>2</sup> + b<sup>2</sup>) = a + b.</b> A serious error: √(9 + 16) = 5, but 3 + 4 = 7.'),
      L('<b>Yon tomonni balandlik deb olish.</b> Parallelogramm yuzi a · b emas, a · h. Faqat to‘g‘ri to‘rtburchakda yon tomon balandlikka teng.', '<b>Брать боковую сторону вместо высоты.</b> Площадь параллелограмма не a · b, а a · h. Только у прямоугольника боковая сторона равна высоте.', '<b>Using a slanted side as the height.</b> A parallelogram’s area is a · h, not a · b. Only in a rectangle is the side equal to the height.'),
      L('<b>½ ni unutish.</b> Uchburchak va romb formulalarida yarim ko‘paytuvchi bor. Tekshirish: uchburchak o‘zi joylashgan to‘g‘ri to‘rtburchakning yarmini egallaydi.', '<b>Забывать ½.</b> В формулах треугольника и ромба есть множитель одна вторая. Проверка: треугольник занимает половину описанного прямоугольника.', '<b>Forgetting the ½.</b> The triangle and rhombus formulas contain a half. Check: a triangle fills half of the rectangle around it.'),
      L('<b>Birliklarni aralashtirish.</b> Tomonlar cm va m da berilsa, avval bir xil birlikka o‘tkazing. Yuz javobi kvadrat birlikda: 1 m<sup>2</sup> = 10 000 cm<sup>2</sup>, 100 emas!', '<b>Смешивать единицы.</b> Если стороны даны в см и м, сначала приведите их к одной единице. Площадь — в квадратных единицах: 1 м<sup>2</sup> = 10 000 см<sup>2</sup>, а не 100!', '<b>Mixing units.</b> If sides are given in cm and m, convert first. Areas are in square units: 1 m<sup>2</sup> = 10,000 cm<sup>2</sup>, not 100!')
    ] },
    { kind: 'life', h: L('Hayotda Pifagor va yuzlar', 'Пифагор и площади в жизни', 'Pythagoras and area in real life'), p: [
      L('<b>Ekran diagonali.</b> 16 : 9 formatli 55 dyuymli televizorda eni va bo‘yi 16x va 9x. Pifagor bo‘yicha 256x<sup>2</sup> + 81x<sup>2</sup> = 55<sup>2</sup>, x ≈ 3,02, ya’ni eni ≈ 48 dyuym (122 cm), bo‘yi ≈ 27 dyuym (69 cm). Mebel tanlashda aynan shu o‘lchamlar kerak.', '<b>Диагональ экрана.</b> У телевизора 55 дюймов формата 16 : 9 ширина и высота 16x и 9x. По Пифагору 256x<sup>2</sup> + 81x<sup>2</sup> = 55<sup>2</sup>, x ≈ 3,02, то есть ширина ≈ 48 дюймов (122 см), высота ≈ 27 дюймов (69 см). Именно эти размеры нужны при выборе мебели.', '<b>Screen diagonals.</b> A 55-inch 16 : 9 television has width 16x and height 9x. By Pythagoras 256x<sup>2</sup> + 81x<sup>2</sup> = 55<sup>2</sup>, so x ≈ 3.02: the width is about 48 inches (122 cm) and the height about 27 inches (69 cm). These are the numbers you need when choosing furniture.'),
      L('<b>Qurilish.</b> Usta poydevor burchagi to‘g‘riligini «3–4–5 qoidasi» bilan tekshiradi: bir devor bo‘ylab 3 m, ikkinchisi bo‘ylab 4 m o‘lchaydi; uchlar orasidagi masofa roppa-rosa 5 m bo‘lsa, burchak 90°. Narvonni devorga suyashda ham Pifagor kerak: 5 m li narvon pastki uchi devordan 1,4 m uzoqda bo‘lsa, u devorga √(25 − 1,96) ≈ 4,8 m balandlikda tegadi.', '<b>Строительство.</b> Мастер проверяет прямой угол фундамента «правилом 3–4–5»: откладывает 3 м по одной стене и 4 м по другой; если между концами ровно 5 м, угол прямой. Пифагор нужен и для лестницы: 5-метровая лестница, нижний конец которой в 1,4 м от стены, касается стены на высоте √(25 − 1,96) ≈ 4,8 м.', '<b>Building.</b> A builder checks a foundation corner with the “3–4–5 rule”: measure 3 m along one wall and 4 m along the other; if the ends are exactly 5 m apart, the corner is square. Ladders need Pythagoras too: a 5 m ladder with its foot 1.4 m from the wall reaches √(25 − 1.96) ≈ 4.8 m up the wall.'),
      L('<b>Ta’mir va dehqonchilik.</b> Devorni bo‘yash uchun bo‘yoq miqdori yuzga qarab olinadi (masalan, 1 litr 8 m<sup>2</sup> ga). Fermer trapetsiya shaklidagi dalaga qancha urug‘ sepishini yuz bo‘yicha hisoblaydi: 1 gektar = 10 000 m<sup>2</sup>.', '<b>Ремонт и сельское хозяйство.</b> Краску для стены покупают по площади (например, 1 литр на 8 м<sup>2</sup>). Фермер рассчитывает, сколько семян посеять на трапециевидном поле, по его площади: 1 гектар = 10 000 м<sup>2</sup>.', '<b>Repairs and farming.</b> Paint is bought by area (say 1 litre per 8 m<sup>2</sup>). A farmer works out how much seed a trapezium-shaped field needs from its area: 1 hectare = 10,000 m<sup>2</sup>.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Pifagor teoremasining 400 dan ortiq turli isboti ma’lum. Ulardan birini 1876-yilda AQShning bo‘lajak prezidenti Jeyms Garfild trapetsiya yuzi orqali topgan.', 'Известно более 400 различных доказательств теоремы Пифагора. Одно из них в 1876 году нашёл будущий президент США Джеймс Гарфилд — через площадь трапеции.', 'More than 400 different proofs of Pythagoras’ theorem are known. One was found in 1876 by future US president James Garfield, using the area of a trapezium.'),
      L('Pifagor uchliklari cheksiz ko‘p: istalgan m &gt; n uchun a = m<sup>2</sup> − n<sup>2</sup>, b = 2mn, c = m<sup>2</sup> + n<sup>2</sup> uchlik beradi. m = 2, n = 1 da 3, 4, 5 chiqadi.', 'Пифагоровых троек бесконечно много: для любых m &gt; n числа a = m<sup>2</sup> − n<sup>2</sup>, b = 2mn, c = m<sup>2</sup> + n<sup>2</sup> дают тройку. При m = 2, n = 1 получается 3, 4, 5.', 'There are infinitely many Pythagorean triples: for any m &gt; n, a = m<sup>2</sup> − n<sup>2</sup>, b = 2mn, c = m<sup>2</sup> + n<sup>2</sup> form one. With m = 2, n = 1 you get 3, 4, 5.'),
      L('Teorema faqat kvadratlar uchun emas: katetlarga va gipotenuzaga o‘xshash har qanday shakllar (yarim doiralar, uchburchaklar) qursak ham, gipotenuzadagi shakl yuzi qolgan ikkitasi yig‘indisiga teng bo‘ladi. Buni t2 mavzusida k<sup>2</sup> qoidasi bilan tushunamiz.', 'Теорема верна не только для квадратов: если построить на катетах и гипотенузе любые подобные фигуры (полукруги, треугольники), площадь фигуры на гипотенузе равна сумме двух других. Это мы поймём в теме t2 с правилом k<sup>2</sup>.', 'The theorem is not only about squares: build any similar shapes (semicircles, triangles) on the legs and the hypotenuse, and the shape on the hypotenuse has the area of the other two combined. We will see why in topic t2 with the k<sup>2</sup> rule.'),
      L('Ferma 1637-yilda a<sup>n</sup> + b<sup>n</sup> = c<sup>n</sup> tenglamaning n &gt; 2 da natural yechimi yo‘q deb yozgan. Bu «Fermaning buyuk teoremasi» faqat 1994-yilda Endryu Uayls tomonidan isbotlandi.', 'Ферма в 1637 году написал, что уравнение a<sup>n</sup> + b<sup>n</sup> = c<sup>n</sup> при n &gt; 2 не имеет натуральных решений. Эту «Великую теорему Ферма» доказал лишь в 1994 году Эндрю Уайлс.', 'In 1637 Fermat wrote that a<sup>n</sup> + b<sup>n</sup> = c<sup>n</sup> has no whole-number solutions for n &gt; 2. This “Fermat’s Last Theorem” was proved only in 1994, by Andrew Wiles.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Gipotenuza 17, bir katet 8. Ikkinchi katet va yuz?', '1. Гипотенуза 17, один катет 8. Второй катет и площадь?', '1. Hypotenuse 17, one leg 8. The other leg and the area?'),
      L('2. Kvadratning diagonali 10 cm. Uning yuzi?', '2. Диагональ квадрата 10 см. Его площадь?', '2. A square has diagonal 10 cm. Its area?'),
      L('3. Tomonlari 6, 8 va 11 bo‘lgan uchburchak qanday: o‘tkir, to‘g‘ri yoki o‘tmas burchakli?', '3. Каков треугольник со сторонами 6, 8 и 11: остро-, прямо- или тупоугольный?', '3. Is the triangle with sides 6, 8 and 11 acute, right or obtuse?'),
      L('4. Parallelogrammning tomonlari 10 va 6, katta tomonga balandlik 3. Kichik tomonga balandlik?', '4. Стороны параллелограмма 10 и 6, высота к большей стороне 3. Высота к меньшей?', '4. A parallelogram has sides 10 and 6, and the height to the longer side is 3. The height to the shorter side?')
    ], after: [
      L('Javoblar: 1) 15 va 60; 2) d<sup>2</sup>/2 = 50 cm<sup>2</sup>; 3) 121 &gt; 36 + 64 = 100 — o‘tmas burchakli; 4) S = 30, 30 : 6 = 5.', 'Ответы: 1) 15 и 60; 2) d<sup>2</sup>/2 = 50 см<sup>2</sup>; 3) 121 &gt; 36 + 64 = 100 — тупоугольный; 4) S = 30, 30 : 6 = 5.', 'Answers: 1) 15 and 60; 2) d<sup>2</sup>/2 = 50 cm<sup>2</sup>; 3) 121 &gt; 36 + 64 = 100, so obtuse; 4) S = 30, and 30 ÷ 6 = 5.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('To‘g‘ri burchakli uchburchakda c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>; katet topish uchun kvadratlar ayiriladi.', 'В прямоугольном треугольнике c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>; для катета квадраты вычитаются.', 'In a right triangle c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>; to find a leg, subtract squares.'),
      L('Teskari teorema uchburchak to‘g‘ri burchakli ekanini aniqlaydi; c<sup>2</sup> ni a<sup>2</sup> + b<sup>2</sup> bilan solishtirib, burchak turini bilamiz.', 'Обратная теорема распознаёт прямоугольный треугольник; сравнивая c<sup>2</sup> с a<sup>2</sup> + b<sup>2</sup>, узнаём вид угла.', 'The converse detects right triangles; comparing c<sup>2</sup> with a<sup>2</sup> + b<sup>2</sup> tells the type of angle.'),
      L('Yuzlar: parallelogramm ah, uchburchak ½ah, romb ½d<sub>1</sub>d<sub>2</sub>, trapetsiya (a + b)h/2.', 'Площади: параллелограмм ah, треугольник ½ah, ромб ½d<sub>1</sub>d<sub>2</sub>, трапеция (a + b)h/2.', 'Areas: parallelogram ah, triangle ½ah, rhombus ½d<sub>1</sub>d<sub>2</sub>, trapezium (a + b)h/2.'),
      L('Barcha formulalar «kesib, qayta joylash» g‘oyasidan kelib chiqadi.', 'Все формулы выводятся из идеи «разрезать и переложить».', 'All the formulas come from the idea of “cut and rearrange”.'),
      L('Ko‘p masalada yetishmagan balandlik Pifagor teoremasi bilan topiladi.', 'Во многих задачах недостающая высота находится по теореме Пифагора.', 'In many problems the missing height is found with Pythagoras.'),
      L('Bu ikki qurol 9-sinfning o‘xshashlik va trigonometriya mavzularida doimo ishlatiladi.', 'Эти два инструмента постоянно используются в темах 9 класса о подобии и тригонометрии.', 'These two tools are used constantly in grade 9 similarity and trigonometry.')
    ] }
  ] });

  // ---------- t2. O‘xshash ko‘pburchaklar va uchburchaklar ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Bir xil shakl — har xil o‘lcham', 'Одна форма — разные размеры', 'Same shape, different size'), p: [
      L('Telefoningizda suratni ikki barmoq bilan kattalashtirsangiz, rasm kattalashadi, lekin undagi odam «cho‘zilib» yoki «yassilanib» qolmaydi. Xarita, binoning chizmasi, o‘yinchoq mashina va haqiqiy mashina, pasport surati va uning kattalashtirilgan nusxasi — hammasida shakl saqlanadi, faqat o‘lcham o‘zgaradi. Geometriyada bunday shakllar <b>o‘xshash</b> deyiladi.', 'Если раздвинуть фото на телефоне двумя пальцами, изображение увеличится, но человек на нём не «вытянется» и не «сплющится». Карта, чертёж здания, игрушечная и настоящая машина, фото на паспорт и его увеличенная копия — везде форма сохраняется, меняется только размер. В геометрии такие фигуры называют <b>подобными</b>.', 'When you spread two fingers on a phone photo, the picture grows, but the person in it is not “stretched” or “squashed”. A map, a building plan, a toy car and the real car, a passport photo and its enlargement — in each case the shape is kept and only the size changes. In geometry such figures are called <b>similar</b>.'),
      L('Lekin «shakli bir xil» degani matematik jihatdan nima? Faqat burchaklar tengligi yetarlimi? Yo‘q: kvadrat va cho‘ziq to‘g‘ri to‘rtburchakning barcha burchaklari 90°, ammo ular o‘xshash emas. Faqat tomonlar nisbati yetarlimi? Ham yo‘q: tomoni 5 bo‘lgan kvadrat va tomoni 5 bo‘lgan qiyshiq romb o‘xshash emas. Ikkala shart birga kerak.', 'Но что значит «одинаковая форма» математически? Достаточно ли равенства углов? Нет: у квадрата и вытянутого прямоугольника все углы по 90°, но они не подобны. Достаточно ли пропорциональности сторон? Тоже нет: квадрат со стороной 5 и косой ромб со стороной 5 не подобны. Нужны оба условия сразу.', 'But what does “the same shape” mean mathematically? Is it enough for the angles to match? No: a square and a long rectangle both have all angles 90°, yet they are not similar. Is it enough for the sides to be in proportion? No again: a square of side 5 and a slanted rhombus of side 5 are not similar. Both conditions are needed together.'),
      L('Bu mavzuda o‘xshashlikning aniq ta’rifini beramiz, o‘xshashlik koeffitsiyenti k ni kiritamiz va eng muhim xossalarni isbotlaymiz: perimetrlar k marta, yuzlar esa <b>k<sup>2</sup></b> marta farq qiladi. Bu oddiy ko‘ringan qoida pitsa narxidan tortib fil va sichqonning tana tuzilishigacha ko‘p narsani tushuntiradi.', 'В этой теме мы дадим точное определение подобия, введём коэффициент подобия k и докажем главные свойства: периметры отличаются в k раз, а площади — в <b>k<sup>2</sup></b> раз. Это простое на вид правило объясняет многое — от цены пиццы до строения тела слона и мыши.', 'In this topic we give a precise definition of similarity, introduce the scale factor k and prove the key properties: perimeters differ by a factor of k, but areas by <b>k<sup>2</sup></b>. This simple-looking rule explains many things, from pizza prices to why elephants and mice are built so differently.')
    ] },
    { kind: 'def', h: L('O‘xshash ko‘pburchaklar ta’rifi', 'Определение подобных многоугольников', 'Definition of similar polygons'), p: [
      L('Ikki ko‘pburchak <b>o‘xshash</b> deyiladi, agar ularning uchlari orasida shunday moslik o‘rnatish mumkin bo‘lsaki, <b>mos burchaklar teng</b> va <b>mos tomonlar proporsional</b> bo‘lsa. Uchburchaklar uchun: △ABC ~ △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub>, agar ∠A = ∠A<sub>1</sub>, ∠B = ∠B<sub>1</sub>, ∠C = ∠C<sub>1</sub> va A<sub>1</sub>B<sub>1</sub>/AB = B<sub>1</sub>C<sub>1</sub>/BC = A<sub>1</sub>C<sub>1</sub>/AC = k.', 'Два многоугольника называются <b>подобными</b>, если между их вершинами можно установить соответствие, при котором <b>соответственные углы равны</b>, а <b>соответственные стороны пропорциональны</b>. Для треугольников: △ABC ~ △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub>, если ∠A = ∠A<sub>1</sub>, ∠B = ∠B<sub>1</sub>, ∠C = ∠C<sub>1</sub> и A<sub>1</sub>B<sub>1</sub>/AB = B<sub>1</sub>C<sub>1</sub>/BC = A<sub>1</sub>C<sub>1</sub>/AC = k.', 'Two polygons are <b>similar</b> if their vertices can be matched so that <b>corresponding angles are equal</b> and <b>corresponding sides are proportional</b>. For triangles: △ABC ~ △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> if ∠A = ∠A<sub>1</sub>, ∠B = ∠B<sub>1</sub>, ∠C = ∠C<sub>1</sub> and A<sub>1</sub>B<sub>1</sub>/AB = B<sub>1</sub>C<sub>1</sub>/BC = A<sub>1</sub>C<sub>1</sub>/AC = k.')
    ], list: [
      L('<b>k — o‘xshashlik koeffitsiyenti</b>: ikkinchi shakl tomonining birinchisining mos tomoniga nisbati. k &gt; 1 — kattalashtirish, 0 &lt; k &lt; 1 — kichraytirish, k = 1 — shakllar teng.', '<b>k — коэффициент подобия</b>: отношение стороны второй фигуры к соответственной стороне первой. k &gt; 1 — увеличение, 0 &lt; k &lt; 1 — уменьшение, k = 1 — фигуры равны.', '<b>k is the scale factor</b>: the ratio of a side of the second figure to the matching side of the first. k &gt; 1 enlarges, 0 &lt; k &lt; 1 shrinks, k = 1 means the figures are congruent.'),
      L('<b>Mos (o‘xshash) tomonlar</b> — teng burchaklar qarshisida yotgan tomonlar. Belgilashda harflar tartibi muhim: △ABC ~ △KLM yozuvida A ↔ K, B ↔ L, C ↔ M.', '<b>Сходственные стороны</b> лежат против равных углов. В записи важен порядок букв: в △ABC ~ △KLM A ↔ K, B ↔ L, C ↔ M.', '<b>Corresponding sides</b> lie opposite equal angles. The order of letters matters: △ABC ~ △KLM means A ↔ K, B ↔ L, C ↔ M.'),
      L('Barcha kvadratlar, barcha teng tomonli uchburchaklar, barcha muntazam n-burchaklar va barcha aylanalar o‘zaro o‘xshash.', 'Все квадраты, все равносторонние треугольники, все правильные n-угольники и все окружности подобны между собой.', 'All squares, all equilateral triangles, all regular n-gons and all circles are similar to each other.'),
      L('O‘xshashlik <b>tranzitiv</b>: F<sub>1</sub> ~ F<sub>2</sub> va F<sub>2</sub> ~ F<sub>3</sub> bo‘lsa, F<sub>1</sub> ~ F<sub>3</sub>, koeffitsiyentlar esa ko‘paytiriladi.', 'Подобие <b>транзитивно</b>: если F<sub>1</sub> ~ F<sub>2</sub> и F<sub>2</sub> ~ F<sub>3</sub>, то F<sub>1</sub> ~ F<sub>3</sub>, а коэффициенты перемножаются.', 'Similarity is <b>transitive</b>: if F<sub>1</sub> ~ F<sub>2</sub> and F<sub>2</sub> ~ F<sub>3</sub>, then F<sub>1</sub> ~ F<sub>3</sub>, and the factors multiply.')
    ] },
    { kind: 'history', h: L('Tarixdan: Yevklidning VI kitobi', 'Из истории: шестая книга Евклида', 'History: Euclid’s Book VI'), p: [
      L('O‘xshashlik g‘oyasini birinchi bo‘lib amalda qo‘llaganlardan biri <b>Fales Miletlik</b> (miloddan avvalgi VI asr) edi. Ammo uni qat’iy nazariyaga aylantirgan <b>Yevklid</b> bo‘ldi: «Negizlar»ning <b>VI kitobi</b> butunlay o‘xshash shakllarga bag‘ishlangan. U yerda «o‘xshash to‘g‘ri chiziqli shakllar — burchaklari birma-bir teng va teng burchaklar atrofidagi tomonlari proporsional shakllar» degan ta’rif berilgan. Yevklid o‘xshash uchburchaklar yuzlari mos tomonlarining «ikki karrali nisbati»da, ya’ni bugungi tilda k<sup>2</sup> nisbatda ekanini isbotlagan.', 'Одним из первых, кто применил идею подобия на практике, был <b>Фалес Милетский</b> (VI век до н. э.). Но строгую теорию построил <b>Евклид</b>: <b>VI книга</b> «Начал» целиком посвящена подобным фигурам. Там дано определение: подобные прямолинейные фигуры — это фигуры, у которых углы соответственно равны, а стороны при равных углах пропорциональны. Евклид доказал, что площади подобных треугольников относятся как «двойное отношение» сторон, то есть, по-современному, как k<sup>2</sup>.', 'One of the first to use similarity in practice was <b>Thales of Miletus</b> (6th century BC). But it was <b>Euclid</b> who turned it into a strict theory: <b>Book VI</b> of the Elements is devoted entirely to similar figures. It defines similar rectilinear figures as those with angles equal one by one and with proportional sides about the equal angles. Euclid proved that the areas of similar triangles are in the “duplicate ratio” of their sides — in today’s language, in the ratio k<sup>2</sup>.'),
      L('Proporsiyalar nazariyasining o‘zi Yevkliddan oldin <b>Evdoks Knidlik</b> tomonidan ishlab chiqilgan va V kitobda bayon etilgan. Keyinchalik o‘xshashlik xaritachilik va me’morchilikda asosiy vosita bo‘ldi. Movarounnahrda masjid va madrasalar loyihasi kichik masshtabli chizmalarda tayyorlanib, so‘ng yerga ko‘chirilgan; <b>G‘iyosiddin Jamshid al-Koshiy</b> (XV asr) «Arifmetika kaliti» asarida gumbaz va ravoqlar o‘lchamlarini hisoblash usullarini bergan.', 'Сама теория пропорций была разработана ещё до Евклида <b>Евдоксом Книдским</b> и изложена в V книге. Позже подобие стало главным инструментом картографии и архитектуры. В Мавераннахре мечети и медресе проектировали на чертежах в малом масштабе, а затем переносили на землю; <b>Гиясиддин Джамшид аль-Каши</b> (XV век) в «Ключе арифметики» дал способы расчёта размеров куполов и арок.', 'The theory of proportion itself was developed before Euclid by <b>Eudoxus of Cnidus</b> and is set out in Book V. Later similarity became the basic tool of map-making and architecture. In Transoxiana mosques and madrasas were designed on small-scale drawings and then transferred to the ground; <b>Jamshid al-Kashi</b> (15th century), in his Key to Arithmetic, gave methods for computing the sizes of domes and arches.')
    ] },
    { kind: 'rule', h: L('Perimetrlar nisbati k ga teng', 'Отношение периметров равно k', 'Perimeters are in ratio k'), p: [
      L('<b>Teorema.</b> O‘xshash ko‘pburchaklar perimetrlarining nisbati o‘xshashlik koeffitsiyentiga teng: <b>P<sub>2</sub> / P<sub>1</sub> = k</b>.', '<b>Теорема.</b> Отношение периметров подобных многоугольников равно коэффициенту подобия: <b>P<sub>2</sub> / P<sub>1</sub> = k</b>.', '<b>Theorem.</b> The ratio of the perimeters of similar polygons equals the scale factor: <b>P<sub>2</sub> / P<sub>1</sub> = k</b>.'),
      L('<b>Isbot.</b> Birinchi ko‘pburchak tomonlari a<sub>1</sub>, a<sub>2</sub>, …, a<sub>n</sub> bo‘lsin. U holda ikkinchisining tomonlari ka<sub>1</sub>, ka<sub>2</sub>, …, ka<sub>n</sub>. Ikkinchi perimetr: ka<sub>1</sub> + ka<sub>2</sub> + … + ka<sub>n</sub> = k(a<sub>1</sub> + a<sub>2</sub> + … + a<sub>n</sub>) = k · P<sub>1</sub>. Umumiy ko‘paytuvchini qavsdan chiqarish — butun isbot shu.', '<b>Доказательство.</b> Пусть стороны первого многоугольника a<sub>1</sub>, a<sub>2</sub>, …, a<sub>n</sub>. Тогда стороны второго ka<sub>1</sub>, ka<sub>2</sub>, …, ka<sub>n</sub>. Второй периметр: ka<sub>1</sub> + ka<sub>2</sub> + … + ka<sub>n</sub> = k(a<sub>1</sub> + a<sub>2</sub> + … + a<sub>n</sub>) = k · P<sub>1</sub>. Вынести общий множитель за скобки — вот и всё доказательство.', '<b>Proof.</b> Let the first polygon have sides a<sub>1</sub>, a<sub>2</sub>, …, a<sub>n</sub>. Then the second has sides ka<sub>1</sub>, ka<sub>2</sub>, …, ka<sub>n</sub>. Its perimeter is ka<sub>1</sub> + ka<sub>2</sub> + … + ka<sub>n</sub> = k(a<sub>1</sub> + a<sub>2</sub> + … + a<sub>n</sub>) = k · P<sub>1</sub>. Taking out the common factor is the whole proof.'),
      L('Xuddi shu sababli o‘xshash uchburchaklarning <b>barcha mos chiziqli elementlari</b> — balandliklar, medianalar, bissektrisalar, ichki va tashqi chizilgan aylanalar radiuslari — ham k nisbatda bo‘ladi. Agar ikki o‘xshash uchburchakning mos medianalari 6 va 9 bo‘lsa, k = 1,5, va perimetrlari ham 1,5 marta farq qiladi.', 'По той же причине <b>все соответственные линейные элементы</b> подобных треугольников — высоты, медианы, биссектрисы, радиусы вписанной и описанной окружностей — тоже относятся как k. Если соответственные медианы двух подобных треугольников 6 и 9, то k = 1,5, и периметры тоже различаются в 1,5 раза.', 'For the same reason <b>all corresponding lengths</b> of similar triangles — heights, medians, angle bisectors, the radii of the inscribed and circumscribed circles — are also in ratio k. If corresponding medians of two similar triangles are 6 and 9, then k = 1.5 and the perimeters also differ by a factor of 1.5.')
    ] },
    { kind: 'rule', h: L('Yuzlar nisbati k² ga teng', 'Отношение площадей равно k²', 'Areas are in ratio k²'), p: [
      L('<b>Teorema.</b> O‘xshash uchburchaklar (va ko‘pburchaklar) yuzlarining nisbati o‘xshashlik koeffitsiyentining kvadratiga teng: <b>S<sub>2</sub> / S<sub>1</sub> = k<sup>2</sup></b>.', '<b>Теорема.</b> Отношение площадей подобных треугольников (и многоугольников) равно квадрату коэффициента подобия: <b>S<sub>2</sub> / S<sub>1</sub> = k<sup>2</sup></b>.', '<b>Theorem.</b> The ratio of the areas of similar triangles (and polygons) equals the square of the scale factor: <b>S<sub>2</sub> / S<sub>1</sub> = k<sup>2</sup></b>.'),
      L('<b>Isbot (uchburchak uchun).</b> △ABC da AC asos va unga h balandlik bo‘lsin; S<sub>1</sub> = ½ · AC · h. O‘xshash uchburchakda mos asos k · AC, mos balandlik esa (yuqoridagi teoremaga ko‘ra) k · h. Demak, S<sub>2</sub> = ½ · (k · AC) · (k · h) = k<sup>2</sup> · ½ · AC · h = k<sup>2</sup> · S<sub>1</sub>. Ko‘pburchakni esa diagonallar bilan o‘xshash uchburchaklarga bo‘lamiz: har bir bo‘lak yuzi k<sup>2</sup> marta oshadi, demak yig‘indi ham.', '<b>Доказательство (для треугольника).</b> Пусть в △ABC основание AC и высота к нему h; S<sub>1</sub> = ½ · AC · h. В подобном треугольнике соответственное основание k · AC, а соответственная высота (по предыдущей теореме) k · h. Значит, S<sub>2</sub> = ½ · (k · AC) · (k · h) = k<sup>2</sup> · ½ · AC · h = k<sup>2</sup> · S<sub>1</sub>. Многоугольник же разобьём диагоналями на подобные треугольники: площадь каждой части растёт в k<sup>2</sup> раз, значит, и сумма.', '<b>Proof (for a triangle).</b> In △ABC let AC be the base with height h; S<sub>1</sub> = ½ · AC · h. In the similar triangle the matching base is k · AC and the matching height is k · h (by the previous theorem). So S<sub>2</sub> = ½ · (k · AC) · (k · h) = k<sup>2</sup> · ½ · AC · h = k<sup>2</sup> · S<sub>1</sub>. For a polygon, cut it by diagonals into similar triangles: each piece’s area grows by k<sup>2</sup>, so the total does too.'),
      L('<b>Intuitsiya.</b> Kvadrat tomonini 3 marta oshirsak, kattasiga kichik kvadratdan 3 qator, har qatorda 3 tadan — jami 9 ta joylashadi. Yuz ikki yo‘nalishda — eni va bo‘yi bo‘yicha — o‘sadi, shuning uchun k bir emas, ikki marta ko‘paytiriladi. Fazoda hajm uch yo‘nalishda o‘sadi va k<sup>3</sup> marta oshadi.', '<b>Интуиция.</b> Если сторону квадрата увеличить в 3 раза, в большой квадрат поместится 3 ряда по 3 маленьких — всего 9. Площадь растёт в двух направлениях — в ширину и в высоту, поэтому k умножается не один, а два раза. В пространстве объём растёт в трёх направлениях — в k<sup>3</sup> раз.', '<b>Intuition.</b> If you triple a square’s side, the big square holds 3 rows of 3 small ones — 9 in total. Area grows in two directions, width and height, so k is applied twice, not once. In space, volume grows in three directions, by k<sup>3</sup>.')
    ] },
    { kind: 'steps', h: L('O‘xshashlik masalasini yechish', 'Как решать задачу на подобие', 'Solving a similarity problem'), list: [
      L('1. Qaysi uch qaysi uchga mos ekanini aniqlang: teng burchaklarni juftlang. Mos tomonlar teng burchaklar qarshisida yotadi.', '1. Определите, какая вершина какой соответствует: сопоставьте равные углы. Сходственные стороны лежат против равных углов.', '1. Decide which vertex matches which by pairing equal angles. Corresponding sides lie opposite equal angles.'),
      L('2. Ikkala shakldan bir juft ma’lum mos tomonni oling va k ni toping: k = katta / kichik (yoki aksincha, lekin bir xil tartibda).', '2. Возьмите пару известных сходственных сторон и найдите k: k = большая / меньшая (или наоборот, но в одном порядке).', '2. Take one known pair of corresponding sides and find k = big / small (or the other way round, but stay consistent).'),
      L('3. Noma’lum uzunlik uchun: mos uzunlikni k ga ko‘paytiring (yoki bo‘ling).', '3. Для неизвестной длины: умножьте (или разделите) соответственную длину на k.', '3. For a missing length, multiply (or divide) the matching length by k.'),
      L('4. Perimetr uchun k, yuz uchun k<sup>2</sup> ishlating. Yuzlar nisbatidan k topish uchun ildiz chiqaring: k = √(S<sub>2</sub>/S<sub>1</sub>).', '4. Для периметра используйте k, для площади — k<sup>2</sup>. Чтобы найти k по отношению площадей, извлеките корень: k = √(S<sub>2</sub>/S<sub>1</sub>).', '4. Use k for perimeters and k<sup>2</sup> for areas. To get k from an area ratio, take the square root: k = √(S<sub>2</sub>/S<sub>1</sub>).'),
      L('5. Tekshiring: kattaroq shaklda barcha uzunliklar kattaroq chiqishi kerak.', '5. Проверьте: у большей фигуры все длины должны получиться больше.', '5. Check: every length of the bigger figure should come out bigger.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('△ABC ~ △KLM, AB = 4, BC = 6, AC = 8, KL = 10. LM va KM ni toping.', '△ABC ~ △KLM, AB = 4, BC = 6, AC = 8, KL = 10. Найдите LM и KM.', '△ABC ~ △KLM, AB = 4, BC = 6, AC = 8, KL = 10. Find LM and KM.'),
        s: L('Moslik: AB ↔ KL, BC ↔ LM, AC ↔ KM. k = KL / AB = 10 / 4 = 2,5. LM = 6 · 2,5 = 15, KM = 8 · 2,5 = 20. Tekshirish: 10 : 15 : 20 = 4 : 6 : 8 = 2 : 3 : 4.', 'Соответствие: AB ↔ KL, BC ↔ LM, AC ↔ KM. k = KL / AB = 10 / 4 = 2,5. LM = 6 · 2,5 = 15, KM = 8 · 2,5 = 20. Проверка: 10 : 15 : 20 = 4 : 6 : 8 = 2 : 3 : 4.', 'Matching: AB ↔ KL, BC ↔ LM, AC ↔ KM. k = KL / AB = 10 / 4 = 2.5. LM = 6 · 2.5 = 15 and KM = 8 · 2.5 = 20. Check: 10 : 15 : 20 = 4 : 6 : 8 = 2 : 3 : 4.') },
      { q: L('Ikki o‘xshash uchburchakning yuzlari 12 cm<sup>2</sup> va 75 cm<sup>2</sup>. Kichigining perimetri 14 cm. Kattasining perimetri qancha?', 'Площади двух подобных треугольников 12 см<sup>2</sup> и 75 см<sup>2</sup>. Периметр меньшего 14 см. Чему равен периметр большего?', 'Two similar triangles have areas 12 cm<sup>2</sup> and 75 cm<sup>2</sup>. The smaller has perimeter 14 cm. What is the larger one’s perimeter?'),
        s: L('k<sup>2</sup> = 75 / 12 = 25 / 4, k = 5 / 2 = 2,5. Perimetrlar k nisbatda: P = 14 · 2,5 = 35 cm. Diqqat: perimetrni 75/12 ga ko‘paytirish xato bo‘lardi.', 'k<sup>2</sup> = 75 / 12 = 25 / 4, k = 5 / 2 = 2,5. Периметры относятся как k: P = 14 · 2,5 = 35 см. Внимание: умножать периметр на 75/12 было бы ошибкой.', 'k<sup>2</sup> = 75 / 12 = 25 / 4, so k = 5 / 2 = 2.5. Perimeters are in ratio k: P = 14 · 2.5 = 35 cm. Careful: multiplying the perimeter by 75/12 would be wrong.') },
      { q: L('Xarita masshtabi 1 : 50 000. Xaritadagi ko‘l yuzi 6 cm<sup>2</sup>. Haqiqiy yuzi necha gektar?', 'Масштаб карты 1 : 50 000. Площадь озера на карте 6 см<sup>2</sup>. Какова настоящая площадь в гектарах?', 'A map has scale 1 : 50,000. A lake on it has area 6 cm<sup>2</sup>. What is its real area in hectares?'),
        s: L('k = 50 000, k<sup>2</sup> = 2 500 000 000. Haqiqiy yuz 6 · 2,5 · 10<sup>9</sup> = 1,5 · 10<sup>10</sup> cm<sup>2</sup>. 1 m<sup>2</sup> = 10<sup>4</sup> cm<sup>2</sup>, demak 1,5 · 10<sup>6</sup> m<sup>2</sup> = 150 ga. Boshqacha: xaritadagi 1 cm — 500 m, 1 cm<sup>2</sup> — 500 · 500 = 250 000 m<sup>2</sup> = 25 ga; 6 · 25 = 150 ga.', 'k = 50 000, k<sup>2</sup> = 2 500 000 000. Настоящая площадь 6 · 2,5 · 10<sup>9</sup> = 1,5 · 10<sup>10</sup> см<sup>2</sup>. 1 м<sup>2</sup> = 10<sup>4</sup> см<sup>2</sup>, значит, 1,5 · 10<sup>6</sup> м<sup>2</sup> = 150 га. Иначе: 1 см на карте — 500 м, 1 см<sup>2</sup> — 500 · 500 = 250 000 м<sup>2</sup> = 25 га; 6 · 25 = 150 га.', 'k = 50,000 and k<sup>2</sup> = 2,500,000,000. Real area 6 · 2.5 · 10<sup>9</sup> = 1.5 · 10<sup>10</sup> cm<sup>2</sup>. Since 1 m<sup>2</sup> = 10<sup>4</sup> cm<sup>2</sup>, that is 1.5 · 10<sup>6</sup> m<sup>2</sup> = 150 ha. Another way: 1 cm on the map is 500 m, so 1 cm<sup>2</sup> is 500 · 500 = 250,000 m<sup>2</sup> = 25 ha; 6 · 25 = 150 ha.') },
      { q: L('Ikki muntazam oltiburchakning tomonlari 3 va 5. Ularning yuzlari nisbatini toping. Ular o‘xshashmi?', 'Стороны двух правильных шестиугольников 3 и 5. Найдите отношение их площадей. Подобны ли они?', 'Two regular hexagons have sides 3 and 5. Find the ratio of their areas. Are they similar?'),
        s: L('Ha: ikkalasining burchaklari 120° va tomonlari teng, demak tomonlar nisbati doim 5/3. k = 5/3, yuzlar nisbati k<sup>2</sup> = 25/9 ≈ 2,78. Katta oltiburchak deyarli 3 barobar katta joy egallaydi.', 'Да: у обоих углы по 120° и стороны равны, значит, отношение сторон всюду 5/3. k = 5/3, отношение площадей k<sup>2</sup> = 25/9 ≈ 2,78. Большой шестиугольник занимает почти в 3 раза больше места.', 'Yes: both have 120° angles and equal sides, so every side ratio is 5/3. k = 5/3, and the area ratio is k<sup>2</sup> = 25/9 ≈ 2.78. The big hexagon covers almost 3 times as much.') }
    ] },
    { kind: 'table', h: L('k, k² va k³ jadvali', 'Таблица k, k² и k³', 'Table of k, k² and k³'), table: {
      head: [L('Uzunliklar (k)', 'Длины (k)', 'Lengths (k)'), L('Perimetr (k)', 'Периметр (k)', 'Perimeter (k)'), L('Yuz (k²)', 'Площадь (k²)', 'Area (k²)'), L('Hajm (k³)', 'Объём (k³)', 'Volume (k³)')],
      rows: [
        [L('½ marta', 'в ½ раза', '×½'), L('½ marta', 'в ½ раза', '×½'), L('¼ marta', 'в ¼ раза', '×¼'), L('⅛ marta', 'в ⅛ раза', '×⅛')],
        [L('2 marta', 'в 2 раза', '×2'), L('2 marta', 'в 2 раза', '×2'), L('4 marta', 'в 4 раза', '×4'), L('8 marta', 'в 8 раз', '×8')],
        [L('3 marta', 'в 3 раза', '×3'), L('3 marta', 'в 3 раза', '×3'), L('9 marta', 'в 9 раз', '×9'), L('27 marta', 'в 27 раз', '×27')],
        [L('10 marta', 'в 10 раз', '×10'), L('10 marta', 'в 10 раз', '×10'), L('100 marta', 'в 100 раз', '×100'), L('1000 marta', 'в 1000 раз', '×1000')]
      ] }, after: [
      L('Jadvaldan ko‘rinadiki, uzunlik ikki barobar oshsa, bo‘yoq (yuz) to‘rt barobar, material (hajm) esa sakkiz barobar ko‘p ketadi. Hajm va k<sup>3</sup> haqida batafsil 10–11-sinf stereometriyasida gaplashamiz.', 'Из таблицы видно: если длины удвоить, краски (площадь) нужно в 4 раза больше, а материала (объём) — в 8 раз. Подробно об объёме и k<sup>3</sup> поговорим в стереометрии 10–11 классов.', 'The table shows that doubling lengths needs four times the paint (area) and eight times the material (volume). We discuss volume and k<sup>3</sup> in detail in solid geometry in grades 10–11.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Yuzni k marta oshirish.</b> Tomonlar 2 marta oshsa, yuz 4 marta oshadi, 2 marta emas. Har doim o‘zingizdan so‘rang: men uzunlik bilan ishlayapmanmi yoki yuz bilanmi?', '<b>Увеличивать площадь в k раз.</b> Если стороны выросли в 2 раза, площадь выросла в 4 раза, а не в 2. Всегда спрашивайте себя: я работаю с длиной или с площадью?', '<b>Scaling area by k.</b> If sides double, area quadruples, not doubles. Always ask yourself: am I working with a length or an area?'),
      L('<b>Mos bo‘lmagan tomonlarni nisbatga olish.</b> Tomonlarni o‘lchami bo‘yicha emas, teng burchaklar bo‘yicha juftlang. Eng xavfsiz yo‘l — ikkala uchburchakda eng qisqa bilan eng qisqani, eng uzun bilan eng uzunni solishtirish.', '<b>Брать в отношение несходственные стороны.</b> Сопоставляйте стороны не по виду, а по равным углам. Самый надёжный путь — сравнивать самую короткую с самой короткой, самую длинную с самой длинной.', '<b>Pairing the wrong sides.</b> Match sides by equal angles, not by how the picture looks. The safest way is shortest with shortest and longest with longest.'),
      L('<b>Faqat burchaklarni tekshirish (ko‘pburchakda).</b> To‘rtburchak va undan katta ko‘pburchaklarda teng burchaklar o‘xshashlikni kafolatlamaydi: kvadrat va to‘g‘ri to‘rtburchak. Uchburchak bundan istisno — buni keyingi mavzuda ko‘ramiz.', '<b>Проверять только углы (у многоугольника).</b> Для четырёхугольников и выше равенство углов не гарантирует подобия: квадрат и прямоугольник. Треугольник — исключение, это мы увидим в следующей теме.', '<b>Checking only angles (for polygons).</b> For quadrilaterals and beyond, equal angles do not guarantee similarity: think of a square and a rectangle. The triangle is an exception, as the next topic shows.'),
      L('<b>Yuzlar nisbatidan k ni ildizsiz olish.</b> S<sub>2</sub>/S<sub>1</sub> = 16 bo‘lsa, k = 4, 16 emas.', '<b>Находить k из отношения площадей без корня.</b> Если S<sub>2</sub>/S<sub>1</sub> = 16, то k = 4, а не 16.', '<b>Taking k from an area ratio without a root.</b> If S<sub>2</sub>/S<sub>1</sub> = 16, then k = 4, not 16.'),
      L('<b>k ni teskari olish.</b> «Katta / kichik» yoki «kichik / katta» — ikkalasi ham to‘g‘ri, lekin butun masala davomida bitta tartibda qoling.', '<b>Брать k наоборот.</b> «Большая / меньшая» или «меньшая / большая» — оба варианта верны, но держитесь одного порядка во всей задаче.', '<b>Flipping k.</b> “Big / small” and “small / big” are both fine, but stick to one order throughout the problem.')
    ] },
    { kind: 'life', h: L('Hayotda o‘xshashlik', 'Подобие в жизни', 'Similarity in real life'), p: [
      L('<b>Pitsa paradoksi.</b> Diametri 20 cm va 30 cm bo‘lgan pitsalar o‘xshash (doiralar), k = 1,5. Katta pitsa yuzi 1,5<sup>2</sup> = 2,25 marta katta! Agar u kichigidan atigi 1,5 marta qimmat bo‘lsa, katta pitsani olish ancha foydali. Do‘konlar ko‘pincha narxni yuzga emas, diametrga qarab qo‘yadi.', '<b>Парадокс пиццы.</b> Пиццы диаметром 20 см и 30 см подобны (круги), k = 1,5. Площадь большой пиццы в 1,5<sup>2</sup> = 2,25 раза больше! Если она дороже маленькой всего в 1,5 раза, брать большую гораздо выгоднее. Магазины часто ставят цену по диаметру, а не по площади.', '<b>The pizza paradox.</b> Pizzas 20 cm and 30 cm across are similar (circles) with k = 1.5. The big one has 1.5<sup>2</sup> = 2.25 times the area! If it costs only 1.5 times as much, the big pizza is much better value. Shops often price by diameter, not by area.'),
      L('<b>Xarita va chizmalar.</b> Masshtab — bu o‘xshashlik koeffitsiyenti. Arxitektor 1 : 100 masshtabdagi chizmada 1 cm ni 1 m deb o‘qiydi, lekin xona yuzi uchun 1 cm<sup>2</sup> = 1 m<sup>2</sup> emas, balki 100<sup>2</sup> = 10 000 cm<sup>2</sup> = 1 m<sup>2</sup> — bu tasodifan mos keladi; 1 : 200 da esa 1 cm<sup>2</sup> = 4 m<sup>2</sup>.', '<b>Карты и чертежи.</b> Масштаб — это коэффициент подобия. Архитектор на чертеже 1 : 100 читает 1 см как 1 м, а для площади 1 см<sup>2</sup> соответствует 100<sup>2</sup> = 10 000 см<sup>2</sup> = 1 м<sup>2</sup>; при масштабе 1 : 200 уже 1 см<sup>2</sup> = 4 м<sup>2</sup>.', '<b>Maps and plans.</b> A scale is a scale factor. On a 1 : 100 plan an architect reads 1 cm as 1 m, and for area 1 cm<sup>2</sup> stands for 100<sup>2</sup> = 10,000 cm<sup>2</sup> = 1 m<sup>2</sup>; at 1 : 200, however, 1 cm<sup>2</sup> means 4 m<sup>2</sup>.'),
      L('<b>Biologiya.</b> Hayvon 2 marta kattalashsa, uning og‘irligi (hajm) 8 marta, suyaklari kesimi (yuz) esa faqat 4 marta oshadi. Shuning uchun fil oyoqlari sichqonnikiga nisbatan ancha yo‘g‘on: yuz hajmdan sekin o‘sadi. Kichik hayvonlar tez soviydi, chunki ularda tana yuzi hajmga nisbatan katta.', '<b>Биология.</b> Если животное увеличить в 2 раза, его вес (объём) вырастет в 8 раз, а сечение костей (площадь) — только в 4. Поэтому ноги слона намного толще, чем у мыши: площадь растёт медленнее объёма. Маленькие животные быстро остывают — у них велика поверхность тела относительно объёма.', '<b>Biology.</b> If an animal were twice as large, its weight (volume) would grow 8 times but the cross-section of its bones (area) only 4 times. That is why an elephant’s legs are so much thicker than a mouse’s: area grows more slowly than volume. Small animals lose heat fast because their surface is large compared with their volume.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('A4, A3, A5 qog‘oz varaqlari o‘zaro o‘xshash: tomonlar nisbati √2 ≈ 1,414. A3 ni teng ikkiga buklasangiz, aynan A4 hosil bo‘ladi, k = 1/√2, yuz esa roppa-rosa 2 marta kichik.', 'Листы A4, A3, A5 подобны друг другу: отношение сторон √2 ≈ 1,414. Сложите A3 пополам — получится ровно A4, k = 1/√2, а площадь ровно в 2 раза меньше.', 'A4, A3 and A5 sheets are all similar, with side ratio √2 ≈ 1.414. Fold an A3 sheet in half and you get exactly A4: k = 1/√2 and the area is exactly halved.'),
      L('A0 varag‘ining yuzi roppa-rosa 1 m<sup>2</sup>. A4 esa undan 4 marta kichraytirilgan, ya’ni yuzi 1/16 m<sup>2</sup>.', 'Площадь листа A0 — ровно 1 м<sup>2</sup>. A4 получен из него четырьмя складываниями, его площадь 1/16 м<sup>2</sup>.', 'An A0 sheet has an area of exactly 1 m<sup>2</sup>. A4 is four halvings smaller, with area 1/16 m<sup>2</sup>.'),
      L('Fraktallar — o‘ziga o‘xshash shakllar: Serpinskiy uchburchagining har bir bo‘lagi butun shaklga 1/2 koeffitsiyent bilan o‘xshash. Paporotnik bargi va gulkaram ham shunday tuzilgan.', 'Фракталы — самоподобные фигуры: каждая часть треугольника Серпинского подобна целому с коэффициентом 1/2. Так же устроены лист папоротника и цветная капуста.', 'Fractals are self-similar: each part of the Sierpiński triangle is similar to the whole with factor 1/2. Fern leaves and cauliflower are built the same way.'),
      L('Ikki o‘xshash shakl yuzlari 2 marta farq qilsa, tomonlar √2 marta farq qiladi — shuning uchun fotoapparat diafragmasi qiymatlari 1,4; 2; 2,8; 4; 5,6 … ketma-ketligida √2 qadam bilan ortadi.', 'Если площади двух подобных фигур отличаются в 2 раза, стороны отличаются в √2 раз — поэтому значения диафрагмы фотоаппарата идут шагом √2: 1,4; 2; 2,8; 4; 5,6 …', 'If two similar figures differ in area by 2, their sides differ by √2 — which is why camera aperture numbers go up in steps of √2: 1.4, 2, 2.8, 4, 5.6 …')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Uchburchak tomonlari 5, 7, 9. O‘xshash uchburchakning eng katta tomoni 27. Qolgan tomonlari?', '1. Стороны треугольника 5, 7, 9. Наибольшая сторона подобного треугольника 27. Остальные стороны?', '1. A triangle has sides 5, 7, 9. A similar triangle has longest side 27. Its other sides?'),
      L('2. k = 4. Kichik shakl yuzi 3 cm<sup>2</sup>. Katta shakl yuzi?', '2. k = 4. Площадь меньшей фигуры 3 см<sup>2</sup>. Площадь большей?', '2. k = 4. The small figure has area 3 cm<sup>2</sup>. The large one’s area?'),
      L('3. O‘xshash ko‘pburchaklar yuzlari 50 va 8. Perimetrlar nisbati?', '3. Площади подобных многоугольников 50 и 8. Отношение периметров?', '3. Similar polygons have areas 50 and 8. The ratio of perimeters?'),
      L('4. Ikki rombning tomonlari teng. Ular har doim o‘xshashmi?', '4. У двух ромбов равны стороны. Всегда ли они подобны?', '4. Two rhombuses have equal sides. Are they always similar?')
    ], after: [
      L('Javoblar: 1) k = 3, tomonlar 15 va 21; 2) 3 · 16 = 48 cm<sup>2</sup>; 3) √(50/8) = √6,25 = 2,5; 4) yo‘q — burchaklari har xil bo‘lishi mumkin.', 'Ответы: 1) k = 3, стороны 15 и 21; 2) 3 · 16 = 48 см<sup>2</sup>; 3) √(50/8) = √6,25 = 2,5; 4) нет — углы могут быть разными.', 'Answers: 1) k = 3, sides 15 and 21; 2) 3 · 16 = 48 cm<sup>2</sup>; 3) √(50/8) = √6.25 = 2.5; 4) no — their angles can differ.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘xshash ko‘pburchaklarda mos burchaklar teng, mos tomonlar proporsional.', 'У подобных многоугольников соответственные углы равны, а сходственные стороны пропорциональны.', 'Similar polygons have equal corresponding angles and proportional corresponding sides.'),
      L('Tomonlar nisbati k — o‘xshashlik koeffitsiyenti; mos tomonlar teng burchaklar qarshisida yotadi.', 'Отношение сторон k — коэффициент подобия; сходственные стороны лежат против равных углов.', 'The side ratio k is the scale factor; corresponding sides lie opposite equal angles.'),
      L('Perimetrlar, balandliklar, medianalar — hammasi k nisbatda.', 'Периметры, высоты, медианы — все относятся как k.', 'Perimeters, heights and medians are all in ratio k.'),
      L('Yuzlar nisbati k<sup>2</sup>; hajmlar nisbati k<sup>3</sup>.', 'Площади относятся как k<sup>2</sup>; объёмы — как k<sup>3</sup>.', 'Areas are in ratio k<sup>2</sup>; volumes in ratio k<sup>3</sup>.'),
      L('Yuzlar nisbatidan k ni topish uchun kvadrat ildiz chiqariladi.', 'Чтобы найти k по отношению площадей, извлекают квадратный корень.', 'To find k from an area ratio, take the square root.'),
      L('Masshtab, fotosurat, pitsa va hayvonlar tanasi — o‘xshashlikning hayotdagi ko‘rinishlari.', 'Масштаб, фотография, пицца и строение животных — проявления подобия в жизни.', 'Scales, photographs, pizzas and animal bodies all show similarity at work.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '9-2';

  // ---------- t3. Uchburchaklar o‘xshashligining alomatlari ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Oltita shart o‘rniga ikkita', 'Два условия вместо шести', 'Two conditions instead of six'), p: [
      L('Ta’rif bo‘yicha ikki uchburchak o‘xshash ekanini isbotlash uchun <b>oltita</b> narsani tekshirish kerak: uchta burchak tengligi va uchta tomon nisbati tengligi. Bu juda ko‘p ish! Bundan tashqari, amaliy masalalarda biz ko‘pincha hamma o‘lchamlarni bilmaymiz: daraxt balandligi, daryo kengligi yoki uzoqdagi minoragacha masofa — aynan noma’lum narsalar.', 'Чтобы по определению доказать подобие двух треугольников, нужно проверить <b>шесть</b> вещей: равенство трёх углов и равенство трёх отношений сторон. Это очень много работы! К тому же в практических задачах мы часто знаем не всё: высота дерева, ширина реки, расстояние до далёкой башни — как раз неизвестны.', 'To prove two triangles similar by the definition we must check <b>six</b> things: three equal angles and three equal side ratios. That is a lot of work! Besides, in practical problems we often do not know all the measurements: the height of a tree, the width of a river or the distance to a far tower are exactly the unknowns.'),
      L('Xayriyatki, uchburchak juda «qattiq» shakl: uning bir nechta elementi qolganlarini to‘liq belgilab beradi. 7-sinfda biz uchburchaklar <b>tengligining</b> uchta alomatini o‘rgangan edik (TBT, BTB, TTT). Endi xuddi shunday, <b>o‘xshashlikning</b> uchta alomatini o‘rganamiz. Ular ikki yoki uchta shartni tekshirib, qolganlari avtomatik bajarilishini kafolatlaydi.', 'К счастью, треугольник — очень «жёсткая» фигура: несколько его элементов полностью определяют остальные. В 7 классе мы изучили три признака <b>равенства</b> треугольников (СУС, УСУ, ССС). Теперь точно так же изучим три признака <b>подобия</b>. Они позволяют проверить два-три условия и гарантируют, что остальные выполнятся автоматически.', 'Fortunately, a triangle is a very “rigid” shape: a few of its parts completely fix the rest. In grade 7 we learned three tests for <b>congruent</b> triangles (SAS, ASA, SSS). Now, in the same spirit, we learn three tests for <b>similar</b> triangles. They let us check two or three conditions and guarantee that the rest hold automatically.'),
      L('Bu alomatlar geometriyaning eng ko‘p ishlatiladigan vositalaridan biri. Aylanadagi vatarlar, trapetsiya diagonallari, uchburchak medianalari, parallel chiziqlar — deyarli har bir murakkab masalaning ichida yashiringan bir juft o‘xshash uchburchak bor. Uni topa bilish — yechimning yarmi.', 'Эти признаки — один из самых используемых инструментов геометрии. Хорды окружности, диагонали трапеции, медианы треугольника, параллельные прямые — почти в каждой сложной задаче спрятана пара подобных треугольников. Умение её найти — половина решения.', 'These tests are among the most used tools in geometry. Chords in a circle, diagonals of a trapezium, medians of a triangle, parallel lines — almost every hard problem hides a pair of similar triangles inside. Spotting it is half of the solution.')
    ] },
    { kind: 'def', h: L('Uchta alomat', 'Три признака', 'The three tests'), list: [
      L('<b>1-alomat (BB — ikki burchak bo‘yicha).</b> Agar bir uchburchakning ikki burchagi ikkinchi uchburchakning ikki burchagiga mos ravishda teng bo‘lsa, bu uchburchaklar o‘xshash.', '<b>Признак 1 (УУ — по двум углам).</b> Если два угла одного треугольника соответственно равны двум углам другого, то треугольники подобны.', '<b>Test 1 (AA — two angles).</b> If two angles of one triangle are equal to two angles of another, the triangles are similar.'),
      L('<b>2-alomat (TBT — ikki tomon va ular orasidagi burchak bo‘yicha).</b> Agar bir uchburchakning ikki tomoni ikkinchisining ikki tomoniga proporsional bo‘lsa va bu tomonlar orasidagi burchaklar teng bo‘lsa, uchburchaklar o‘xshash.', '<b>Признак 2 (СУС — по двум сторонам и углу между ними).</b> Если две стороны одного треугольника пропорциональны двум сторонам другого, а углы между этими сторонами равны, то треугольники подобны.', '<b>Test 2 (SAS — two sides and the included angle).</b> If two sides of one triangle are proportional to two sides of another and the angles between them are equal, the triangles are similar.'),
      L('<b>3-alomat (TTT — uch tomon bo‘yicha).</b> Agar bir uchburchakning uch tomoni ikkinchisining uch tomoniga proporsional bo‘lsa, uchburchaklar o‘xshash.', '<b>Признак 3 (ССС — по трём сторонам).</b> Если три стороны одного треугольника пропорциональны трём сторонам другого, то треугольники подобны.', '<b>Test 3 (SSS — three sides).</b> If the three sides of one triangle are proportional to the three sides of another, the triangles are similar.')
    ], after: [
      L('Diqqat: BB alomatida ikki burchak yetarli, chunki uchinchisi avtomatik teng — uchburchak burchaklari yig‘indisi 180°. TBT da burchak aynan proporsional tomonlar <i>orasida</i> bo‘lishi shart.', 'Внимание: в признаке УУ хватает двух углов, потому что третий равен автоматически — сумма углов треугольника 180°. В СУС угол должен лежать именно <i>между</i> пропорциональными сторонами.', 'Note: in the AA test two angles are enough, because the third then matches automatically — the angles of a triangle add up to 180°. In SAS the angle must lie exactly <i>between</i> the proportional sides.')
    ] },
    { kind: 'history', h: L('Tarixdan: Falesdan Yevklidgacha', 'Из истории: от Фалеса до Евклида', 'History: from Thales to Euclid'), p: [
      L('Rivoyatlarga ko‘ra, <b>Fales Miletlik</b> (taxminan miloddan avvalgi 624–546) burchaklari teng uchburchaklarda tomonlar proporsional ekanini birinchi bo‘lib payqagan. Uning nomi bilan ataladigan teorema — <b>parallel to‘g‘ri chiziqlar burchak tomonlaridan proporsional kesmalar ajratadi</b> — o‘xshashlik alomatlarining asosi. Fales bu bilimdan dengizdagi kemagacha masofani qirg‘oqdan turib aniqlashda foydalangan, deyishadi.', 'По преданию, <b>Фалес Милетский</b> (около 624–546 до н. э.) первым заметил, что у треугольников с равными углами стороны пропорциональны. Теорема, носящая его имя, — <b>параллельные прямые отсекают на сторонах угла пропорциональные отрезки</b> — основа признаков подобия. Говорят, Фалес применял это знание, чтобы с берега определить расстояние до корабля в море.', 'According to tradition, <b>Thales of Miletus</b> (about 624–546 BC) was the first to notice that triangles with equal angles have proportional sides. The theorem named after him — <b>parallel lines cut proportional segments on the sides of an angle</b> — is the foundation of the similarity tests. Thales is said to have used it to find the distance to a ship at sea from the shore.'),
      L('<b>Yevklid</b> «Negizlar»ning VI kitobida bu alomatlarni qat’iy isbotlagan: 4-taklif — teng burchakli uchburchaklar tomonlari proporsional (BB), 5-taklif — tomonlari proporsional uchburchaklar teng burchakli (TTT), 6-taklif — TBT alomati. Bu isbotlar V kitobdagi <b>Evdoks</b>ning proporsiyalar nazariyasiga tayanadi; u √2 kabi «o‘lchovsiz» nisbatlar bilan ham ishlashga imkon berdi. Keyinchalik Bag‘dodning «Bayt ul-hikma»sida Yevklid arab tiliga tarjima qilindi va Xorazmiy, Farg‘oniy, Beruniy kabi olimlar uni o‘rganib, amaliy o‘lchashlarda qo‘lladilar.', '<b>Евклид</b> в VI книге «Начал» строго доказал эти признаки: предложение 4 — у равноугольных треугольников стороны пропорциональны (УУ), предложение 5 — треугольники с пропорциональными сторонами равноугольны (ССС), предложение 6 — признак СУС. Доказательства опираются на теорию пропорций <b>Евдокса</b> из V книги, которая позволила работать даже с «несоизмеримыми» отношениями вроде √2. Позже в багдадском «Доме мудрости» Евклида перевели на арабский, и учёные — Хорезми, Фергани, Беруни — изучали его и применяли в практических измерениях.', '<b>Euclid</b> proved these tests rigorously in Book VI of the Elements: Proposition 4 — equiangular triangles have proportional sides (AA); Proposition 5 — triangles with proportional sides are equiangular (SSS); Proposition 6 — the SAS test. The proofs rest on <b>Eudoxus’</b> theory of proportion from Book V, which made it possible to handle even “incommensurable” ratios such as √2. Later, in Baghdad’s House of Wisdom, Euclid was translated into Arabic, and scholars such as al-Khwarizmi, al-Farghani and al-Biruni studied him and used him in practical measurement.')
    ] },
    { kind: 'rule', h: L('Asosiy lemma va BB alomatining isboti', 'Основная лемма и доказательство признака УУ', 'The key lemma and the proof of AA'), p: [
      L('<b>Lemma.</b> Uchburchakning bir tomoniga parallel to‘g‘ri chiziq qolgan ikki tomonini kesib o‘tsa, berilgan uchburchakka o‘xshash uchburchak kesib oladi. Ya’ni △ABC da MN ∥ AC (M ∈ AB, N ∈ BC) bo‘lsa, △MBN ~ △ABC.', '<b>Лемма.</b> Прямая, параллельная стороне треугольника и пересекающая две другие стороны, отсекает треугольник, подобный данному. То есть если в △ABC MN ∥ AC (M ∈ AB, N ∈ BC), то △MBN ~ △ABC.', '<b>Lemma.</b> A line parallel to one side of a triangle that cuts the other two sides cuts off a triangle similar to the original. That is, if in △ABC MN ∥ AC (M on AB, N on BC), then △MBN ~ △ABC.'),
      L('<b>Lemma isboti g‘oyasi.</b> Burchaklar: ∠B umumiy, ∠BMN = ∠BAC va ∠BNM = ∠BCA — parallel chiziqlardagi mos burchaklar. Tomonlar: Fales (umumlashgan) teoremasiga ko‘ra BM/BA = BN/BC. Uchinchi nisbat uchun N orqali AB ga parallel chiziq o‘tkazamiz; u AC dan parallelogramm ajratadi va MN ga teng kesma hosil qiladi, shundan MN/AC = BN/BC.', '<b>Идея доказательства леммы.</b> Углы: ∠B общий, ∠BMN = ∠BAC и ∠BNM = ∠BCA — соответственные углы при параллельных. Стороны: по обобщённой теореме Фалеса BM/BA = BN/BC. Для третьего отношения проведём через N прямую, параллельную AB; она отсекает от AC параллелограмм и отрезок, равный MN, откуда MN/AC = BN/BC.', '<b>Proof idea of the lemma.</b> Angles: ∠B is shared, and ∠BMN = ∠BAC, ∠BNM = ∠BCA as corresponding angles at parallel lines. Sides: by the generalised Thales theorem, BM/BA = BN/BC. For the third ratio, draw a line through N parallel to AB; it cuts a parallelogram off AC with a segment equal to MN, so MN/AC = BN/BC.'),
      L('<b>BB alomatining isboti.</b> △ABC va △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> da ∠A = ∠A<sub>1</sub>, ∠B = ∠B<sub>1</sub> bo‘lsin. BA nurida BM = B<sub>1</sub>A<sub>1</sub> kesmani qo‘yamiz va M orqali AC ga parallel MN o‘tkazamiz. Lemmaga ko‘ra △MBN ~ △ABC. Endi △MBN = △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> (BTB alomati: BM = B<sub>1</sub>A<sub>1</sub>, ∠B = ∠B<sub>1</sub>, ∠BMN = ∠A = ∠A<sub>1</sub>). Demak △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> ham △ABC ga o‘xshash. TBT va TTT alomatlari ham xuddi shu «nusxa ko‘chirish» usuli bilan isbotlanadi.', '<b>Доказательство признака УУ.</b> Пусть в △ABC и △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> ∠A = ∠A<sub>1</sub>, ∠B = ∠B<sub>1</sub>. Отложим на луче BA отрезок BM = B<sub>1</sub>A<sub>1</sub> и проведём через M прямую MN ∥ AC. По лемме △MBN ~ △ABC. Далее △MBN = △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> (по признаку УСУ: BM = B<sub>1</sub>A<sub>1</sub>, ∠B = ∠B<sub>1</sub>, ∠BMN = ∠A = ∠A<sub>1</sub>). Значит, и △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> подобен △ABC. Признаки СУС и ССС доказываются тем же приёмом «копирования».', '<b>Proof of AA.</b> Let △ABC and △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> have ∠A = ∠A<sub>1</sub> and ∠B = ∠B<sub>1</sub>. On ray BA mark BM = B<sub>1</sub>A<sub>1</sub> and draw MN ∥ AC through M. By the lemma △MBN ~ △ABC. Next, △MBN is congruent to △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> (by ASA: BM = B<sub>1</sub>A<sub>1</sub>, ∠B = ∠B<sub>1</sub>, ∠BMN = ∠A = ∠A<sub>1</sub>). So △A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> is similar to △ABC too. SAS and SSS are proved with the same “copying” trick.')
    ] },
    { kind: 'steps', h: L('Qaysi alomatni tanlash kerak?', 'Какой признак выбрать?', 'Which test should you use?'), list: [
      L('1. Chizmada parallel chiziqlar, umumiy burchak yoki vertikal burchaklar bormi? Bo‘lsa — <b>BB</b> alomati deyarli har doim ishlaydi.', '1. Есть ли на чертеже параллельные прямые, общий угол или вертикальные углы? Если да — почти всегда работает признак <b>УУ</b>.', '1. Does the figure have parallel lines, a shared angle or vertical angles? If so, the <b>AA</b> test almost always works.'),
      L('2. Bitta burchak umumiy va uning yonidagi tomonlar ma’lummi? <b>TBT</b>: ikki nisbatni hisoblab, tengligini tekshiring.', '2. Один угол общий и известны прилежащие стороны? <b>СУС</b>: вычислите два отношения и проверьте их равенство.', '2. Is one angle shared and are the sides next to it known? Use <b>SAS</b>: compute two ratios and check they are equal.'),
      L('3. Faqat tomonlar ma’lummi? <b>TTT</b>: ikkala uchburchak tomonlarini o‘sish tartibida yozing va mos nisbatlarni solishtiring.', '3. Известны только стороны? <b>ССС</b>: выпишите стороны обоих треугольников по возрастанию и сравните соответствующие отношения.', '3. Are only the sides known? Use <b>SSS</b>: list both triangles’ sides in increasing order and compare the matching ratios.'),
      L('4. O‘xshashlikni to‘g‘ri tartibda yozing: △ABC ~ △KLM — teng burchaklar bir xil o‘rinda.', '4. Запишите подобие в правильном порядке: △ABC ~ △KLM — равные углы на одних местах.', '4. Write the similarity in the right order: △ABC ~ △KLM with equal angles in the same positions.'),
      L('5. Proporsiya tuzing va noma’lumni toping: AB/KL = BC/LM = AC/KM.', '5. Составьте пропорцию и найдите неизвестное: AB/KL = BC/LM = AC/KM.', '5. Set up the proportion and solve for the unknown: AB/KL = BC/LM = AC/KM.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('△ABC da AB = 12, BC = 15. AB da M nuqta, BM = 4; MN ∥ AC, N ∈ BC. BN ni toping.', 'В △ABC AB = 12, BC = 15. На AB точка M, BM = 4; MN ∥ AC, N ∈ BC. Найдите BN.', 'In △ABC, AB = 12 and BC = 15. M is on AB with BM = 4; MN ∥ AC with N on BC. Find BN.'),
        s: L('MN ∥ AC bo‘lgani uchun △MBN ~ △ABC (BB: ∠B umumiy, mos burchaklar teng). k = BM/BA = 4/12 = 1/3. BN = 15 · 1/3 = 5.', 'Так как MN ∥ AC, △MBN ~ △ABC (УУ: ∠B общий, соответственные углы равны). k = BM/BA = 4/12 = 1/3. BN = 15 · 1/3 = 5.', 'Since MN ∥ AC, △MBN ~ △ABC (AA: ∠B is shared and corresponding angles are equal). k = BM/BA = 4/12 = 1/3, so BN = 15 · 1/3 = 5.') },
      { q: L('Trapetsiya ABCD asoslari AD = 18, BC = 6. Diagonallar O nuqtada kesishadi, AC = 16. AO va OC ni toping.', 'В трапеции ABCD основания AD = 18, BC = 6. Диагонали пересекаются в O, AC = 16. Найдите AO и OC.', 'Trapezium ABCD has bases AD = 18 and BC = 6. The diagonals meet at O, and AC = 16. Find AO and OC.'),
        s: L('△AOD ~ △COB (BB: vertikal burchaklar ∠AOD = ∠COB, ichki almashinuvchi ∠OAD = ∠OCB). k = AD/BC = 3, ya’ni AO = 3 · OC. AO + OC = 16, 4 · OC = 16, OC = 4, AO = 12.', '△AOD ~ △COB (УУ: вертикальные ∠AOD = ∠COB, накрест лежащие ∠OAD = ∠OCB). k = AD/BC = 3, то есть AO = 3 · OC. AO + OC = 16, 4 · OC = 16, OC = 4, AO = 12.', '△AOD ~ △COB (AA: vertical angles ∠AOD = ∠COB and alternate angles ∠OAD = ∠OCB). k = AD/BC = 3, so AO = 3 · OC. AO + OC = 16 gives 4 · OC = 16, OC = 4 and AO = 12.') },
      { q: L('Uchburchaklar tomonlari 4, 6, 9 va 8, 12, 18. Ular o‘xshashmi? Teng burchaklarni ayting.', 'Стороны треугольников 4, 6, 9 и 8, 12, 18. Подобны ли они? Назовите равные углы.', 'Triangles have sides 4, 6, 9 and 8, 12, 18. Are they similar? Which angles are equal?'),
        s: L('Tartib bo‘yicha nisbatlar: 8/4 = 12/6 = 18/9 = 2. TTT alomatiga ko‘ra o‘xshash, k = 2. Teng burchaklar mos tomonlar qarshisida: 4 va 8 qarshisidagi, 6 va 12 qarshisidagi, 9 va 18 qarshisidagi burchaklar o‘zaro teng.', 'Отношения по порядку: 8/4 = 12/6 = 18/9 = 2. По признаку ССС треугольники подобны, k = 2. Равные углы лежат против сходственных сторон: против 4 и 8, против 6 и 12, против 9 и 18.', 'Ratios in order: 8/4 = 12/6 = 18/9 = 2. By SSS they are similar with k = 2. Equal angles lie opposite matching sides: opposite 4 and 8, opposite 6 and 12, and opposite 9 and 18.') },
      { q: L('△ABC da AB = 10, AC = 15. AB da D, AD = 6; AC da E, AE = 4. DE = 5. BC ni toping.', 'В △ABC AB = 10, AC = 15. На AB точка D, AD = 6; на AC точка E, AE = 4. DE = 5. Найдите BC.', 'In △ABC, AB = 10 and AC = 15. D is on AB with AD = 6, E is on AC with AE = 4, and DE = 5. Find BC.'),
        s: L('∠A umumiy. Nisbatlar: AE/AB = 4/10 = 0,4 va AD/AC = 6/15 = 0,4. TBT bo‘yicha △AED ~ △ABC (E ↔ B, D ↔ C), k = 0,4. DE ↔ BC, demak BC = 5 / 0,4 = 12,5. E’tibor bering: DE bu yerda BC ga parallel emas — uchburchak «ag‘darilgan» holda o‘xshash.', '∠A общий. Отношения: AE/AB = 4/10 = 0,4 и AD/AC = 6/15 = 0,4. По СУС △AED ~ △ABC (E ↔ B, D ↔ C), k = 0,4. DE ↔ BC, значит, BC = 5 / 0,4 = 12,5. Заметьте: DE здесь не параллелен BC — треугольник подобен в «перевёрнутом» положении.', '∠A is shared. Ratios: AE/AB = 4/10 = 0.4 and AD/AC = 6/15 = 0.4. By SAS △AED ~ △ABC (E ↔ B, D ↔ C) with k = 0.4. DE matches BC, so BC = 5 / 0.4 = 12.5. Note that DE is not parallel to BC here — the small triangle is similar in a “flipped” position.') },
      { q: L('Aylanada AB va CD vatarlar P nuqtada kesishadi. AP = 4, PB = 9, CP = 6. PD ni toping.', 'Хорды AB и CD окружности пересекаются в точке P. AP = 4, PB = 9, CP = 6. Найдите PD.', 'Chords AB and CD of a circle meet at P. AP = 4, PB = 9, CP = 6. Find PD.'),
        s: L('△APC ~ △DPB: vertikal burchaklar teng, ∠CAB = ∠CDB (bir yoyga tiralgan ichki chizilgan burchaklar). Demak AP/DP = CP/BP, ya’ni AP · PB = CP · PD. 4 · 9 = 6 · PD, PD = 6.', '△APC ~ △DPB: вертикальные углы равны, ∠CAB = ∠CDB (вписанные углы, опирающиеся на одну дугу). Значит, AP/DP = CP/BP, то есть AP · PB = CP · PD. 4 · 9 = 6 · PD, PD = 6.', '△APC ~ △DPB: vertical angles are equal and ∠CAB = ∠CDB (inscribed angles on the same arc). So AP/DP = CP/BP, that is AP · PB = CP · PD. 4 · 9 = 6 · PD, so PD = 6.') }
    ] },
    { kind: 'table', h: L('Tenglik va o‘xshashlik alomatlarini solishtirish', 'Сравнение признаков равенства и подобия', 'Congruence tests versus similarity tests'), table: {
      head: [L('Tenglik', 'Равенство', 'Congruence'), L('O‘xshashlik', 'Подобие', 'Similarity'), L('Farqi', 'Отличие', 'Difference')],
      rows: [
        [L('BTB: burchak, tomon, burchak', 'УСУ: угол, сторона, угол', 'ASA: angle, side, angle'), L('BB: ikki burchak', 'УУ: два угла', 'AA: two angles'), L('tomon kerak emas', 'сторона не нужна', 'no side needed')],
        [L('TBT: ikki tomon teng + burchak', 'СУС: две стороны равны + угол', 'SAS: two equal sides + angle'), L('TBT: ikki tomon proporsional + burchak', 'СУС: две стороны пропорциональны + угол', 'SAS: two proportional sides + angle'), L('teng o‘rniga proporsional', 'пропорциональны вместо равны', 'proportional instead of equal')],
        [L('TTT: uch tomon teng', 'ССС: три стороны равны', 'SSS: three equal sides'), L('TTT: uch tomon proporsional', 'ССС: три стороны пропорциональны', 'SSS: three proportional sides'), L('teng o‘rniga proporsional', 'пропорциональны вместо равны', 'proportional instead of equal')]
      ] }, after: [
      L('Tenglik — bu k = 1 bo‘lgan xususiy o‘xshashlik. Shuning uchun tenglik alomatlari o‘xshashlik alomatlaridan bitta qo‘shimcha shart (masalan, bitta tomon tengligi) bilan farq qiladi.', 'Равенство — частный случай подобия с k = 1. Поэтому признаки равенства отличаются от признаков подобия одним дополнительным условием (например, равенством одной стороны).', 'Congruence is the special case of similarity with k = 1. That is why each congruence test is a similarity test plus one extra condition (such as one pair of equal sides).')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>TBT da burchak tomonlar orasida emas.</b> Agar teng burchak proporsional tomonlardan biriga qarama-qarshi bo‘lsa, alomat ishlamaydi va uchburchaklar o‘xshash bo‘lmasligi mumkin.', '<b>В СУС угол не между сторонами.</b> Если равный угол лежит против одной из пропорциональных сторон, признак не работает, и треугольники могут быть не подобны.', '<b>The SAS angle is not between the sides.</b> If the equal angle is opposite one of the proportional sides, the test fails and the triangles may not be similar.'),
      L('<b>Uchlarni noto‘g‘ri tartibda yozish.</b> △ADE ~ △ABC deb yozib, aslida E ↔ B bo‘lsa, butun proporsiya buziladi. Avval teng burchaklarni belgilang, keyin harflarni yozing.', '<b>Записывать вершины не в том порядке.</b> Если записать △ADE ~ △ABC, а на деле E ↔ B, вся пропорция испортится. Сначала отметьте равные углы, потом пишите буквы.', '<b>Writing vertices in the wrong order.</b> Writing △ADE ~ △ABC when really E ↔ B ruins the whole proportion. Mark the equal angles first, then write the letters.'),
      L('<b>Kesma bo‘laklarini butun tomon o‘rniga olish.</b> MN ∥ AC bo‘lsa, MN/AC = BM/BA, lekin BM/MA emas! Nisbatda uchburchak tomonlari bo‘lishi kerak.', '<b>Брать части отрезка вместо всей стороны.</b> При MN ∥ AC MN/AC = BM/BA, а не BM/MA! В отношении должны стоять стороны треугольников.', '<b>Using pieces instead of whole sides.</b> If MN ∥ AC, then MN/AC = BM/BA, not BM/MA! The ratio must use sides of the triangles.'),
      L('<b>Faqat ikki nisbatni tekshirib TTT deyish.</b> Uch tomon alomatida uchala nisbat teng bo‘lishi kerak: 3, 4, 5 va 6, 8, 11 da ikki nisbat 2, uchinchisi 2,2 — o‘xshash emas.', '<b>Проверить два отношения и сказать «ССС».</b> В признаке по трём сторонам все три отношения должны быть равны: у 3, 4, 5 и 6, 8, 11 два отношения 2, третье 2,2 — не подобны.', '<b>Checking only two ratios and calling it SSS.</b> All three ratios must be equal: for 3, 4, 5 and 6, 8, 11 two ratios are 2 but the third is 2.2 — not similar.')
    ] },
    { kind: 'life', h: L('Hayotda o‘xshashlik alomatlari', 'Признаки подобия в жизни', 'Similarity tests in real life'), p: [
      L('<b>Daryo kengligini o‘lchash.</b> Qirg‘oqda A nuqtada turib, narigi qirg‘oqdagi daraxt T ni ko‘zlaymiz. Qirg‘oq bo‘ylab AB kesmani o‘lchab, B dan AT ga parallel yo‘nalishda yoki maxsus qoziqlar bilan kichik o‘xshash uchburchak quramiz. BB alomati bo‘yicha katta va kichik uchburchaklar o‘xshash bo‘ladi va daryo kengligi oddiy proporsiyadan topiladi — daryoni kechib o‘tish shart emas.', '<b>Измерение ширины реки.</b> Стоя в точке A на берегу, замечаем дерево T на другом берегу. Отмерив вдоль берега отрезок AB и поставив колышки, строим маленький подобный треугольник. По признаку УУ большой и малый треугольники подобны, и ширина реки находится из простой пропорции — переходить реку не нужно.', '<b>Measuring the width of a river.</b> Standing at A on the bank, we sight a tree T on the other side. Measuring a segment AB along the bank and placing stakes, we build a small similar triangle. By AA the large and small triangles are similar, and the width follows from a simple proportion — no need to cross the river.'),
      L('<b>Fotoapparat va ko‘z.</b> Linza orqali o‘tgan nurlar ikki o‘xshash uchburchak hosil qiladi: biri jism va linza orasida, ikkinchisi linza va sensor orasida. Vertikal burchaklar teng, nurlar sensor tekisligiga parallel — BB alomati. Shuning uchun fotografiya jismning o‘xshash (kichraytirilgan va teskari) tasviri.', '<b>Фотоаппарат и глаз.</b> Лучи, прошедшие через линзу, образуют два подобных треугольника: между предметом и линзой и между линзой и матрицей. Вертикальные углы равны, плоскости параллельны — признак УУ. Поэтому фотография — подобное (уменьшенное и перевёрнутое) изображение предмета.', '<b>Cameras and the eye.</b> Rays through a lens form two similar triangles: one between the object and the lens, the other between the lens and the sensor. The vertical angles are equal and the planes are parallel — the AA test. That is why a photograph is a similar (smaller and inverted) image of the object.'),
      L('<b>Muhandislik.</b> Ko‘prik fermalari va minoralar uchburchaklardan quriladi, chunki uchburchakning tomonlari uning shaklini to‘liq belgilaydi (TTT). Loyihachilar maketni sinab ko‘radi va TTT bo‘yicha haqiqiy inshoot maketga o‘xshash ekanini biladi.', '<b>Инженерия.</b> Фермы мостов и башни собирают из треугольников, потому что стороны треугольника полностью определяют его форму (ССС). Конструкторы испытывают макет и знают по ССС, что настоящее сооружение ему подобно.', '<b>Engineering.</b> Bridge trusses and towers are built from triangles because a triangle’s sides fix its shape completely (SSS). Designers test a scale model, knowing by SSS that the real structure is similar to it.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('To‘rtburchaklar uchun «to‘rt tomon proporsional» alomati yo‘q: tomoni 1 bo‘lgan kvadrat va romb tomonlari proporsional, lekin o‘xshash emas. Uchburchak yagona «qattiq» ko‘pburchak.', 'Для четырёхугольников признака «четыре стороны пропорциональны» нет: квадрат и ромб со стороной 1 имеют пропорциональные стороны, но не подобны. Треугольник — единственный «жёсткий» многоугольник.', 'There is no “four proportional sides” test for quadrilaterals: a square and a rhombus of side 1 have proportional sides but are not similar. The triangle is the only “rigid” polygon.'),
      L('Uchburchak o‘rta chizig‘i asosning yarmiga teng — bu k = ½ bo‘lgan lemmaning xususiy holi. U kesib olgan uchburchak yuzi butun uchburchakning ¼ qismi.', 'Средняя линия треугольника равна половине основания — частный случай леммы при k = ½. Отсекаемый ею треугольник имеет площадь ¼ всего треугольника.', 'The midline of a triangle is half the base — the lemma with k = ½. The triangle it cuts off has ¼ of the whole area.'),
      L('Uchburchak medianalari kesishish nuqtasida 2 : 1 nisbatda bo‘linishini ham o‘xshash uchburchaklar orqali isbotlash mumkin.', 'То, что медианы треугольника делятся точкой пересечения в отношении 2 : 1, тоже доказывается через подобные треугольники.', 'The fact that the medians of a triangle divide each other in the ratio 2 : 1 can also be proved with similar triangles.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. △ABC da ∠A = 50°, ∠B = 70°; △KLM da ∠K = 50°, ∠M = 60°. Ular o‘xshashmi?', '1. В △ABC ∠A = 50°, ∠B = 70°; в △KLM ∠K = 50°, ∠M = 60°. Подобны ли они?', '1. △ABC has ∠A = 50°, ∠B = 70°; △KLM has ∠K = 50°, ∠M = 60°. Are they similar?'),
      L('2. Tomonlari 5, 6, 7 va 10, 12, 15 bo‘lgan uchburchaklar o‘xshashmi?', '2. Подобны ли треугольники со сторонами 5, 6, 7 и 10, 12, 15?', '2. Are the triangles with sides 5, 6, 7 and 10, 12, 15 similar?'),
      L('3. Trapetsiya asoslari 4 va 10. Diagonallar kesishish nuqtasi bir diagonalni qanday nisbatda bo‘ladi?', '3. Основания трапеции 4 и 10. В каком отношении точка пересечения делит диагональ?', '3. A trapezium has bases 4 and 10. In what ratio does the intersection point divide a diagonal?'),
      L('4. Vatarlar P da kesishadi: AP = 3, PB = 8, CP = 4. PD = ?', '4. Хорды пересекаются в P: AP = 3, PB = 8, CP = 4. PD = ?', '4. Chords meet at P: AP = 3, PB = 8, CP = 4. PD = ?')
    ], after: [
      L('Javoblar: 1) ∠C = 60°, demak ∠A = ∠K, ∠C = ∠M — o‘xshash (BB); 2) 2; 2; 15/7 ≈ 2,14 — o‘xshash emas; 3) 2 : 5; 4) 3 · 8 : 4 = 6.', 'Ответы: 1) ∠C = 60°, значит, ∠A = ∠K, ∠C = ∠M — подобны (УУ); 2) 2; 2; 15/7 ≈ 2,14 — не подобны; 3) 2 : 5; 4) 3 · 8 : 4 = 6.', 'Answers: 1) ∠C = 60°, so ∠A = ∠K and ∠C = ∠M — similar (AA); 2) 2, 2 and 15/7 ≈ 2.14 — not similar; 3) 2 : 5; 4) 3 · 8 ÷ 4 = 6.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('BB: ikki burchagi teng uchburchaklar o‘xshash (uchinchi burchak avtomatik teng).', 'УУ: треугольники с двумя равными углами подобны (третий угол равен автоматически).', 'AA: triangles with two equal angles are similar (the third angle matches automatically).'),
      L('TBT: ikki tomon proporsional va ular orasidagi burchaklar teng bo‘lsa, o‘xshash.', 'СУС: две стороны пропорциональны и углы между ними равны — подобны.', 'SAS: two proportional sides with equal included angles give similarity.'),
      L('TTT: uchala tomon proporsional bo‘lsa, o‘xshash.', 'ССС: все три стороны пропорциональны — подобны.', 'SSS: all three sides proportional give similarity.'),
      L('Asosiy lemma: tomonga parallel chiziq o‘xshash uchburchak kesib oladi.', 'Основная лемма: прямая, параллельная стороне, отсекает подобный треугольник.', 'Key lemma: a line parallel to a side cuts off a similar triangle.'),
      L('Parallel chiziqlar, vertikal burchaklar va ichki chizilgan burchaklar — o‘xshash uchburchaklarni topish belgilari.', 'Параллельные прямые, вертикальные и вписанные углы — подсказки для поиска подобных треугольников.', 'Parallel lines, vertical angles and inscribed angles are clues for finding similar triangles.'),
      L('Har doim uchlarni mos tartibda yozing va proporsiyani tomonlar bilan tuzing.', 'Всегда записывайте вершины в соответствующем порядке и составляйте пропорцию из сторон.', 'Always write vertices in matching order and build the proportion from whole sides.')
    ] }
  ] });

  // ---------- t4. To‘g‘ri burchakli uchburchaklar o‘xshashligi. Tatbiqlar ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Soya o‘lchab, piramidani bilish', 'Измерить тень — узнать пирамиду', 'Measure a shadow, know a pyramid'), p: [
      L('Quyoshli kunda maktab hovlisidagi bayroq ustuni balandligini qanday bilish mumkin? Uning tepasiga chiqish xavfli, uzun ruletka ham yo‘q. Lekin sizda bir metr chizg‘ich va oddiy ruletka bor. Ma’lum bo‘lishicha, shuning o‘zi yetarli: ustun soyasini va chizg‘ich soyasini o‘lchab, bir proporsiya yozsangiz bas. Bu usul 2500 yildan ortiq vaqt oldin o‘ylab topilgan.', 'Как в солнечный день узнать высоту флагштока на школьном дворе? Залезать на него опасно, длинной рулетки нет. Но у вас есть метровая линейка и обычная рулетка. Оказывается, этого достаточно: измерьте тень флагштока и тень линейки и запишите одну пропорцию. Этот способ придуман более 2500 лет назад.', 'On a sunny day, how can you find the height of the flagpole in the school yard? Climbing it is dangerous and you have no long tape. But you have a metre stick and an ordinary tape measure. It turns out that is enough: measure the pole’s shadow and the stick’s shadow and write one proportion. This method was invented more than 2,500 years ago.'),
      L('Sababi shundaki, ustun, uning soyasi va quyosh nuri to‘g‘ri burchakli uchburchak hosil qiladi; chizg‘ich ham xuddi shunday uchburchak hosil qiladi. Quyosh nurlari parallel bo‘lgani uchun ikki uchburchakda o‘tkir burchaklar teng. To‘g‘ri burchakli uchburchaklar uchun esa bitta o‘tkir burchak tengligi o‘xshashlik uchun yetarli!', 'Причина в том, что флагшток, его тень и солнечный луч образуют прямоугольный треугольник; линейка образует такой же треугольник. Так как солнечные лучи параллельны, острые углы у двух треугольников равны. А для прямоугольных треугольников равенства одного острого угла достаточно для подобия!', 'The reason is that the pole, its shadow and the sun’s ray form a right triangle; the stick forms another. Since the sun’s rays are parallel, the two triangles have equal acute angles. And for right triangles, one equal acute angle is enough for similarity!'),
      L('Bu mavzuda to‘g‘ri burchakli uchburchaklar o‘xshashligining alomatlarini, gipotenuzaga tushirilgan balandlik bilan bog‘liq go‘zal munosabatlarni (o‘rta proporsional kesmalar) va o‘lchash usullarini — soya, ko‘zgu, tayoq usullarini o‘rganamiz. Shuningdek, qadimgi olimlar Yerning o‘lchamini qanday aniqlaganini bilib olamiz.', 'В этой теме мы изучим признаки подобия прямоугольных треугольников, красивые соотношения, связанные с высотой к гипотенузе (средние пропорциональные), и способы измерений — по тени, по зеркалу, с шестом. А ещё узнаем, как древние учёные определили размер Земли.', 'In this topic we study the similarity tests for right triangles, the beautiful relations linked to the height on the hypotenuse (mean proportionals) and practical measuring methods — the shadow, mirror and pole methods. We also learn how ancient scholars found the size of the Earth.')
    ] },
    { kind: 'def', h: L('To‘g‘ri burchakli uchburchaklar o‘xshashligi alomatlari', 'Признаки подобия прямоугольных треугольников', 'Similarity tests for right triangles'), p: [
      L('To‘g‘ri burchakli uchburchaklarda bitta burchak (90°) har doim teng. Shuning uchun umumiy alomatlar ancha soddalashadi:', 'В прямоугольных треугольниках один угол (90°) всегда равен. Поэтому общие признаки сильно упрощаются:', 'In right triangles one angle (90°) always matches. So the general tests become much simpler:')
    ], list: [
      L('<b>Bitta o‘tkir burchak bo‘yicha:</b> agar ikki to‘g‘ri burchakli uchburchakning bittadan o‘tkir burchagi teng bo‘lsa, ular o‘xshash (BB alomatidan).', '<b>По острому углу:</b> если у двух прямоугольных треугольников по одному острому углу равны, они подобны (из признака УУ).', '<b>One acute angle:</b> if two right triangles have one equal acute angle, they are similar (from AA).'),
      L('<b>Ikki katet bo‘yicha:</b> katetlari proporsional bo‘lsa, o‘xshash (TBT: to‘g‘ri burchak katetlar orasida).', '<b>По двум катетам:</b> если катеты пропорциональны, треугольники подобны (СУС: прямой угол между катетами).', '<b>Two legs:</b> if the legs are proportional, they are similar (SAS: the right angle lies between the legs).'),
      L('<b>Katet va gipotenuza bo‘yicha:</b> bir katet va gipotenuza proporsional bo‘lsa, o‘xshash. Pifagor teoremasi ikkinchi katetlar ham shu nisbatda ekanini ko‘rsatadi, keyin TTT ishlaydi.', '<b>По катету и гипотенузе:</b> если катет и гипотенуза пропорциональны, треугольники подобны. Теорема Пифагора показывает, что и вторые катеты в том же отношении, а дальше работает ССС.', '<b>A leg and the hypotenuse:</b> if one leg and the hypotenuse are proportional, they are similar. Pythagoras shows the other legs are in the same ratio, and then SSS applies.'),
      L('<b>O‘rta proporsional</b> (o‘rta geometrik) — a va b sonlar uchun x<sup>2</sup> = ab, ya’ni x = √(ab) bo‘lgan x soni. Masalan, 4 va 9 uchun 6.', '<b>Среднее пропорциональное</b> (среднее геометрическое) чисел a и b — число x, для которого x<sup>2</sup> = ab, то есть x = √(ab). Например, для 4 и 9 это 6.', 'The <b>mean proportional</b> (geometric mean) of a and b is the number x with x<sup>2</sup> = ab, that is x = √(ab). For 4 and 9 it is 6.')
    ] },
    { kind: 'history', h: L('Tarixdan: Fales, Eratosfen va Beruniy', 'Из истории: Фалес, Эратосфен и Беруни', 'History: Thales, Eratosthenes and al-Biruni'), p: [
      L('Rivoyat qilishlaricha, <b>Fales</b> Misrga borganida firavn undan Xeops piramidasining balandligini aniqlashni so‘ragan. Fales tayog‘ini yerga qadab, uning soyasi tayoq uzunligiga teng bo‘lgan paytni kutgan. Aynan shu paytda piramida balandligi ham uning soyasiga (asos markazigacha) teng bo‘ladi. Boshqa variantda u istalgan paytda tayoq va piramida soyalari nisbatidan foydalangan. Bu o‘xshash to‘g‘ri burchakli uchburchaklarning eng mashhur qo‘llanishi.', 'Рассказывают, что когда <b>Фалес</b> был в Египте, фараон попросил его определить высоту пирамиды Хеопса. Фалес воткнул посох в землю и дождался момента, когда тень посоха стала равна его длине. В этот момент и высота пирамиды равна её тени (до центра основания). По другой версии, он в любой момент использовал отношение теней посоха и пирамиды. Это самое знаменитое применение подобных прямоугольных треугольников.', 'The story goes that when <b>Thales</b> visited Egypt, the pharaoh asked him to find the height of the Great Pyramid. Thales stuck his staff in the ground and waited until its shadow was as long as the staff. At that moment the pyramid’s height also equals its shadow (measured to the centre of the base). In another version he used the ratio of the staff’s and the pyramid’s shadows at any time. It is the most famous use of similar right triangles.'),
      L('Miloddan avvalgi 240-yil atrofida <b>Eratosfen</b> Yer aylanasini o‘lchadi. Yozgi quyosh turishi kuni Siyenada (Asvon) quyosh tikkasiga turgan, Iskandariyada esa vertikal ustun soyasi 7,2° burchak hosil qilgan. Nurlar parallel bo‘lgani uchun shaharlar orasidagi yoy ham 7,2°, ya’ni aylananing 1/50 qismi. Masofani 50 ga ko‘paytirib, u Yer aylanasini taxminan 40 000 km atrofida topdi.', 'Около 240 года до н. э. <b>Эратосфен</b> измерил окружность Земли. В день летнего солнцестояния в Сиене (Асуане) солнце стояло в зените, а в Александрии тень вертикального шеста образовывала угол 7,2°. Так как лучи параллельны, дуга между городами тоже 7,2°, то есть 1/50 окружности. Умножив расстояние на 50, он получил окружность Земли около 40 000 км.', 'Around 240 BC <b>Eratosthenes</b> measured the Earth’s circumference. On the summer solstice the sun stood directly overhead at Syene (Aswan), while in Alexandria a vertical pole’s shadow made an angle of 7.2°. As the rays are parallel, the arc between the cities is also 7.2°, that is 1/50 of the circle. Multiplying the distance by 50, he found a circumference of about 40,000 km.'),
      L('XI asrda <b>Abu Rayhon Beruniy</b> Hindistondagi Nandana qal’asi yonidagi tog‘ cho‘qqisidan ufqning pastga og‘ish burchagini o‘lchab, Yer radiusini topdi. Tog‘ balandligini u ham o‘xshash to‘g‘ri burchakli uchburchaklar yordamida pastdan o‘lchagan. Uning natijasi (taxminan 6340 km) hozirgi qiymatga juda yaqin. Beruniy usulining afzalligi — ikki shahar o‘rniga bitta joyda o‘lchash kifoya.', 'В XI веке <b>Абу Райхан Беруни</b> определил радиус Земли, измерив с вершины горы у крепости Нандана в Индии угол понижения горизонта. Высоту горы он тоже измерил снизу с помощью подобных прямоугольных треугольников. Его результат (около 6340 км) очень близок к современному. Преимущество метода Беруни — достаточно измерений в одном месте, а не в двух городах.', 'In the 11th century <b>Abu Rayhan al-Biruni</b> found the Earth’s radius by measuring the dip of the horizon from a mountain near the fort of Nandana in India. He measured the mountain’s height from below, also with similar right triangles. His result (about 6,340 km) is very close to the modern value. The advantage of his method is that one site is enough instead of two cities.')
    ] },
    { kind: 'rule', h: L('Gipotenuzaga tushirilgan balandlik', 'Высота, опущенная на гипотенузу', 'The height on the hypotenuse'), p: [
      L('△ABC da ∠C = 90°, CH — gipotenuzaga balandlik. U gipotenuzani AH = a<sub>c</sub> va HB = b<sub>c</sub> bo‘laklarga ajratadi (har bir katetning gipotenuzadagi proyeksiyasi). <b>Teorema:</b> balandlik uchta o‘xshash to‘g‘ri burchakli uchburchak hosil qiladi: △ACH ~ △CBH ~ △ABC.', 'В △ABC ∠C = 90°, CH — высота к гипотенузе. Она делит гипотенузу на отрезки AH и HB — проекции катетов на гипотенузу. <b>Теорема:</b> высота образует три подобных прямоугольных треугольника: △ACH ~ △CBH ~ △ABC.', 'In △ABC with ∠C = 90°, let CH be the height to the hypotenuse. It splits the hypotenuse into AH and HB, the projections of the legs. <b>Theorem:</b> the height creates three similar right triangles: △ACH ~ △CBH ~ △ABC.'),
      L('<b>Isbot.</b> △ACH va △ABC da ∠A umumiy, ikkalasi to‘g‘ri burchakli — o‘xshash. △CBH va △ABC da ∠B umumiy — o‘xshash. Ikkalasi ham uchinchisiga o‘xshash bo‘lgani uchun o‘zaro ham o‘xshash.', '<b>Доказательство.</b> У △ACH и △ABC общий ∠A, оба прямоугольные — подобны. У △CBH и △ABC общий ∠B — подобны. Раз оба подобны третьему, они подобны и между собой.', '<b>Proof.</b> △ACH and △ABC share ∠A and are both right-angled, so they are similar. △CBH and △ABC share ∠B, so they are similar too. Being similar to the same triangle, they are similar to each other.'),
      L('<b>Natijalar (proporsiyalardan):</b> CH<sup>2</sup> = AH · HB — balandlik gipotenuza bo‘laklarining o‘rta proporsionali; AC<sup>2</sup> = AB · AH va BC<sup>2</sup> = AB · HB — katet gipotenuza va uning proyeksiyasining o‘rta proporsionali. Oxirgi ikkisini qo‘shsak: AC<sup>2</sup> + BC<sup>2</sup> = AB(AH + HB) = AB<sup>2</sup> — Pifagor teoremasining yana bir isboti!', '<b>Следствия (из пропорций):</b> CH<sup>2</sup> = AH · HB — высота есть среднее пропорциональное отрезков гипотенузы; AC<sup>2</sup> = AB · AH и BC<sup>2</sup> = AB · HB — катет есть среднее пропорциональное гипотенузы и своей проекции. Сложив два последних: AC<sup>2</sup> + BC<sup>2</sup> = AB(AH + HB) = AB<sup>2</sup> — ещё одно доказательство теоремы Пифагора!', '<b>Consequences (from the proportions):</b> CH<sup>2</sup> = AH · HB — the height is the mean proportional of the hypotenuse pieces; AC<sup>2</sup> = AB · AH and BC<sup>2</sup> = AB · HB — each leg is the mean proportional of the hypotenuse and its own projection. Adding the last two: AC<sup>2</sup> + BC<sup>2</sup> = AB(AH + HB) = AB<sup>2</sup> — yet another proof of Pythagoras!')
    ] },
    { kind: 'steps', h: L('Soya usuli bilan balandlik o‘lchash', 'Измерение высоты по тени', 'Measuring a height by its shadow'), list: [
      L('1. Quyoshli kunni tanlang. Uzunligi ma’lum h<sub>1</sub> bo‘lgan tayoqni yerga tik o‘rnating (shovun bilan tekshiring).', '1. Выберите солнечный день. Установите вертикально шест известной длины h<sub>1</sub> (проверьте отвесом).', '1. Pick a sunny day. Stand a pole of known length h<sub>1</sub> upright (check it with a plumb line).'),
      L('2. Tayoq soyasi s<sub>1</sub> ni va obyekt soyasi s<sub>2</sub> ni <b>bir vaqtda</b> o‘lchang — quyosh harakatlanadi, kechikish xatoga olib keladi.', '2. Измерьте тень шеста s<sub>1</sub> и тень объекта s<sub>2</sub> <b>одновременно</b> — солнце движется, и задержка даёт ошибку.', '2. Measure the pole’s shadow s<sub>1</sub> and the object’s shadow s<sub>2</sub> <b>at the same time</b> — the sun moves, and a delay causes error.'),
      L('3. Yer tekis va gorizontal ekanini tekshiring; obyekt soyasini uning tagidan (yoki asos markazidan) o‘lchang.', '3. Убедитесь, что земля ровная и горизонтальная; тень объекта мерьте от его основания (или центра основания).', '3. Make sure the ground is flat and level; measure the object’s shadow from its foot (or the centre of its base).'),
      L('4. Proporsiya tuzing: h<sub>2</sub> / s<sub>2</sub> = h<sub>1</sub> / s<sub>1</sub>, demak h<sub>2</sub> = h<sub>1</sub> · s<sub>2</sub> / s<sub>1</sub>.', '4. Составьте пропорцию: h<sub>2</sub> / s<sub>2</sub> = h<sub>1</sub> / s<sub>1</sub>, значит, h<sub>2</sub> = h<sub>1</sub> · s<sub>2</sub> / s<sub>1</sub>.', '4. Set up the proportion h<sub>2</sub> / s<sub>2</sub> = h<sub>1</sub> / s<sub>1</sub>, so h<sub>2</sub> = h<sub>1</sub> · s<sub>2</sub> / s<sub>1</sub>.'),
      L('5. Natijani aqlga muvofiqlik bo‘yicha tekshiring: bir qavat ≈ 3 m, daraxt odatda 5–25 m.', '5. Проверьте разумность результата: этаж ≈ 3 м, дерево обычно 5–25 м.', '5. Check the result is sensible: one storey is about 3 m, and a tree is usually 5–25 m.')
    ], after: [
      L('Quyosh bo‘lmasa, <b>ko‘zgu usuli</b> yordam beradi: ko‘zguni yerga qo‘yib, unda obyekt cho‘qqisi ko‘ringuncha orqaga yuring. Tushish va qaytish burchaklari teng, shuning uchun siz bilan ko‘zgu va obyekt bilan ko‘zgu hosil qilgan uchburchaklar o‘xshash.', 'Если солнца нет, поможет <b>метод зеркала</b>: положите зеркало на землю и отходите, пока в нём не увидите верхушку объекта. Углы падения и отражения равны, поэтому треугольники «вы — зеркало» и «объект — зеркало» подобны.', 'With no sun, the <b>mirror method</b> helps: put a mirror on the ground and step back until you see the top of the object in it. The angles of incidence and reflection are equal, so the triangles “you–mirror” and “object–mirror” are similar.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('1,5 m bo‘yli o‘quvchining soyasi 2 m. Shu payt daraxt soyasi 14 m. Daraxt balandligi qancha?', 'Тень ученика ростом 1,5 м равна 2 м. В это же время тень дерева 14 м. Какова высота дерева?', 'A 1.5 m tall student casts a 2 m shadow. At the same time a tree casts a 14 m shadow. How tall is the tree?'),
        s: L('Uchburchaklar o‘xshash (quyosh nurlari parallel, bitta o‘tkir burchak teng). h / 14 = 1,5 / 2, h = 14 · 0,75 = 10,5 m.', 'Треугольники подобны (лучи параллельны, острый угол общий). h / 14 = 1,5 / 2, h = 14 · 0,75 = 10,5 м.', 'The triangles are similar (parallel rays, equal acute angle). h / 14 = 1.5 / 2, so h = 14 · 0.75 = 10.5 m.') },
      { q: L('To‘g‘ri burchakli uchburchakda balandlik gipotenuzani 4 va 9 ga bo‘ladi. Balandlikni, katetlarni va yuzni toping.', 'Высота прямоугольного треугольника делит гипотенузу на отрезки 4 и 9. Найдите высоту, катеты и площадь.', 'The height of a right triangle divides the hypotenuse into 4 and 9. Find the height, the legs and the area.'),
        s: L('h<sup>2</sup> = 4 · 9 = 36, h = 6. Gipotenuza 13. Katetlar: a<sup>2</sup> = 13 · 4 = 52, a = 2√13; b<sup>2</sup> = 13 · 9 = 117, b = 3√13. Yuz: ½ · 13 · 6 = 39. Tekshirish: ½ · 2√13 · 3√13 = 3 · 13 = 39.', 'h<sup>2</sup> = 4 · 9 = 36, h = 6. Гипотенуза 13. Катеты: a<sup>2</sup> = 13 · 4 = 52, a = 2√13; b<sup>2</sup> = 13 · 9 = 117, b = 3√13. Площадь: ½ · 13 · 6 = 39. Проверка: ½ · 2√13 · 3√13 = 3 · 13 = 39.', 'h<sup>2</sup> = 4 · 9 = 36, so h = 6. The hypotenuse is 13. Legs: a<sup>2</sup> = 13 · 4 = 52, a = 2√13; b<sup>2</sup> = 13 · 9 = 117, b = 3√13. Area: ½ · 13 · 6 = 39. Check: ½ · 2√13 · 3√13 = 3 · 13 = 39.') },
      { q: L('Ko‘zgu usuli: ko‘zgu binodan 24 m uzoqda, o‘quvchi ko‘zgudan 2 m uzoqda turibdi, ko‘zi yerdan 1,6 m balandda. Bino balandligi?', 'Метод зеркала: зеркало в 24 м от здания, ученик стоит в 2 м от зеркала, его глаза на высоте 1,6 м. Высота здания?', 'Mirror method: the mirror is 24 m from a building, the student stands 2 m from the mirror, with eyes 1.6 m above the ground. How tall is the building?'),
        s: L('Ikki to‘g‘ri burchakli uchburchak o‘xshash (ko‘zgudagi burchaklar teng). H / 24 = 1,6 / 2, H = 24 · 0,8 = 19,2 m — taxminan olti qavatli bino.', 'Два прямоугольных треугольника подобны (углы у зеркала равны). H / 24 = 1,6 / 2, H = 24 · 0,8 = 19,2 м — примерно шестиэтажное здание.', 'The two right triangles are similar (equal angles at the mirror). H / 24 = 1.6 / 2, so H = 24 · 0.8 = 19.2 m — roughly a six-storey building.') },
      { q: L('To‘g‘ri burchakli uchburchakning kateti 12, uning gipotenuzadagi proyeksiyasi 7,2. Gipotenuzani va ikkinchi katetni toping.', 'Катет прямоугольного треугольника 12, его проекция на гипотенузу 7,2. Найдите гипотенузу и второй катет.', 'A leg of a right triangle is 12 and its projection on the hypotenuse is 7.2. Find the hypotenuse and the other leg.'),
        s: L('a<sup>2</sup> = c · a<sub>c</sub>: 144 = c · 7,2, c = 20. Ikkinchi katet: √(400 − 144) = √256 = 16. Bu 3, 4, 5 uchligining 4 barobari.', 'a<sup>2</sup> = c · a<sub>c</sub>: 144 = c · 7,2, c = 20. Второй катет: √(400 − 144) = √256 = 16. Это тройка 3, 4, 5, умноженная на 4.', 'a<sup>2</sup> = c · a<sub>c</sub>: 144 = c · 7.2, so c = 20. The other leg is √(400 − 144) = √256 = 16. It is the 3, 4, 5 triple times 4.') }
    ] },
    { kind: 'table', h: L('O‘lchash usullari', 'Способы измерения', 'Measuring methods'), table: {
      head: [L('Usul', 'Метод', 'Method'), L('Nima kerak', 'Что нужно', 'What you need'), L('Formula', 'Формула', 'Formula')],
      rows: [
        [L('soya', 'тень', 'shadow'), L('quyosh, tayoq, ruletka', 'солнце, шест, рулетка', 'sun, pole, tape'), L('H = h · S / s', 'H = h · S / s', 'H = h · S / s')],
        [L('ko‘zgu', 'зеркало', 'mirror'), L('ko‘zgu, ruletka', 'зеркало, рулетка', 'mirror, tape'), L('H = h · D / d', 'H = h · D / d', 'H = h · D / d')],
        [L('tayoq (ko‘z bilan)', 'шест (на глаз)', 'sighting pole'), L('ikki tayoq, ruletka', 'два шеста, рулетка', 'two poles, tape'), L('o‘xshash uchburchaklar', 'подобные треугольники', 'similar triangles')],
        [L('Eratosfen', 'Эратосфен', 'Eratosthenes'), L('ikki shahar, soya burchagi', 'два города, угол тени', 'two cities, shadow angle'), L('aylana = masofa · 360° / burchak', 'окружность = расстояние · 360° / угол', 'circumference = distance · 360° / angle')],
        [L('Beruniy', 'Беруни', 'al-Biruni'), L('tog‘, ufq og‘ishi', 'гора, понижение горизонта', 'mountain, horizon dip'), L('to‘g‘ri burchakli uchburchak', 'прямоугольный треугольник', 'a right triangle')]
      ] }, after: [
      L('Bu yerda h — ma’lum balandlik (tayoq yoki ko‘z), s va d — kichik uchburchakdagi masofalar, S va D — katta uchburchakdagi mos masofalar.', 'Здесь h — известная высота (шест или глаза), s и d — расстояния в малом треугольнике, S и D — соответствующие расстояния в большом.', 'Here h is a known height (pole or eye level), s and d are distances in the small triangle, and S and D are the matching distances in the big one.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Soyalarni turli vaqtda o‘lchash.</b> Bir soatda quyosh 15° ga siljiydi va soyalar uzunligi keskin o‘zgaradi. O‘lchashlar bir paytda bo‘lishi kerak.', '<b>Мерить тени в разное время.</b> За час солнце смещается на 15°, и длины теней сильно меняются. Измерения должны быть одновременными.', '<b>Measuring shadows at different times.</b> In an hour the sun moves 15° and shadow lengths change a lot. The measurements must be simultaneous.'),
      L('<b>Proporsiyani teskari tuzish.</b> h<sub>2</sub> = h<sub>1</sub> · s<sub>1</sub> / s<sub>2</sub> emas! Uzunroq soya — balandroq obyekt; tekshirish shuni ko‘rsatishi kerak.', '<b>Переворачивать пропорцию.</b> Не h<sub>2</sub> = h<sub>1</sub> · s<sub>1</sub> / s<sub>2</sub>! Длиннее тень — выше объект; проверка должна это подтверждать.', '<b>Flipping the proportion.</b> It is not h<sub>2</sub> = h<sub>1</sub> · s<sub>1</sub> / s<sub>2</sub>! A longer shadow means a taller object, and your check should confirm that.'),
      L('<b>Proyeksiyalarni adashtirish.</b> AC<sup>2</sup> = AB · AH formulasida AH — aynan AC katetiga yopishgan bo‘lak, ya’ni A uchidan boshlanadigan bo‘lak.', '<b>Путать проекции.</b> В формуле AC<sup>2</sup> = AB · AH отрезок AH — тот, что прилежит к катету AC, то есть начинается в вершине A.', '<b>Mixing up projections.</b> In AC<sup>2</sup> = AB · AH, AH is the piece next to leg AC, the one that starts at vertex A.'),
      L('<b>Bitta o‘tkir burchak alomatini oddiy uchburchakka qo‘llash.</b> Bitta burchak tengligi faqat ikkala uchburchak to‘g‘ri burchakli bo‘lganda yetarli.', '<b>Применять признак по одному острому углу к обычным треугольникам.</b> Одного равного угла достаточно, только если оба треугольника прямоугольные.', '<b>Using the one-acute-angle test on ordinary triangles.</b> One equal angle is enough only when both triangles are right-angled.')
    ] },
    { kind: 'life', h: L('Hayotda: geodeziya, kino va tibbiyot', 'В жизни: геодезия, кино и медицина', 'In real life: surveying, film and medicine'), p: [
      L('<b>Geodeziya va qurilish.</b> Yo‘l quruvchilar va geodezistlar teodolit bilan burchaklarni, lazer dalnomer bilan masofalarni o‘lchaydi va o‘xshash to‘g‘ri burchakli uchburchaklar orqali tepalik balandligini, ko‘prik uzunligini va yo‘l qiyaligini hisoblaydi. Yo‘l belgisidagi «10 % qiyalik» — bu katetlar nisbati 1 : 10 bo‘lgan to‘g‘ri burchakli uchburchak.', '<b>Геодезия и строительство.</b> Дорожники и геодезисты измеряют теодолитом углы, лазерным дальномером — расстояния и через подобные прямоугольные треугольники вычисляют высоту холма, длину моста и уклон дороги. Знак «уклон 10 %» — это прямоугольный треугольник с отношением катетов 1 : 10.', '<b>Surveying and construction.</b> Road builders and surveyors measure angles with a theodolite and distances with a laser rangefinder, and use similar right triangles to compute hill heights, bridge lengths and road gradients. A “10 % gradient” sign describes a right triangle with legs in the ratio 1 : 10.'),
      L('<b>Kino va teatr.</b> Kinoproyektor ekrandagi tasvirni katta qiladi: proyektor ekrandan ikki barobar uzoqlashsa, tasvir eni ham ikki barobar oshadi. Kinoteatrlar zal uzunligini shu o‘xshashlik bo‘yicha hisoblab loyihalaydi.', '<b>Кино и театр.</b> Кинопроектор увеличивает изображение: если отодвинуть проектор от экрана вдвое дальше, ширина картинки вырастет вдвое. Кинотеатры проектируют длину зала по этому подобию.', '<b>Film and theatre.</b> A projector enlarges the image: move it twice as far from the screen and the picture becomes twice as wide. Cinemas plan the length of the hall using this similarity.'),
      L('<b>Tibbiyot.</b> Rentgen nurlari nuqtaviy manbadan tarqaladi, shuning uchun suratdagi suyak haqiqiysidan biroz katta chiqadi. Shifokorlar manba–tana va manba–plyonka masofalari nisbatidan haqiqiy o‘lchamni topadi.', '<b>Медицина.</b> Рентгеновские лучи расходятся из точечного источника, поэтому кость на снимке немного больше настоящей. Врачи находят истинный размер по отношению расстояний источник–тело и источник–плёнка.', '<b>Medicine.</b> X-rays spread out from a point source, so a bone on the film looks slightly larger than it really is. Doctors find the true size from the ratio of the source–body and source–film distances.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Xeops piramidasining dastlabki balandligi taxminan 146 m edi; 3800 yildan ortiq vaqt davomida u dunyodagi eng baland inshoot bo‘lgan.', 'Первоначальная высота пирамиды Хеопса — около 146 м; более 3800 лет она была самым высоким сооружением в мире.', 'The Great Pyramid was originally about 146 m tall; for more than 3,800 years it was the tallest structure in the world.'),
      L('Eratosfen natijasi qaysi «stadiy» birligi olinganiga qarab haqiqiy 40 075 km dan bir necha foiz farq qiladi — oddiy tayoq va soya uchun ajoyib aniqlik.', 'Результат Эратосфена в зависимости от того, какой «стадий» взять, отличается от истинных 40 075 км на несколько процентов — поразительная точность для шеста и тени.', 'Depending on which “stadion” unit is used, Eratosthenes’ result is within a few percent of the true 40,075 km — remarkable accuracy for a stick and a shadow.'),
      L('Ufqqacha masofa taxminan √(2Rh) ga teng: qirg‘oqda 1,7 m balandlikdagi ko‘z ufqni ≈ 4,7 km da ko‘radi. Bu ham Beruniy chizmasidagi to‘g‘ri burchakli uchburchakdan kelib chiqadi.', 'Расстояние до горизонта примерно √(2Rh): глаз на высоте 1,7 м видит горизонт на ≈ 4,7 км. Это тоже следует из прямоугольного треугольника на чертеже Беруни.', 'The distance to the horizon is about √(2Rh): an eye 1.7 m up sees the horizon about 4.7 km away. This, too, comes from the right triangle in al-Biruni’s drawing.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. 2 m li tayoq soyasi 1,6 m; minora soyasi 36 m. Minora balandligi?', '1. Тень двухметрового шеста 1,6 м; тень башни 36 м. Высота башни?', '1. A 2 m pole casts 1.6 m of shadow; a tower casts 36 m. The tower’s height?'),
      L('2. Gipotenuza bo‘laklari 2 va 8. Balandlik?', '2. Отрезки гипотенузы 2 и 8. Высота?', '2. The hypotenuse pieces are 2 and 8. The height?'),
      L('3. Katetlari 6, 8 va 9, 12 bo‘lgan uchburchaklar o‘xshashmi?', '3. Подобны ли треугольники с катетами 6, 8 и 9, 12?', '3. Are triangles with legs 6, 8 and 9, 12 similar?'),
      L('4. Katetlar 15 va 20. Gipotenuzaga balandlik?', '4. Катеты 15 и 20. Высота к гипотенузе?', '4. The legs are 15 and 20. The height to the hypotenuse?')
    ], after: [
      L('Javoblar: 1) 2 · 36 / 1,6 = 45 m; 2) √16 = 4; 3) ha, 9/6 = 12/8 = 1,5; 4) c = 25, h = 15 · 20 / 25 = 12.', 'Ответы: 1) 2 · 36 / 1,6 = 45 м; 2) √16 = 4; 3) да, 9/6 = 12/8 = 1,5; 4) c = 25, h = 15 · 20 / 25 = 12.', 'Answers: 1) 2 · 36 / 1.6 = 45 m; 2) √16 = 4; 3) yes, 9/6 = 12/8 = 1.5; 4) c = 25, h = 15 · 20 / 25 = 12.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('To‘g‘ri burchakli uchburchaklar o‘xshashligi uchun bitta o‘tkir burchak tengligi yetarli.', 'Для подобия прямоугольных треугольников достаточно равенства одного острого угла.', 'One equal acute angle is enough for two right triangles to be similar.'),
      L('Katetlar proporsional yoki katet va gipotenuza proporsional bo‘lsa ham o‘xshash.', 'Они подобны и тогда, когда пропорциональны катеты или катет и гипотенуза.', 'They are also similar if the legs, or a leg and the hypotenuse, are proportional.'),
      L('Gipotenuzaga balandlik uchta o‘xshash uchburchak beradi: h<sup>2</sup> = a<sub>c</sub> · b<sub>c</sub>, a<sup>2</sup> = c · a<sub>c</sub>, b<sup>2</sup> = c · b<sub>c</sub>.', 'Высота к гипотенузе даёт три подобных треугольника: h<sup>2</sup> = a<sub>c</sub> · b<sub>c</sub>, a<sup>2</sup> = c · a<sub>c</sub>, b<sup>2</sup> = c · b<sub>c</sub>.', 'The height to the hypotenuse gives three similar triangles: h<sup>2</sup> = a<sub>c</sub> · b<sub>c</sub>, a<sup>2</sup> = c · a<sub>c</sub>, b<sup>2</sup> = c · b<sub>c</sub>.'),
      L('Soya usuli: H / S = h / s; o‘lchashlar bir vaqtda bo‘lishi shart.', 'Метод тени: H / S = h / s; измерения должны быть одновременными.', 'Shadow method: H / S = h / s, with simultaneous measurements.'),
      L('Fales piramidani, Eratosfen Yer aylanasini, Beruniy Yer radiusini o‘xshash uchburchaklar bilan o‘lchagan.', 'Фалес измерил пирамиду, Эратосфен — окружность Земли, Беруни — радиус Земли с помощью подобных треугольников.', 'Thales measured the pyramid, Eratosthenes the Earth’s circumference and al-Biruni the Earth’s radius with similar triangles.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '9-2';

  // ---------- t5. Harakat va parallel ko‘chirish ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Shakllarni siljitish geometriyasi', 'Геометрия перемещений', 'The geometry of moving figures'), p: [
      L('7-sinfda biz ikki uchburchak tengligini «ustma-ust qo‘yish» bilan tushuntirgan edik: birini qog‘ozdan qirqib, ikkinchisining ustiga qo‘ysak, ular to‘liq ustma-ust tushadi. Ammo «qo‘yish», «siljitish», «aylantirish» — bu kundalik so‘zlar. Matematika ularni aniq ta’riflashni talab qiladi. Bu mavzuda biz shakllarni ko‘chirishni <b>almashtirish</b> sifatida qaraymiz: tekislikning har bir nuqtasi qandaydir yangi nuqtaga o‘tadi.', 'В 7 классе мы объясняли равенство треугольников «наложением»: вырежем один из бумаги, положим на другой — и они совпадут. Но «положить», «сдвинуть», «повернуть» — бытовые слова. Математика требует точных определений. В этой теме мы будем рассматривать перемещение фигур как <b>преобразование</b>: каждая точка плоскости переходит в некоторую новую точку.', 'In grade 7 we explained congruent triangles by “placing one on the other”: cut one out of paper, lay it on the other and they match exactly. But “place”, “slide” and “turn” are everyday words. Mathematics demands precise definitions. In this topic we treat moving figures as a <b>transformation</b>: every point of the plane goes to some new point.'),
      L('Eng muhim almashtirishlar — shaklni buzmaydigan, faqat joyini o‘zgartiradigan almashtirishlar. Ular <b>harakat</b> deb ataladi. Lift kabinasi, eskalator zinasi, konveyerdagi quti, kompyuter o‘yinidagi qahramon — hammasi harakat qiladi, lekin o‘lchami va shakli o‘zgarmaydi. Eng sodda harakat — <b>parallel ko‘chirish</b>: barcha nuqtalar bir xil yo‘nalishda bir xil masofaga siljiydi.', 'Самые важные преобразования — те, что не искажают фигуру, а лишь меняют её положение. Они называются <b>движениями</b>. Кабина лифта, ступенька эскалатора, коробка на конвейере, герой компьютерной игры — все они перемещаются, но не меняют размер и форму. Простейшее движение — <b>параллельный перенос</b>: все точки сдвигаются в одном направлении на одно и то же расстояние.', 'The most important transformations are those that do not distort a figure but only change its position. They are called <b>isometries</b> (rigid motions). A lift car, an escalator step, a box on a conveyor belt, a character in a computer game — all of them move without changing size or shape. The simplest isometry is a <b>translation</b>: every point slides the same distance in the same direction.'),
      L('Biz harakatning ta’rifi va xossalarini, parallel ko‘chirishning vektor va koordinata ko‘rinishini o‘rganamiz, shuningdek parallel ko‘chirish yordamida yechiladigan qiziq masalalarni — masalan, daryo ustiga ko‘prikni qayerga qurish kerakligini — ko‘rib chiqamiz.', 'Мы изучим определение и свойства движения, векторную и координатную запись параллельного переноса, а также интересные задачи, которые решаются переносом, — например, где построить мост через реку.', 'We will study the definition and properties of isometries, the vector and coordinate forms of a translation, and some neat problems solved with translations — such as where to build a bridge over a river.')
    ] },
    { kind: 'def', h: L('Almashtirish va harakat', 'Преобразование и движение', 'Transformation and isometry'), p: [
      L('Tekislikning har bir X nuqtasiga qandaydir X′ nuqtani mos qo‘yuvchi qoida <b>tekislikni almashtirish</b> deyiladi. X′ — X ning <b>tasviri (obrazi)</b>. Agar har qanday ikki A va B nuqta uchun A′B′ = AB bo‘lsa, ya’ni masofalar saqlansa, bunday almashtirish <b>harakat</b> deyiladi.', 'Правило, которое каждой точке X плоскости ставит в соответствие некоторую точку X′, называется <b>преобразованием плоскости</b>. X′ — <b>образ</b> точки X. Если для любых двух точек A и B выполняется A′B′ = AB, то есть расстояния сохраняются, преобразование называется <b>движением</b>.', 'A rule that assigns to every point X of the plane some point X′ is a <b>transformation of the plane</b>. X′ is the <b>image</b> of X. If A′B′ = AB for any two points A and B, that is, distances are kept, the transformation is called an <b>isometry</b> (a motion).')
    ], list: [
      L('Harakat to‘g‘ri chiziqni to‘g‘ri chiziqqa, nurni nurga, kesmani unga teng kesmaga o‘tkazadi.', 'Движение переводит прямую в прямую, луч в луч, отрезок в равный ему отрезок.', 'An isometry maps lines to lines, rays to rays and segments to equal segments.'),
      L('Harakat burchaklarni saqlaydi: burchak unga teng burchakka o‘tadi; shuning uchun parallel chiziqlar parallel, perpendikulyarlar perpendikulyar bo‘lib qoladi.', 'Движение сохраняет углы: угол переходит в равный угол; поэтому параллельные прямые остаются параллельными, перпендикулярные — перпендикулярными.', 'Isometries keep angles: an angle goes to an equal angle, so parallel lines stay parallel and perpendicular lines stay perpendicular.'),
      L('Harakat uchburchakni unga teng uchburchakka, aylanani shu radiusli aylanaga o‘tkazadi.', 'Движение переводит треугольник в равный треугольник, окружность — в окружность того же радиуса.', 'An isometry maps a triangle to a congruent triangle and a circle to a circle of the same radius.'),
      L('<b>Teng shakllar</b> — biri ikkinchisiga harakat bilan o‘tadigan shakllar. Bu 7-sinfdagi «ustma-ust qo‘yish»ning aniq ma’nosi.', '<b>Равные фигуры</b> — фигуры, одна из которых переводится в другую движением. Это точный смысл «наложения» из 7 класса.', '<b>Congruent figures</b> are figures one of which can be mapped onto the other by an isometry. This is the precise meaning of “placing on top” from grade 7.'),
      L('Ikki harakatni ketma-ket bajarish (<b>kompozitsiya</b>) yana harakat bo‘ladi.', 'Последовательное выполнение двух движений (<b>композиция</b>) — снова движение.', 'Doing two isometries one after another (their <b>composition</b>) gives another isometry.')
    ] },
    { kind: 'history', h: L('Tarixdan: Feliks Kleynning Erlangen dasturi', 'Из истории: Эрлангенская программа Феликса Клейна', 'History: Felix Klein’s Erlangen programme'), p: [
      L('Yevklid «Negizlar»ida shakllarni ustma-ust qo‘yishdan foydalangan, lekin buni alohida tushuncha sifatida ajratmagan. XIX asrga kelib matematiklar ko‘plab turli geometriyalarni — Lobachevskiy geometriyasi, proyektiv geometriya va boshqalarni — kashf qilishdi va savol tug‘ildi: ularni nima birlashtiradi?', 'Евклид в «Началах» использовал наложение фигур, но не выделял его как отдельное понятие. К XIX веку математики открыли множество разных геометрий — геометрию Лобачевского, проективную и другие, — и возник вопрос: что их объединяет?', 'Euclid used the placing of one figure on another in the Elements but did not treat it as a separate concept. By the 19th century mathematicians had discovered many different geometries — Lobachevsky’s geometry, projective geometry and others — and a question arose: what unites them?'),
      L('1872-yilda 23 yoshli nemis matematigi <b>Feliks Kleyn</b> Erlangen universitetiga professor bo‘lib kelganida mashhur <b>«Erlangen dasturi»</b>ni e’lon qildi. Uning g‘oyasi: har bir geometriya — bu qandaydir almashtirishlar guruhi va shu almashtirishlarda o‘zgarmaydigan xossalarni o‘rganuvchi fan. Maktab (Yevklid) geometriyasi — harakatlarda saqlanadigan xossalar: uzunlik, burchak, yuz. O‘xshashlik geometriyasi esa gomotetiyani ham qo‘shadi va faqat burchaklar va nisbatlarni o‘rganadi. Bu g‘oya keyinchalik fizikaga ham ta’sir qildi: Eynshteynning nisbiylik nazariyasi ham simmetriyalar tiliga tayanadi.', 'В 1872 году 23-летний немецкий математик <b>Феликс Клейн</b>, став профессором Эрлангенского университета, выдвинул знаменитую <b>«Эрлангенскую программу»</b>. Её идея: каждая геометрия — это некоторая группа преобразований и наука о свойствах, не меняющихся при этих преобразованиях. Школьная (евклидова) геометрия изучает свойства, сохраняющиеся при движениях: длины, углы, площади. Геометрия подобия добавляет гомотетии и изучает только углы и отношения. Эта идея повлияла и на физику: теория относительности Эйнштейна тоже говорит на языке симметрий.', 'In 1872 the 23-year-old German mathematician <b>Felix Klein</b>, on becoming a professor at the University of Erlangen, announced his famous <b>Erlangen programme</b>. Its idea: every geometry is a group of transformations together with the study of the properties that do not change under them. School (Euclidean) geometry studies what isometries keep: lengths, angles, areas. Similarity geometry adds dilations and studies only angles and ratios. The idea later influenced physics too: Einstein’s relativity also speaks the language of symmetry.')
    ] },
    { kind: 'rule', h: L('Parallel ko‘chirish', 'Параллельный перенос', 'Translation'), p: [
      L('<b>Ta’rif.</b> a→ vektor berilgan bo‘lsin. Har bir X nuqtani XX′ = a→ shartni qanoatlantiruvchi X′ nuqtaga o‘tkazuvchi almashtirish <b>a→ vektorga parallel ko‘chirish</b> deyiladi. Barcha nuqtalar bir xil yo‘nalishda, bir xil masofaga siljiydi.', '<b>Определение.</b> Пусть дан вектор a→. Преобразование, переводящее каждую точку X в такую точку X′, что XX′ = a→, называется <b>параллельным переносом на вектор a→</b>. Все точки сдвигаются в одном направлении на одно и то же расстояние.', '<b>Definition.</b> Let a vector a→ be given. The transformation sending each point X to the point X′ with XX′ = a→ is the <b>translation by a→</b>. All points move the same distance in the same direction.'),
      L('<b>Koordinatalarda:</b> a→(a; b) vektorga ko‘chirishda (x; y) → (x + a; y + b). <b>Teorema:</b> parallel ko‘chirish — harakat. <b>Isbot:</b> A(x<sub>1</sub>; y<sub>1</sub>), B(x<sub>2</sub>; y<sub>2</sub>) nuqtalar A′(x<sub>1</sub> + a; y<sub>1</sub> + b), B′(x<sub>2</sub> + a; y<sub>2</sub> + b) ga o‘tadi. Koordinatalar ayirmasi: (x<sub>2</sub> + a) − (x<sub>1</sub> + a) = x<sub>2</sub> − x<sub>1</sub>, y uchun ham xuddi shunday. Masofa formulasidagi ayirmalar o‘zgarmagani uchun A′B′ = AB.', '<b>В координатах:</b> при переносе на вектор a→(a; b) (x; y) → (x + a; y + b). <b>Теорема:</b> параллельный перенос — движение. <b>Доказательство:</b> точки A(x<sub>1</sub>; y<sub>1</sub>), B(x<sub>2</sub>; y<sub>2</sub>) переходят в A′(x<sub>1</sub> + a; y<sub>1</sub> + b), B′(x<sub>2</sub> + a; y<sub>2</sub> + b). Разность координат: (x<sub>2</sub> + a) − (x<sub>1</sub> + a) = x<sub>2</sub> − x<sub>1</sub>, для y так же. Разности в формуле расстояния не изменились, поэтому A′B′ = AB.', '<b>In coordinates:</b> the translation by a→(a; b) sends (x; y) → (x + a; y + b). <b>Theorem:</b> a translation is an isometry. <b>Proof:</b> A(x<sub>1</sub>; y<sub>1</sub>) and B(x<sub>2</sub>; y<sub>2</sub>) go to A′(x<sub>1</sub> + a; y<sub>1</sub> + b) and B′(x<sub>2</sub> + a; y<sub>2</sub> + b). The coordinate difference is (x<sub>2</sub> + a) − (x<sub>1</sub> + a) = x<sub>2</sub> − x<sub>1</sub>, and the same for y. The differences in the distance formula are unchanged, so A′B′ = AB.'),
      L('<b>Xossalar:</b> parallel ko‘chirishda to‘g‘ri chiziq o‘ziga parallel (yoki o‘zi bilan ustma-ust tushuvchi) to‘g‘ri chiziqqa o‘tadi; ikki ketma-ket ko‘chirish — a→ + b→ vektorga bitta ko‘chirish; nol vektorga ko‘chirish — ayniy almashtirish; a→ ga ko‘chirishni −a→ ga ko‘chirish «bekor qiladi».', '<b>Свойства:</b> при переносе прямая переходит в параллельную ей (или в себя); два переноса подряд — один перенос на вектор a→ + b→; перенос на нулевой вектор — тождественное преобразование; перенос на −a→ «отменяет» перенос на a→.', '<b>Properties:</b> a translation sends a line to a parallel line (or to itself); two translations in a row equal one translation by a→ + b→; translating by the zero vector is the identity; translating by −a→ “undoes” translating by a→.')
    ] },
    { kind: 'steps', h: L('Parallel ko‘chirishni qurish', 'Построение параллельного переноса', 'Constructing a translation'), list: [
      L('1. Ko‘chirish vektorini aniqlang: u berilgan bo‘lishi yoki bitta nuqta va uning tasviridan topilishi mumkin: a→ = AA′ = (x′ − x; y′ − y).', '1. Определите вектор переноса: он дан или находится по точке и её образу: a→ = AA′ = (x′ − x; y′ − y).', '1. Find the translation vector: it is given, or found from a point and its image: a→ = AA′ = (x′ − x; y′ − y).'),
      L('2. Shaklning har bir uchidan shu vektorga teng (parallel, bir xil yo‘nalishli va uzunlikli) kesma qo‘ying.', '2. От каждой вершины фигуры отложите отрезок, равный этому вектору (параллельный, того же направления и длины).', '2. From each vertex of the figure, draw a segment equal to the vector (parallel, same direction and length).'),
      L('3. Koordinatalarda: har bir uch koordinatalariga vektor koordinatalarini qo‘shing.', '3. В координатах: прибавьте координаты вектора к координатам каждой вершины.', '3. In coordinates: add the vector’s coordinates to each vertex’s coordinates.'),
      L('4. Hosil bo‘lgan uchlarni xuddi asl shakldagi tartibda tutashtiring.', '4. Соедините полученные вершины в том же порядке, что и у исходной фигуры.', '4. Join the new vertices in the same order as in the original figure.'),
      L('5. Tekshiring: mos tomonlar parallel va teng bo‘lishi, asl va yangi uchlarni tutashtiruvchi kesmalar esa o‘zaro parallel va teng bo‘lishi kerak.', '5. Проверьте: соответственные стороны должны быть параллельны и равны, а отрезки, соединяющие старые и новые вершины, — параллельны и равны между собой.', '5. Check: corresponding sides must be parallel and equal, and the segments joining old and new vertices must all be parallel and equal.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('A(2; −3) nuqta B(−1; 4) ga o‘tadigan parallel ko‘chirishda C(5; 0) nuqta qayerga o‘tadi?', 'При параллельном переносе точка A(2; −3) переходит в B(−1; 4). Куда перейдёт точка C(5; 0)?', 'A translation sends A(2; −3) to B(−1; 4). Where does C(5; 0) go?'),
        s: L('Vektor: a→ = (−1 − 2; 4 − (−3)) = (−3; 7). C′ = (5 − 3; 0 + 7) = (2; 7).', 'Вектор: a→ = (−1 − 2; 4 − (−3)) = (−3; 7). C′ = (5 − 3; 0 + 7) = (2; 7).', 'Vector: a→ = (−1 − 2; 4 − (−3)) = (−3; 7). So C′ = (5 − 3; 0 + 7) = (2; 7).') },
      { q: L('y = 2x + 1 to‘g‘ri chiziq a→(3; −1) vektorga ko‘chirilganda qanday tenglamali to‘g‘ri chiziqqa o‘tadi?', 'В какую прямую переходит прямая y = 2x + 1 при переносе на вектор a→(3; −1)?', 'What line does y = 2x + 1 become under the translation by a→(3; −1)?'),
        s: L('Yangi nuqta (x′; y′) = (x + 3; y − 1), demak x = x′ − 3, y = y′ + 1. Tenglamaga qo‘yamiz: y′ + 1 = 2(x′ − 3) + 1, y′ = 2x′ − 6. Javob: y = 2x − 6. Burchak koeffitsiyenti 2 saqlandi — to‘g‘ri chiziq parallel.', 'Новая точка (x′; y′) = (x + 3; y − 1), значит, x = x′ − 3, y = y′ + 1. Подставим: y′ + 1 = 2(x′ − 3) + 1, y′ = 2x′ − 6. Ответ: y = 2x − 6. Угловой коэффициент 2 сохранился — прямая параллельна.', 'The new point is (x′; y′) = (x + 3; y − 1), so x = x′ − 3 and y = y′ + 1. Substitute: y′ + 1 = 2(x′ − 3) + 1, so y′ = 2x′ − 6. Answer: y = 2x − 6. The slope 2 is kept — the line is parallel.') },
      { q: L('(x − 1)<sup>2</sup> + (y + 2)<sup>2</sup> = 9 aylana a→(−4; 5) ga ko‘chirildi. Yangi aylana tenglamasi?', 'Окружность (x − 1)<sup>2</sup> + (y + 2)<sup>2</sup> = 9 перенесли на вектор a→(−4; 5). Уравнение новой окружности?', 'The circle (x − 1)<sup>2</sup> + (y + 2)<sup>2</sup> = 9 is translated by a→(−4; 5). Its new equation?'),
        s: L('Markaz (1; −2) → (−3; 3), radius 3 o‘zgarmaydi (harakat). Javob: (x + 3)<sup>2</sup> + (y − 3)<sup>2</sup> = 9.', 'Центр (1; −2) → (−3; 3), радиус 3 не меняется (движение). Ответ: (x + 3)<sup>2</sup> + (y − 3)<sup>2</sup> = 9.', 'The centre (1; −2) goes to (−3; 3) and the radius 3 stays (it is an isometry). Answer: (x + 3)<sup>2</sup> + (y − 3)<sup>2</sup> = 9.') },
      { q: L('Ko‘prik masalasi: A va B qishloqlar kengligi d bo‘lgan to‘g‘ri daryoning ikki tomonida. Daryoga perpendikulyar ko‘prikni qayerga qursak, A dan B gacha yo‘l eng qisqa bo‘ladi?', 'Задача о мосте: деревни A и B на разных берегах прямой реки ширины d. Где построить мост перпендикулярно реке, чтобы путь из A в B был кратчайшим?', 'The bridge problem: villages A and B lie on opposite sides of a straight river of width d. Where should a bridge perpendicular to the river be built so that the route from A to B is shortest?'),
        s: L('Ko‘prik uzunligi har doim d, shuning uchun qolgan yo‘lni qisqartirish kerak. A ni daryoga perpendikulyar, uzunligi d bo‘lgan vektorga ko‘chiramiz: A′. A′ ni B bilan to‘g‘ri chiziq bilan tutashtiramiz; u narigi qirg‘oqni kesgan nuqtada ko‘prik tugaydi. Sababi: AM + MN + NB = A′N + d + NB, va A′N + NB eng kichik bo‘ladi, qachonki N A′B kesmada yotsa.', 'Длина моста всегда d, значит, сокращать нужно остальной путь. Перенесём A на вектор длины d, перпендикулярный реке: получим A′. Соединим A′ с B прямой; там, где она пересекает дальний берег, мост заканчивается. Причина: AM + MN + NB = A′N + d + NB, а A′N + NB минимально, когда N лежит на отрезке A′B.', 'The bridge length is always d, so we must shorten the rest. Translate A by a vector of length d perpendicular to the river to get A′. Join A′ to B with a straight line; where it meets the far bank the bridge ends. Reason: AM + MN + NB = A′N + d + NB, and A′N + NB is smallest when N lies on segment A′B.') }
    ] },
    { kind: 'table', h: L('Harakatda nima saqlanadi, nima o‘zgaradi', 'Что сохраняет движение, а что меняет', 'What an isometry keeps and what it changes'), table: {
      head: [L('Xossa', 'Свойство', 'Property'), L('Harakatda', 'При движении', 'Under an isometry'), L('Parallel ko‘chirishda', 'При переносе', 'Under a translation')],
      rows: [
        [L('masofa, uzunlik', 'расстояния, длины', 'distances, lengths'), L('saqlanadi', 'сохраняются', 'kept'), L('saqlanadi', 'сохраняются', 'kept')],
        [L('burchaklar', 'углы', 'angles'), L('saqlanadi', 'сохраняются', 'kept'), L('saqlanadi', 'сохраняются', 'kept')],
        [L('yuz', 'площадь', 'area'), L('saqlanadi', 'сохраняется', 'kept'), L('saqlanadi', 'сохраняется', 'kept')],
        [L('to‘g‘ri chiziq yo‘nalishi', 'направление прямой', 'direction of lines'), L('o‘zgarishi mumkin', 'может меняться', 'may change'), L('saqlanadi', 'сохраняется', 'kept')],
        [L('qo‘zg‘almas nuqtalar', 'неподвижные точки', 'fixed points'), L('bo‘lishi mumkin', 'могут быть', 'may exist'), L('yo‘q (a→ ≠ 0 bo‘lsa)', 'нет (если a→ ≠ 0)', 'none (if a→ ≠ 0)')]
      ] }, after: [
      L('Parallel ko‘chirishning o‘ziga xosligi — u nafaqat uzunliklarni, balki yo‘nalishlarni ham saqlaydi. Har bir kesma o‘ziga parallel kesmaga o‘tadi.', 'Особенность переноса — он сохраняет не только длины, но и направления. Каждый отрезок переходит в параллельный ему отрезок.', 'What is special about a translation is that it keeps not only lengths but also directions: every segment goes to a parallel segment.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Vektorni teskari olish.</b> A → B ko‘chirish vektori B − A, A − B emas. Tekshiring: A ga vektorni qo‘shsangiz, B chiqishi kerak.', '<b>Брать вектор наоборот.</b> Вектор переноса A → B равен B − A, а не A − B. Проверьте: прибавив вектор к A, должны получить B.', '<b>Reversing the vector.</b> The vector of A → B is B − A, not A − B. Check: adding it to A must give B.'),
      L('<b>Tenglamadagi ishorani adashtirish.</b> To‘g‘ri chiziqni (3; −1) ga ko‘chirganda x o‘rniga x − 3, y o‘rniga y + 1 qo‘yiladi — ishoralar teskari! Grafik o‘ngga siljisa, formulada «minus» paydo bo‘ladi.', '<b>Путать знаки в уравнении.</b> При переносе прямой на (3; −1) вместо x подставляют x − 3, вместо y — y + 1: знаки противоположные! Сдвиг графика вправо даёт «минус» в формуле.', '<b>Getting the signs wrong in equations.</b> Translating a line by (3; −1) means replacing x with x − 3 and y with y + 1 — opposite signs! Moving a graph right puts a “minus” in the formula.'),
      L('<b>Har qanday almashtirishni harakat deb hisoblash.</b> (x; y) → (2x; y) almashtirish masofalarni o‘zgartiradi — bu harakat emas.', '<b>Считать любое преобразование движением.</b> Преобразование (x; y) → (2x; y) меняет расстояния — это не движение.', '<b>Calling every transformation an isometry.</b> The map (x; y) → (2x; y) changes distances, so it is not an isometry.'),
      L('<b>Aylana radiusini ham o‘zgartirish.</b> Harakatda faqat markaz siljiydi; radius doim bir xil qoladi.', '<b>Менять и радиус окружности.</b> При движении сдвигается только центр; радиус остаётся прежним.', '<b>Changing the radius of a circle.</b> Under an isometry only the centre moves; the radius stays the same.')
    ] },
    { kind: 'life', h: L('Hayotda harakat va parallel ko‘chirish', 'Движения и переносы в жизни', 'Isometries and translations in real life'), p: [
      L('<b>Naqsh va bordyurlar.</b> Atlas va adras matolaridagi naqshlar, gilam hoshiyalari, devor qog‘ozlari bitta motivni qayta-qayta parallel ko‘chirish orqali hosil qilinadi. Naqqosh bitta «rapport» (takrorlanuvchi bo‘lak) chizadi va uni bir xil vektorga siljitib boradi.', '<b>Узоры и бордюры.</b> Узоры на атласе и адрасе, каймы ковров, обои создаются многократным параллельным переносом одного мотива. Мастер рисует один «раппорт» (повторяющийся фрагмент) и сдвигает его на один и тот же вектор.', '<b>Patterns and borders.</b> The patterns on atlas and adras silk, carpet borders and wallpaper are made by translating one motif again and again. The designer draws one “repeat” and keeps shifting it by the same vector.'),
      L('<b>Kompyuter grafikasi va o‘yinlar.</b> O‘yindagi qahramon yurganda dastur har kadrda uning barcha nuqtalariga bir xil vektorni qo‘shadi: (x; y) → (x + v<sub>x</sub>; y + v<sub>y</sub>). Ekranni aylantirish (skroll) ham parallel ko‘chirish.', '<b>Компьютерная графика и игры.</b> Когда персонаж идёт, программа в каждом кадре прибавляет ко всем его точкам один и тот же вектор: (x; y) → (x + v<sub>x</sub>; y + v<sub>y</sub>). Прокрутка экрана — тоже параллельный перенос.', '<b>Computer graphics and games.</b> When a character walks, the program adds the same vector to all its points every frame: (x; y) → (x + v<sub>x</sub>; y + v<sub>y</sub>). Scrolling a screen is also a translation.'),
      L('<b>Ishlab chiqarish.</b> Konveyer lentasi, lift, eskalator va stanoklarning kesuvchi qismi parallel ko‘chirish bo‘yicha harakatlanadi. Raqamli boshqariladigan (CNC) stanoklarda detal chizmasi koordinatalarda beriladi va asbobni ko‘chirish vektorlar bilan dasturlanadi.', '<b>Производство.</b> Лента конвейера, лифт, эскалатор и режущая часть станка движутся параллельным переносом. На станках с ЧПУ чертёж детали задаётся в координатах, а перемещение инструмента программируется векторами.', '<b>Manufacturing.</b> Conveyor belts, lifts, escalators and machine-tool cutters move by translation. On CNC machines a part is described in coordinates and the tool’s moves are programmed as vectors.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Tekislikdagi har qanday harakat to‘rt turdan biri: parallel ko‘chirish, burish, o‘q simmetriyasi yoki «sirpanuvchi simmetriya» (simmetriya + o‘q bo‘ylab ko‘chirish). Buni XIX asrda Shal isbotlagan.', 'Любое движение плоскости — одно из четырёх: параллельный перенос, поворот, осевая симметрия или «скользящая симметрия» (симметрия + перенос вдоль оси). Это доказал Шаль в XIX веке.', 'Every isometry of the plane is one of four kinds: a translation, a rotation, a reflection or a “glide reflection” (a reflection plus a slide along the axis). Chasles proved this in the 19th century.'),
      L('Har qanday harakat ko‘pi bilan uchta o‘q simmetriyasining kompozitsiyasi sifatida yoziladi. Parallel ko‘chirish — ikkita parallel o‘qqa nisbatan simmetriyalar ketma-ketligi.', 'Любое движение можно записать как композицию не более чем трёх осевых симметрий. Параллельный перенос — это две симметрии относительно параллельных осей.', 'Every isometry can be written as at most three reflections in a row. A translation is two reflections in parallel lines.'),
      L('Bordyur (lenta) naqshlarining faqat 7 turi, devor qog‘ozi naqshlarining esa faqat 17 turi mavjud — buni 1891-yilda Yevgraf Fyodorov isbotlagan.', 'Существует всего 7 типов бордюрных (ленточных) орнаментов и 17 типов обойных узоров — это доказал Евграф Фёдоров в 1891 году.', 'There are only 7 types of frieze (border) patterns and only 17 types of wallpaper patterns, as Evgraf Fedorov proved in 1891.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. A(−2; 5) nuqta a→(4; −3) ga ko‘chirilsa, A′ = ?', '1. Точку A(−2; 5) перенесли на a→(4; −3). A′ = ?', '1. A(−2; 5) is translated by a→(4; −3). A′ = ?'),
      L('2. M(1; 1) → M′(6; −2). Qaysi vektorga ko‘chirish?', '2. M(1; 1) → M′(6; −2). На какой вектор перенос?', '2. M(1; 1) → M′(6; −2). By which vector?'),
      L('3. y = x<sup>2</sup> parabola a→(2; 3) ga ko‘chirilsa, yangi tenglama?', '3. Параболу y = x<sup>2</sup> перенесли на a→(2; 3). Новое уравнение?', '3. The parabola y = x<sup>2</sup> is translated by a→(2; 3). The new equation?'),
      L('4. Ketma-ket (1; 2) va (−3; 4) ga ko‘chirishlar qaysi bitta ko‘chirishga teng?', '4. Какому одному переносу равны последовательные переносы на (1; 2) и (−3; 4)?', '4. Translating by (1; 2) then by (−3; 4) equals which single translation?')
    ], after: [
      L('Javoblar: 1) (2; 2); 2) (5; −3); 3) y = (x − 2)<sup>2</sup> + 3; 4) (−2; 6).', 'Ответы: 1) (2; 2); 2) (5; −3); 3) y = (x − 2)<sup>2</sup> + 3; 4) (−2; 6).', 'Answers: 1) (2; 2); 2) (5; −3); 3) y = (x − 2)<sup>2</sup> + 3; 4) (−2; 6).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Harakat — masofalarni saqlaydigan almashtirish; u shaklni teng shaklga o‘tkazadi.', 'Движение — преобразование, сохраняющее расстояния; оно переводит фигуру в равную.', 'An isometry is a transformation that keeps distances; it maps a figure to a congruent one.'),
      L('Harakatda uzunliklar, burchaklar va yuzlar saqlanadi.', 'При движении сохраняются длины, углы и площади.', 'Isometries keep lengths, angles and areas.'),
      L('Parallel ko‘chirish: XX′ = a→, koordinatalarda (x; y) → (x + a; y + b).', 'Параллельный перенос: XX′ = a→, в координатах (x; y) → (x + a; y + b).', 'Translation: XX′ = a→; in coordinates (x; y) → (x + a; y + b).'),
      L('Parallel ko‘chirish yo‘nalishlarni ham saqlaydi: to‘g‘ri chiziq o‘ziga parallel chiziqqa o‘tadi.', 'Перенос сохраняет и направления: прямая переходит в параллельную.', 'A translation also keeps directions: a line goes to a parallel line.'),
      L('Ikki ko‘chirish kompozitsiyasi — vektorlar yig‘indisiga ko‘chirish.', 'Композиция двух переносов — перенос на сумму векторов.', 'Two translations combine into a translation by the sum of the vectors.'),
      L('Kleyn g‘oyasi: geometriya — almashtirishlarda o‘zgarmaydigan xossalar haqidagi fan.', 'Идея Клейна: геометрия — наука о свойствах, не меняющихся при преобразованиях.', 'Klein’s idea: geometry is the study of what stays unchanged under transformations.')
    ] }
  ] });

  // ---------- t6. O‘q va markaziy simmetriya. Burish ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Ko‘zgu, gildirak va kapalak', 'Зеркало, колесо и бабочка', 'Mirrors, wheels and butterflies'), p: [
      L('Kapalak qanotlari, inson yuzi, Registon peshtoqlari — chap va o‘ng tomonlar bir-birining ko‘zgudagi aksidek. Velosiped g‘ildiragi, gul tojbarglari, qor parchasi esa markaz atrofida aylantirilganda o‘ziga ustma-ust tushadi. Biz bu go‘zallikni «simmetriya» deb ataymiz va ko‘zimiz uni darhol sezadi.', 'Крылья бабочки, человеческое лицо, порталы Регистана — левая и правая половины как отражения друг друга в зеркале. Колесо велосипеда, лепестки цветка, снежинка при повороте вокруг центра совпадают сами с собой. Мы называем эту красоту «симметрией», и глаз сразу её замечает.', 'A butterfly’s wings, a human face, the portals of the Registan — the left and right halves are like mirror images. A bicycle wheel, the petals of a flower and a snowflake land on themselves when turned about their centre. We call this beauty “symmetry”, and our eyes notice it at once.'),
      L('Oldingi mavzuda biz harakat tushunchasi bilan tanishdik va eng sodda harakat — parallel ko‘chirishni o‘rgandik. Endi yana uch muhim harakatni o‘rganamiz: <b>o‘q simmetriyasi</b> (ko‘zgudagi aks), <b>markaziy simmetriya</b> (nuqtaga nisbatan aks) va <b>burish</b> (nuqta atrofida aylantirish). Ular nafaqat chiroyli, balki masalalarni yechishning kuchli vositasi ham.', 'В прошлой теме мы познакомились с понятием движения и изучили простейшее — параллельный перенос. Теперь изучим ещё три важных движения: <b>осевую симметрию</b> (зеркальное отражение), <b>центральную симметрию</b> (отражение относительно точки) и <b>поворот</b> (вращение вокруг точки). Они не только красивы, но и служат сильным инструментом решения задач.', 'In the previous topic we met the idea of an isometry and studied the simplest one, the translation. Now we study three more key isometries: <b>reflection in a line</b> (a mirror image), <b>point symmetry</b> (reflection in a point) and <b>rotation</b> (turning about a point). They are not only beautiful but also powerful problem-solving tools.'),
      L('Masalan, bilyard sharini bortdan qaytarib, boshqa sharga qanday tekkizish mumkin? Daryo bo‘yidagi ikki uydan suv olib kelish uchun eng qisqa yo‘l qaysi? Bunday savollarga ko‘zgu simmetriyasi bir chizg‘ich harakati bilan javob beradi.', 'Например, как, отразив шар от борта, попасть в другой шар в бильярде? Какой путь кратчайший, чтобы дойти от дома до реки за водой и прийти к другому дому? На такие вопросы зеркальная симметрия отвечает одним движением линейки.', 'For example, how do you bounce a billiard ball off the cushion to hit another ball? What is the shortest path from one house to the river and on to another house? Mirror symmetry answers such questions with a single stroke of a ruler.')
    ] },
    { kind: 'def', h: L('Uchta harakatning ta’rifi', 'Определения трёх движений', 'Definitions of the three isometries'), list: [
      L('<b>O‘q simmetriyasi.</b> A va A′ nuqtalar l to‘g‘ri chiziqqa nisbatan simmetrik, agar l AA′ kesmaning o‘rta perpendikulyari bo‘lsa. l ning o‘zidagi nuqtalar joyida qoladi. Har bir X nuqtani l ga nisbatan simmetrik X′ ga o‘tkazuvchi almashtirish — l o‘qqa nisbatan simmetriya.', '<b>Осевая симметрия.</b> Точки A и A′ симметричны относительно прямой l, если l — серединный перпендикуляр к отрезку AA′. Точки самой прямой l остаются на месте. Преобразование, переводящее каждую X в симметричную ей X′, — симметрия относительно оси l.', '<b>Reflection in a line.</b> Points A and A′ are symmetric about the line l if l is the perpendicular bisector of AA′. Points on l stay put. The map sending every X to its mirror image X′ is the reflection in the axis l.'),
      L('<b>Markaziy simmetriya.</b> A va A′ nuqtalar O nuqtaga nisbatan simmetrik, agar O AA′ kesmaning o‘rtasi bo‘lsa. Faqat O nuqtaning o‘zi joyida qoladi.', '<b>Центральная симметрия.</b> Точки A и A′ симметричны относительно точки O, если O — середина отрезка AA′. На месте остаётся только сама точка O.', '<b>Point symmetry.</b> Points A and A′ are symmetric about the point O if O is the midpoint of AA′. Only O itself stays fixed.'),
      L('<b>Burish.</b> O markaz atrofida α burchakka burish har bir A nuqtani shunday A′ ga o‘tkazadiki, OA′ = OA va ∠AOA′ = α (belgilangan yo‘nalishda, odatda soat miliga teskari). 180° ga burish markaziy simmetriya bilan bir xil.', '<b>Поворот.</b> Поворот вокруг центра O на угол α переводит каждую точку A в такую A′, что OA′ = OA и ∠AOA′ = α (в заданном направлении, обычно против часовой стрелки). Поворот на 180° совпадает с центральной симметрией.', '<b>Rotation.</b> A rotation about the centre O through angle α sends each point A to the point A′ with OA′ = OA and ∠AOA′ = α (in a chosen direction, usually anticlockwise). A 180° rotation is the same as point symmetry.'),
      L('<b>Simmetrik shakl:</b> agar shakl biror simmetriya yoki burishda o‘ziga o‘tsa, u shu almashtirishga nisbatan simmetrik; l — uning simmetriya o‘qi, O — simmetriya markazi.', '<b>Симметричная фигура:</b> если фигура при симметрии или повороте переходит в себя, она симметрична относительно этого преобразования; l — её ось симметрии, O — центр симметрии.', '<b>Symmetric figure:</b> if a figure maps onto itself under a reflection or rotation, it is symmetric under it; l is an axis of symmetry and O a centre of symmetry.')
    ] },
    { kind: 'history', h: L('Tarixdan: girih ustalari va Esher', 'Из истории: мастера гириха и Эшер', 'History: girih masters and Escher'), p: [
      L('Simmetriya san’ati Markaziy Osiyoda ayniqsa yuksak darajaga ko‘tarildi. XIV–XV asrlarda Samarqand, Buxoro va Hirot ustalari <b>girih</b> naqshlarini yaratdilar: o‘n, sakkiz va besh qirrali yulduzlar ko‘zgu simmetriyasi va burishlar yordamida cheksiz takrorlanib boradi. Ular ishlatgan to‘rtta-beshta asosiy plitka shakli 2007-yilda olimlar tomonidan qayta o‘rganildi va ba’zi naqshlar XX asrda kashf etilgan «Penrouz mozaikasi»ga juda yaqin ekani aniqlandi.', 'Искусство симметрии особенно высоко поднялось в Центральной Азии. В XIV–XV веках мастера Самарканда, Бухары и Герата создавали узоры <b>гирих</b>: десяти-, восьми- и пятиконечные звёзды бесконечно повторяются с помощью зеркальных симметрий и поворотов. Набор из нескольких основных плиток, которыми они пользовались, учёные заново исследовали в 2007 году и обнаружили, что некоторые узоры очень близки к «мозаике Пенроуза», открытой в XX веке.', 'The art of symmetry reached great heights in Central Asia. In the 14th–15th centuries the masters of Samarkand, Bukhara and Herat created <b>girih</b> patterns in which ten-, eight- and five-pointed stars repeat endlessly through reflections and rotations. In 2007 researchers re-examined the small set of basic tiles they used and found that some patterns come very close to the “Penrose tiling” discovered in the 20th century.'),
      L('XX asrda gollandiyalik rassom <b>Moris Esher</b> 1922 va 1936-yillarda Ispaniyadagi Alhambra saroyiga borib, u yerdagi islomiy naqshlarni sinchiklab chizib oldi. Shundan keyin u qushlar, baliqlar va kaltakesaklardan iborat mashhur mozaikalarini yaratdi: har bir figura parallel ko‘chirish, burish va sirpanuvchi simmetriya bilan tekislikni bo‘shliqsiz to‘ldiradi. Esher matematik bo‘lmasa-da, uning ishlari kristallograflar va geometrlarni hayratga solgan. Simmetriyaning qat’iy nazariyasini esa XIX asrda <b>Galua</b> va <b>Kleyn</b> g‘oyalari asosida qurilgan «guruhlar nazariyasi» berdi.', 'В XX веке голландский художник <b>Мауриц Эшер</b> в 1922 и 1936 годах посетил дворец Альгамбра в Испании и тщательно зарисовал исламские орнаменты. После этого он создал свои знаменитые мозаики из птиц, рыб и ящериц: каждая фигура с помощью переносов, поворотов и скользящих симметрий заполняет плоскость без щелей. Эшер не был математиком, но его работы восхищали кристаллографов и геометров. Строгую же теорию симметрии дала «теория групп», выросшая в XIX веке из идей <b>Галуа</b> и <b>Клейна</b>.', 'In the 20th century the Dutch artist <b>M. C. Escher</b> visited the Alhambra palace in Spain in 1922 and 1936 and carefully sketched its Islamic ornaments. Afterwards he created his famous tessellations of birds, fish and lizards: each figure fills the plane without gaps through translations, rotations and glide reflections. Escher was not a mathematician, yet his work fascinated crystallographers and geometers. The rigorous theory of symmetry came from “group theory”, which grew in the 19th century out of the ideas of <b>Galois</b> and <b>Klein</b>.')
    ] },
    { kind: 'rule', h: L('Koordinatalardagi formulalar va isbot g‘oyasi', 'Формулы в координатах и идея доказательства', 'Coordinate formulas and the proof idea'), p: [
      L('<b>Ox o‘qqa nisbatan:</b> (x; y) → (x; −y). <b>Oy o‘qqa nisbatan:</b> (x; y) → (−x; y). <b>y = x to‘g‘ri chiziqqa nisbatan:</b> (x; y) → (y; x). <b>Koordinata boshiga nisbatan:</b> (x; y) → (−x; −y). <b>M(a; b) nuqtaga nisbatan:</b> (x; y) → (2a − x; 2b − y), chunki M kesma o‘rtasi.', '<b>Относительно оси Ox:</b> (x; y) → (x; −y). <b>Относительно Oy:</b> (x; y) → (−x; y). <b>Относительно прямой y = x:</b> (x; y) → (y; x). <b>Относительно начала координат:</b> (x; y) → (−x; −y). <b>Относительно точки M(a; b):</b> (x; y) → (2a − x; 2b − y), ведь M — середина отрезка.', '<b>In the axis Ox:</b> (x; y) → (x; −y). <b>In Oy:</b> (x; y) → (−x; y). <b>In the line y = x:</b> (x; y) → (y; x). <b>In the origin:</b> (x; y) → (−x; −y). <b>In the point M(a; b):</b> (x; y) → (2a − x; 2b − y), because M is the midpoint.'),
      L('<b>Koordinata boshi atrofida burish:</b> 90° ga (soat miliga teskari) — (x; y) → (−y; x); 180° ga — (−x; −y); 270° ga (yoki soat mili bo‘yicha 90°) — (y; −x).', '<b>Поворот вокруг начала координат:</b> на 90° (против часовой) — (x; y) → (−y; x); на 180° — (−x; −y); на 270° (или по часовой на 90°) — (y; −x).', '<b>Rotation about the origin:</b> by 90° (anticlockwise) — (x; y) → (−y; x); by 180° — (−x; −y); by 270° (or 90° clockwise) — (y; −x).'),
      L('<b>Teorema:</b> o‘q simmetriyasi, markaziy simmetriya va burish — harakatlar. <b>Isbot g‘oyasi (markaziy simmetriya uchun):</b> A va B nuqtalar A′ va B′ ga o‘tsin. △AOB va △A′OB′ da OA = OA′, OB = OB′, ∠AOB = ∠A′OB′ (vertikal burchaklar). TBT bo‘yicha uchburchaklar teng, demak A′B′ = AB. Burish uchun ham xuddi shunday: ∠AOB = ∠A′OB′, chunki ikkala burchakdan bir xil α «ko‘chirildi».', '<b>Теорема:</b> осевая симметрия, центральная симметрия и поворот — движения. <b>Идея доказательства (для центральной симметрии):</b> пусть A и B переходят в A′ и B′. В △AOB и △A′OB′ OA = OA′, OB = OB′, ∠AOB = ∠A′OB′ (вертикальные). По СУС треугольники равны, значит, A′B′ = AB. Для поворота так же: ∠AOB = ∠A′OB′, потому что оба угла «сдвинуты» на одно и то же α.', '<b>Theorem:</b> reflections, point symmetries and rotations are isometries. <b>Proof idea (for point symmetry):</b> let A and B go to A′ and B′. In △AOB and △A′OB′, OA = OA′, OB = OB′ and ∠AOB = ∠A′OB′ (vertical angles). By SAS the triangles are congruent, so A′B′ = AB. For a rotation it is the same: ∠AOB = ∠A′OB′, since both angles are “shifted” by the same α.'),
      L('<b>Muhim farq:</b> burish va parallel ko‘chirish shakl «yo‘nalishini» (soat mili bo‘ylab aylanib chiqish tartibini) saqlaydi, o‘q simmetriyasi esa uni teskarisiga o‘zgartiradi: chap qo‘lqop ko‘zguda o‘ng qo‘lqopga aylanadi.', '<b>Важное отличие:</b> поворот и перенос сохраняют «ориентацию» фигуры (порядок обхода по часовой стрелке), а осевая симметрия её меняет: левая перчатка в зеркале становится правой.', '<b>An important difference:</b> rotations and translations keep a figure’s “orientation” (the clockwise order of its vertices), while a reflection reverses it: a left glove becomes a right glove in the mirror.')
    ] },
    { kind: 'steps', h: L('Simmetrik shaklni yasash', 'Построение симметричной фигуры', 'Constructing a symmetric image'), list: [
      L('1. Shaklning har bir uchidan o‘qqa perpendikulyar tushiring (o‘q simmetriyasi) yoki markaz orqali to‘g‘ri chiziq o‘tkazing (markaziy simmetriya).', '1. Из каждой вершины фигуры опустите перпендикуляр на ось (осевая симметрия) или проведите прямую через центр (центральная).', '1. From each vertex drop a perpendicular to the axis (reflection) or draw a line through the centre (point symmetry).'),
      L('2. Perpendikulyarni o‘qdan narigi tomonga xuddi shu uzunlikda davom ettiring; markaziy simmetriyada esa markazdan narigi tomonga xuddi shu masofani qo‘ying.', '2. Продолжите перпендикуляр за ось на такую же длину; при центральной симметрии отложите то же расстояние за центром.', '2. Extend the perpendicular past the axis by the same length; for point symmetry, mark the same distance beyond the centre.'),
      L('3. Burishda: markazni uch bilan tutashtiring, transportir bilan α burchak qo‘ying va shu nurda markazdan bir xil masofani o‘lchang.', '3. При повороте: соедините центр с вершиной, отложите транспортиром угол α и на этом луче отмерьте от центра то же расстояние.', '3. For a rotation: join the centre to the vertex, mark the angle α with a protractor and measure the same distance from the centre along the new ray.'),
      L('4. Hosil bo‘lgan nuqtalarni asl tartibda tutashtiring.', '4. Соедините полученные точки в исходном порядке.', '4. Join the new points in the original order.'),
      L('5. Tekshiring: tomonlar uzunligi o‘zgarmagan bo‘lishi kerak; o‘q simmetriyasida harflar tartibi teskari aylanadi.', '5. Проверьте: длины сторон не должны измениться; при осевой симметрии порядок обхода вершин меняется на обратный.', '5. Check that side lengths are unchanged; under a reflection the order of the vertices is reversed.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('A(3; −5) nuqtaga Ox, Oy va koordinata boshiga nisbatan simmetrik nuqtalarni toping.', 'Найдите точки, симметричные A(3; −5) относительно Ox, Oy и начала координат.', 'Find the images of A(3; −5) in Ox, in Oy and in the origin.'),
        s: L('Ox: (3; 5). Oy: (−3; −5). O: (−3; 5). Tekshirish: koordinata boshiga nisbatan simmetriya — ketma-ket Ox va Oy simmetriyalari.', 'Ox: (3; 5). Oy: (−3; −5). O: (−3; 5). Проверка: симметрия относительно начала — это последовательные симметрии относительно Ox и Oy.', 'Ox: (3; 5). Oy: (−3; −5). Origin: (−3; 5). Check: reflecting in the origin is the same as reflecting in Ox and then in Oy.') },
      { q: L('A(1; 4) nuqtaning M(3; 2) nuqtaga nisbatan simmetrigini toping.', 'Найдите точку, симметричную A(1; 4) относительно M(3; 2).', 'Find the image of A(1; 4) in the point M(3; 2).'),
        s: L('M — AA′ ning o‘rtasi: 3 = (1 + x)/2, x = 5; 2 = (4 + y)/2, y = 0. A′(5; 0). Formula bilan: (2 · 3 − 1; 2 · 2 − 4) = (5; 0).', 'M — середина AA′: 3 = (1 + x)/2, x = 5; 2 = (4 + y)/2, y = 0. A′(5; 0). По формуле: (2 · 3 − 1; 2 · 2 − 4) = (5; 0).', 'M is the midpoint of AA′: 3 = (1 + x)/2 gives x = 5; 2 = (4 + y)/2 gives y = 0. So A′(5; 0). By the formula: (2 · 3 − 1; 2 · 2 − 4) = (5; 0).') },
      { q: L('Uchlari A(1; 0), B(4; 0), C(4; 2) bo‘lgan uchburchak koordinata boshi atrofida 90° ga burildi. Yangi uchlarni toping va yuzlar tengligini tekshiring.', 'Треугольник с вершинами A(1; 0), B(4; 0), C(4; 2) повернули вокруг начала на 90°. Найдите новые вершины и проверьте равенство площадей.', 'The triangle A(1; 0), B(4; 0), C(4; 2) is rotated 90° about the origin. Find the new vertices and check the areas are equal.'),
        s: L('(x; y) → (−y; x): A′(0; 1), B′(0; 4), C′(−2; 4). Asl uchburchak: katetlar 3 va 2, S = 3. Yangisi: A′B′ = 3 (Oy bo‘ylab), B′C′ = 2 (gorizontal), S = 3. Harakat yuzni saqladi.', '(x; y) → (−y; x): A′(0; 1), B′(0; 4), C′(−2; 4). Исходный треугольник: катеты 3 и 2, S = 3. Новый: A′B′ = 3 (по Oy), B′C′ = 2 (горизонтально), S = 3. Движение сохранило площадь.', '(x; y) → (−y; x): A′(0; 1), B′(0; 4), C′(−2; 4). The original has legs 3 and 2, so S = 3. The new one has A′B′ = 3 (along Oy) and B′C′ = 2 (horizontal), so S = 3. The isometry kept the area.') },
      { q: L('Geron masalasi: A va B nuqtalar l to‘g‘ri chiziqning bir tomonida. l da shunday M nuqta topingki, AM + MB eng kichik bo‘lsin.', 'Задача Герона: точки A и B по одну сторону от прямой l. Найдите на l точку M, для которой AM + MB наименьшая.', 'Heron’s problem: A and B lie on the same side of line l. Find the point M on l for which AM + MB is smallest.'),
        s: L('B ni l ga nisbatan aks ettiramiz: B′. l dagi istalgan M uchun MB = MB′, shuning uchun AM + MB = AM + MB′. Bu yig‘indi eng kichik bo‘ladi, qachonki M AB′ kesmada yotsa. Demak M = AB′ ∩ l. Shu nuqtada «tushish burchagi = qaytish burchagi» — yorug‘lik ham aynan shunday qaytadi.', 'Отразим B относительно l: B′. Для любой M на l MB = MB′, значит, AM + MB = AM + MB′. Сумма наименьшая, когда M лежит на отрезке AB′. Итак, M = AB′ ∩ l. В этой точке «угол падения = углу отражения» — так отражается и свет.', 'Reflect B in l to get B′. For any M on l, MB = MB′, so AM + MB = AM + MB′. That sum is smallest when M lies on segment AB′. So M is where AB′ meets l. At that point “angle of incidence = angle of reflection” — exactly how light bounces.') },
      { q: L('Muntazam oltiburchakning nechta simmetriya o‘qi bor va u qaysi burchaklarga burilganda o‘ziga o‘tadi?', 'Сколько осей симметрии у правильного шестиугольника и при каких поворотах он совмещается с собой?', 'How many axes of symmetry does a regular hexagon have, and which rotations map it onto itself?'),
        s: L('6 ta o‘q: 3 tasi qarama-qarshi uchlar orqali, 3 tasi qarama-qarshi tomonlar o‘rtalari orqali. Burishlar: 60°, 120°, 180°, 240°, 300° (va 360°). 180° li burish borligi uchun oltiburchakning simmetriya markazi ham bor.', '6 осей: 3 через противоположные вершины и 3 через середины противоположных сторон. Повороты: 60°, 120°, 180°, 240°, 300° (и 360°). Есть поворот на 180°, значит, есть и центр симметрии.', '6 axes: 3 through opposite vertices and 3 through midpoints of opposite sides. Rotations: 60°, 120°, 180°, 240°, 300° (and 360°). Since 180° is among them, the hexagon also has a centre of symmetry.') }
    ] },
    { kind: 'table', h: L('Shakllarning simmetriyalari', 'Симметрии фигур', 'Symmetries of figures'), table: {
      head: [L('Shakl', 'Фигура', 'Figure'), L('Simmetriya o‘qlari', 'Оси симметрии', 'Axes'), L('Markaz', 'Центр', 'Centre'), L('Eng kichik burish', 'Наименьший поворот', 'Smallest turn')],
      rows: [
        [L('teng yonli uchburchak', 'равнобедренный треугольник', 'isosceles triangle'), '1', L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'none')],
        [L('teng tomonli uchburchak', 'равносторонний треугольник', 'equilateral triangle'), '3', L('yo‘q', 'нет', 'no'), '120°'],
        [L('parallelogramm', 'параллелограмм', 'parallelogram'), '0', L('bor', 'есть', 'yes'), '180°'],
        [L('to‘g‘ri to‘rtburchak', 'прямоугольник', 'rectangle'), '2', L('bor', 'есть', 'yes'), '180°'],
        [L('romb', 'ромб', 'rhombus'), '2', L('bor', 'есть', 'yes'), '180°'],
        [L('kvadrat', 'квадрат', 'square'), '4', L('bor', 'есть', 'yes'), '90°'],
        [L('muntazam n-burchak', 'правильный n-угольник', 'regular n-gon'), 'n', L('n juft bo‘lsa', 'если n чётное', 'if n is even'), L('360° : n', '360° : n', '360° ÷ n')],
        [L('aylana', 'окружность', 'circle'), L('cheksiz', 'бесконечно', 'infinitely many'), L('bor', 'есть', 'yes'), L('istalgan', 'любой', 'any')]
      ] }, after: [
      L('Qiziq: parallelogrammning simmetriya o‘qi yo‘q, lekin markazi bor. Teng tomonli uchburchakning esa uchta o‘qi bor, lekin markaziy simmetriyasi yo‘q.', 'Интересно: у параллелограмма нет оси симметрии, но есть центр. А у равностороннего треугольника три оси, но нет центральной симметрии.', 'Interesting: a parallelogram has no axis of symmetry but does have a centre, while an equilateral triangle has three axes but no point symmetry.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Ox va Oy simmetriyalarini adashtirish.</b> Ox ga nisbatan aks ettirganda Ox ustidagi koordinata (x) o‘zgarmaydi, y ishorasi o‘zgaradi. Esda tuting: «o‘q bo‘ylab koordinata qoladi».', '<b>Путать симметрии относительно Ox и Oy.</b> При отражении в Ox не меняется координата вдоль оси (x), меняется знак y. Запомните: «координата вдоль оси остаётся».', '<b>Mixing up reflections in Ox and Oy.</b> Reflecting in Ox keeps the coordinate along that axis (x) and flips the sign of y. Remember: “the coordinate along the axis stays”.'),
      L('<b>90° burishda (−y; x) o‘rniga (y; −x) yozish.</b> Bu soat mili bo‘yicha burish. Tekshiring: (1; 0) soat miliga teskari 90° burilsa, (0; 1) ga o‘tishi kerak.', '<b>Писать (y; −x) вместо (−y; x) при повороте на 90°.</b> Это поворот по часовой стрелке. Проверьте: (1; 0) при повороте против часовой на 90° должна перейти в (0; 1).', '<b>Writing (y; −x) instead of (−y; x) for a 90° turn.</b> That is the clockwise turn. Check: (1; 0) turned 90° anticlockwise must go to (0; 1).'),
      L('<b>Parallelogrammni diagonaliga nisbatan simmetrik deb o‘ylash.</b> Bu faqat rombda to‘g‘ri. Oddiy parallelogramm diagonal bo‘yicha buklanganda yarmilari ustma-ust tushmaydi.', '<b>Думать, что параллелограмм симметричен относительно диагонали.</b> Это верно только для ромба. Обычный параллелограмм, сложенный по диагонали, не совпадает половинками.', '<b>Thinking a parallelogram is symmetric about a diagonal.</b> That is true only for a rhombus. An ordinary parallelogram folded along a diagonal does not match up.'),
      L('<b>Markaziy simmetriyada masofani ikki marta olmaslik.</b> A′ markazdan A bilan bir xil masofada, ya’ni AA′ = 2 · AO.', '<b>Не удваивать расстояние при центральной симметрии.</b> A′ на том же расстоянии от центра, что и A, то есть AA′ = 2 · AO.', '<b>Not doubling the distance in point symmetry.</b> A′ is as far from the centre as A, so AA′ = 2 · AO.')
    ] },
    { kind: 'life', h: L('Hayotda simmetriya va burish', 'Симметрия и поворот в жизни', 'Symmetry and rotation in real life'), p: [
      L('<b>Ko‘zgu va bilyard.</b> Ko‘zgudagi aks — o‘q simmetriyasining eng tanish misoli. Bilyardchi sharni bortdan qaytarib urishda nishon sharni bortga nisbatan «aks ettiradi» va o‘sha xayoliy nuqtaga nishon oladi. Periskop va avtomobil oynalari ham shu qonunga bo‘ysunadi.', '<b>Зеркало и бильярд.</b> Отражение в зеркале — самый знакомый пример осевой симметрии. Бильярдист при ударе через борт «отражает» прицельный шар относительно борта и целится в эту мнимую точку. Перископ и автомобильные зеркала подчиняются тому же закону.', '<b>Mirrors and billiards.</b> A mirror image is the most familiar reflection. A billiards player bouncing a ball off the cushion “reflects” the target ball in the cushion and aims at that imaginary point. Periscopes and car mirrors obey the same law.'),
      L('<b>Texnika.</b> G‘ildirak, tishli uzatma, vintilyator, turbina — burish simmetriyasiga ega. Tishli g‘ildirakda 20 ta tish bo‘lsa, u 18° ga burilganda o‘ziga o‘tadi. Avtomobil g‘ildiragi disklari ko‘pincha 5 ta murvat bilan mahkamlanadi — 72° li simmetriya.', '<b>Техника.</b> Колесо, зубчатая передача, вентилятор, турбина обладают поворотной симметрией. Шестерня с 20 зубьями совмещается с собой при повороте на 18°. Автомобильные диски часто крепят 5 болтами — симметрия на 72°.', '<b>Engineering.</b> Wheels, gears, fans and turbines have rotational symmetry. A gear with 20 teeth maps onto itself when turned by 18°. Car wheels are often fixed with 5 bolts — a 72° symmetry.'),
      L('<b>Tabiat va dizayn.</b> Qor parchasi 60° li burish simmetriyasiga ega, chunki suv molekulalari kristallda oltiburchak panjara hosil qiladi. Logotip dizaynerlari, me’morlar va naqqoshlar simmetriyani muvozanat va go‘zallik uchun ongli ravishda qo‘llaydi.', '<b>Природа и дизайн.</b> Снежинка обладает поворотной симметрией на 60°, потому что молекулы воды в кристалле образуют шестиугольную решётку. Дизайнеры логотипов, архитекторы и орнаменталисты сознательно используют симметрию ради равновесия и красоты.', '<b>Nature and design.</b> A snowflake has 60° rotational symmetry because water molecules form a hexagonal lattice in the crystal. Logo designers, architects and ornament makers use symmetry on purpose for balance and beauty.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Ikki kesishuvchi o‘qqa nisbatan ketma-ket simmetriyalar — ular orasidagi burchakning ikki barobariga burish. Ikki parallel o‘qqa nisbatan esa — parallel ko‘chirish.', 'Две симметрии относительно пересекающихся осей подряд дают поворот на удвоенный угол между осями. А относительно параллельных осей — параллельный перенос.', 'Two reflections in intersecting lines give a rotation through twice the angle between them; in parallel lines they give a translation.'),
      L('«ABA», «DOD», «TOT» kabi so‘zlar vertikal o‘qqa nisbatan simmetrik yoziladi; «NOON» esa 180° ga burilganda «NOON» bo‘lib qoladi.', 'Слова вроде «ABA», «ТОТ» имеют вертикальную ось симметрии, а «NOON» при повороте на 180° остаётся «NOON».', 'Words like “ABA” or “TOT” have a vertical axis of symmetry, and “NOON” reads the same after a 180° turn.'),
      L('Odam yuzi faqat taxminan simmetrik. Agar yuzning bir yarmini ko‘zguda aks ettirib to‘liq yuz yasasangiz, u odatda tanib bo‘lmaydigan darajada boshqacha ko‘rinadi.', 'Лицо человека симметрично лишь приблизительно. Если отразить одну половину лица и собрать целое лицо, оно обычно выглядит заметно иначе.', 'A human face is only roughly symmetric. If you mirror one half to build a whole face, it usually looks noticeably different.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. B(−4; 7) ning Oy ga nisbatan simmetrigi?', '1. Точка, симметричная B(−4; 7) относительно Oy?', '1. The image of B(−4; 7) in Oy?'),
      L('2. (5; −2) nuqta koordinata boshi atrofida 90° ga burilsa?', '2. Точку (5; −2) повернули вокруг начала на 90°. Результат?', '2. Rotate (5; −2) by 90° about the origin.'),
      L('3. A(2; 3) va A′(6; −1) nuqtalar qaysi nuqtaga nisbatan simmetrik?', '3. Относительно какой точки симметричны A(2; 3) и A′(6; −1)?', '3. About which point are A(2; 3) and A′(6; −1) symmetric?'),
      L('4. Muntazam beshburchakning simmetriya markazi bormi?', '4. Есть ли у правильного пятиугольника центр симметрии?', '4. Does a regular pentagon have a centre of symmetry?')
    ], after: [
      L('Javoblar: 1) (4; 7); 2) (2; 5); 3) o‘rtasi (4; 1); 4) yo‘q — n toq, eng kichik burish 72°, 180° esa 72° ga karrali emas.', 'Ответы: 1) (4; 7); 2) (2; 5); 3) середина (4; 1); 4) нет — n нечётное, наименьший поворот 72°, а 180° ему не кратно.', 'Answers: 1) (4; 7); 2) (2; 5); 3) the midpoint (4; 1); 4) no — n is odd, the smallest turn is 72°, and 180° is not a multiple of it.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘q simmetriyasida o‘q AA′ ning o‘rta perpendikulyari; Ox: (x; −y), Oy: (−x; y).', 'При осевой симметрии ось — серединный перпендикуляр к AA′; Ox: (x; −y), Oy: (−x; y).', 'In a reflection the axis is the perpendicular bisector of AA′; Ox: (x; −y), Oy: (−x; y).'),
      L('Markaziy simmetriyada markaz AA′ ning o‘rtasi; O ga nisbatan (−x; −y).', 'При центральной симметрии центр — середина AA′; относительно O: (−x; −y).', 'In point symmetry the centre is the midpoint of AA′; about O: (−x; −y).'),
      L('Burish: OA′ = OA, ∠AOA′ = α; 90° da (x; y) → (−y; x); 180° burish = markaziy simmetriya.', 'Поворот: OA′ = OA, ∠AOA′ = α; на 90° (x; y) → (−y; x); поворот на 180° = центральная симметрия.', 'Rotation: OA′ = OA and ∠AOA′ = α; by 90°, (x; y) → (−y; x); a 180° turn is point symmetry.'),
      L('Uchalasi ham harakat: uzunlik, burchak va yuz saqlanadi.', 'Все три — движения: длины, углы и площади сохраняются.', 'All three are isometries: lengths, angles and areas are kept.'),
      L('O‘q simmetriyasi yo‘nalishni teskarisiga o‘zgartiradi, burish esa saqlaydi.', 'Осевая симметрия меняет ориентацию, поворот её сохраняет.', 'A reflection reverses orientation; a rotation keeps it.'),
      L('Aks ettirish usuli eng qisqa yo‘l masalalarini yechadi (Geron masalasi).', 'Метод отражения решает задачи о кратчайшем пути (задача Герона).', 'The reflection trick solves shortest-path problems (Heron’s problem).')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '9-2';
  function F(x) { return L(x, x, x); }

  // ---------- t7. Gomotetiya va o‘xshashlik ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Proyektor nurlari va kattalashtirish', 'Лучи проектора и увеличение', 'Projector beams and enlargement'), p: [
      L('Qorong‘i sinfda proyektorni yoqing va qo‘lingizni nur yo‘liga qo‘ying: devorda qo‘lingizning katta soyasi paydo bo‘ladi. Qo‘lni proyektorga yaqinlashtirsangiz, soya kattalashadi, devorga yaqinlashtirsangiz — kichrayadi. Barcha nurlar bitta nuqtadan — chiroqdan chiqadi, va soya qo‘lning aynan o‘xshash nusxasi bo‘ladi.', 'Включите проектор в тёмном классе и поставьте руку на пути луча: на стене появится большая тень руки. Приблизите руку к проектору — тень вырастет, к стене — уменьшится. Все лучи выходят из одной точки — лампы, и тень оказывается точной подобной копией руки.', 'Switch on a projector in a dark classroom and put your hand in the beam: a large shadow of your hand appears on the wall. Move your hand towards the projector and the shadow grows; move it towards the wall and it shrinks. All rays come from one point, the lamp, and the shadow is an exactly similar copy of your hand.'),
      L('Bu jarayonning geometrik modeli — <b>gomotetiya</b>. U harakatlardan farqli ravishda masofalarni saqlamaydi, balki ularni bir xil k marta o‘zgartiradi. Shuning uchun gomotetiya shaklni teng emas, <b>o‘xshash</b> shaklga o‘tkazadi. Aynan shu almashtirish o‘xshashlik tushunchasini harakatlar tiliga bog‘laydi.', 'Геометрическая модель этого процесса — <b>гомотетия</b>. В отличие от движений, она не сохраняет расстояния, а изменяет их в одно и то же число k раз. Поэтому гомотетия переводит фигуру не в равную, а в <b>подобную</b>. Именно это преобразование связывает понятие подобия с языком преобразований.', 'The geometric model of this is a <b>dilation</b> (homothety). Unlike isometries it does not keep distances but multiplies them all by the same number k. So a dilation maps a figure not to a congruent one but to a <b>similar</b> one. This transformation links the idea of similarity to the language of transformations.'),
      L('Bu mavzuda gomotetiyaning ta’rifi va xossalarini, uning koordinatalardagi formulasini, manfiy koeffitsiyent ma’nosini o‘rganamiz va o‘xshashlikni «gomotetiya + harakat» sifatida qayta ta’riflaymiz. Shuningdek, gomotetiya yordamida yasashga oid chiroyli masalalarni yechamiz.', 'В этой теме мы изучим определение и свойства гомотетии, её формулу в координатах, смысл отрицательного коэффициента и заново определим подобие как «гомотетия + движение». А ещё решим красивые задачи на построение с помощью гомотетии.', 'In this topic we study the definition and properties of a dilation, its coordinate formula and the meaning of a negative factor, and we redefine similarity as “dilation + isometry”. We also solve some elegant construction problems with dilations.')
    ] },
    { kind: 'def', h: L('Gomotetiya ta’rifi', 'Определение гомотетии', 'Definition of a dilation'), p: [
      L('O nuqta va k ≠ 0 son berilgan bo‘lsin. Har bir X nuqtani <b>OX′ = k · OX</b> (vektorlar) shartini qanoatlantiruvchi X′ nuqtaga o‘tkazuvchi almashtirish <b>markazi O, koeffitsiyenti k bo‘lgan gomotetiya</b> deyiladi. Agar k &gt; 0 bo‘lsa, X′ OX nurida yotadi; k &lt; 0 bo‘lsa, X′ O nuqtaning narigi tomonida, qarama-qarshi nurda yotadi.', 'Пусть даны точка O и число k ≠ 0. Преобразование, переводящее каждую точку X в точку X′, для которой <b>OX′ = k · OX</b> (векторы), называется <b>гомотетией с центром O и коэффициентом k</b>. Если k &gt; 0, X′ лежит на луче OX; если k &lt; 0 — по другую сторону от O, на противоположном луче.', 'Let a point O and a number k ≠ 0 be given. The transformation sending each point X to the point X′ with <b>OX′ = k · OX</b> (as vectors) is the <b>dilation with centre O and factor k</b>. If k &gt; 0, X′ lies on ray OX; if k &lt; 0, it lies on the opposite ray, on the other side of O.')
    ], list: [
      L('|k| &gt; 1 — kattalashtirish, 0 &lt; |k| &lt; 1 — kichraytirish.', '|k| &gt; 1 — увеличение, 0 &lt; |k| &lt; 1 — уменьшение.', '|k| &gt; 1 enlarges; 0 &lt; |k| &lt; 1 shrinks.'),
      L('k = 1 — ayniy almashtirish (hech narsa o‘zgarmaydi); k = −1 — O markazli markaziy simmetriya.', 'k = 1 — тождественное преобразование (ничего не меняется); k = −1 — центральная симметрия с центром O.', 'k = 1 is the identity (nothing changes); k = −1 is point symmetry about O.'),
      L('Markaz O — yagona qo‘zg‘almas nuqta (k ≠ 1 bo‘lsa). O orqali o‘tuvchi har bir to‘g‘ri chiziq o‘ziga o‘tadi.', 'Центр O — единственная неподвижная точка (при k ≠ 1). Каждая прямая через O переходит в себя.', 'The centre O is the only fixed point (when k ≠ 1). Every line through O maps to itself.'),
      L('Shakl va uning gomotetik tasviri <b>gomotetik shakllar</b> deyiladi: mos nuqtalarni tutashtiruvchi to‘g‘ri chiziqlar bir nuqtada — markazda kesishadi.', 'Фигура и её образ называются <b>гомотетичными</b>: прямые, соединяющие соответственные точки, пересекаются в одной точке — центре.', 'A figure and its image are called <b>homothetic</b>: the lines joining corresponding points all pass through one point, the centre.'),
      L('<b>Koordinatalarda</b> (markaz koordinata boshida): (x; y) → (kx; ky). Markaz M(a; b) da: (x; y) → (a + k(x − a); b + k(y − b)).', '<b>В координатах</b> (центр в начале): (x; y) → (kx; ky). При центре M(a; b): (x; y) → (a + k(x − a); b + k(y − b)).', '<b>In coordinates</b> (centre at the origin): (x; y) → (kx; ky). With centre M(a; b): (x; y) → (a + k(x − a); b + k(y − b)).')
    ] },
    { kind: 'history', h: L('Tarixdan: kamera-obskura va pantograf', 'Из истории: камера-обскура и пантограф', 'History: the camera obscura and the pantograph'), p: [
      L('Gomotetiyaning tabiiy namunasi — <b>kamera-obskura</b> («qorong‘i xona»): devoridagi kichik teshikdan tushgan yorug‘lik qarama-qarshi devorda tashqi manzaraning teskari tasvirini beradi. Bu k &lt; 0 bo‘lgan gomotetiya, markazi — teshik. Hodisani <b>Ibn al-Haysam</b> (965–1040) «Optika kitobi»da batafsil tasvirlab, yorug‘lik to‘g‘ri chiziq bo‘ylab tarqalishini tajribada isbotlagan. Uning zamondoshi Beruniy ham Quyosh tutilishini teshik orqali kuzatish usulini yozgan.', 'Естественный пример гомотетии — <b>камера-обскура</b> («тёмная комната»): свет, проходящий через маленькое отверстие в стене, даёт на противоположной стене перевёрнутое изображение пейзажа. Это гомотетия с k &lt; 0 и центром в отверстии. Явление подробно описал <b>Ибн аль-Хайсам</b> (965–1040) в «Книге оптики» и опытом доказал прямолинейность распространения света. Его современник Беруни тоже описал наблюдение солнечного затмения через отверстие.', 'A natural example of a dilation is the <b>camera obscura</b> (“dark room”): light passing through a small hole in one wall forms an upside-down image of the outside scene on the opposite wall. It is a dilation with k &lt; 0 centred at the hole. <b>Ibn al-Haytham</b> (965–1040) described it in detail in his Book of Optics and showed by experiment that light travels in straight lines. His contemporary al-Biruni also described watching a solar eclipse through a small hole.'),
      L('1603-yilda nemis olimi <b>Kristof Shayner</b> chizmalarni kattalashtirish va kichraytirish uchun <b>pantograf</b> ixtiro qildi. U parallelogramm shaklida biriktirilgan to‘rtta reykadan iborat: bir uchi qo‘zg‘almas (markaz), bir nuqtasi bilan asl chizma bo‘ylab yuriladi, boshqa nuqtadagi qalam esa gomotetik tasvirni chizadi. Pantograflar xaritachilikda, gravyurada va kalit tayyorlashda ishlatilgan. «Gomotetiya» atamasini esa XIX asrda fransuz matematigi <b>Mishel Shal</b> kiritgan (yunoncha «homos» — bir xil, «thetos» — joylashgan).', 'В 1603 году немецкий учёный <b>Кристоф Шайнер</b> изобрёл <b>пантограф</b> для увеличения и уменьшения чертежей. Он состоит из четырёх реек, скреплённых параллелограммом: один конец неподвижен (центр), одной точкой обводят исходный рисунок, а карандаш в другой точке чертит гомотетичное изображение. Пантографы применяли в картографии, гравировке и изготовлении ключей. Термин «гомотетия» ввёл в XIX веке французский математик <b>Мишель Шаль</b> (греч. «homos» — одинаковый, «thetos» — расположенный).', 'In 1603 the German scholar <b>Christoph Scheiner</b> invented the <b>pantograph</b> for enlarging and reducing drawings. It is four rods joined as a parallelogram: one end is fixed (the centre), one point traces the original drawing, and a pencil at another point draws the homothetic image. Pantographs were used in map-making, engraving and key-cutting. The term “homothety” was introduced in the 19th century by the French mathematician <b>Michel Chasles</b> (Greek “homos”, same, and “thetos”, placed).')
    ] },
    { kind: 'rule', h: L('Gomotetiyaning xossalari', 'Свойства гомотетии', 'Properties of a dilation'), p: [
      L('<b>Teorema.</b> Gomotetiyada istalgan ikki nuqta orasidagi masofa |k| marta o‘zgaradi: A′B′ = |k| · AB. <b>Isbot:</b> A′B′ vektori = OB′ − OA′ = k · OB − k · OA = k(OB − OA) = k · AB vektori. Demak A′B′ ∥ AB (yoki ular bir to‘g‘ri chiziqda) va A′B′ = |k| · AB.', '<b>Теорема.</b> При гомотетии расстояние между любыми двумя точками меняется в |k| раз: A′B′ = |k| · AB. <b>Доказательство:</b> вектор A′B′ = OB′ − OA′ = k · OB − k · OA = k(OB − OA) = k · вектор AB. Значит, A′B′ ∥ AB (или они на одной прямой) и A′B′ = |k| · AB.', '<b>Theorem.</b> A dilation multiplies every distance by |k|: A′B′ = |k| · AB. <b>Proof:</b> the vector A′B′ = OB′ − OA′ = k · OB − k · OA = k(OB − OA) = k times the vector AB. So A′B′ ∥ AB (or they lie on one line) and A′B′ = |k| · AB.'),
      L('<b>Natijalar:</b> to‘g‘ri chiziq o‘ziga parallel to‘g‘ri chiziqqa o‘tadi; burchaklar saqlanadi; uchburchak o‘xshash uchburchakka o‘tadi (TTT bo‘yicha, koeffitsiyent |k|); aylana radiusi |k|R bo‘lgan aylanaga o‘tadi; yuzlar k<sup>2</sup> marta o‘zgaradi.', '<b>Следствия:</b> прямая переходит в параллельную ей прямую; углы сохраняются; треугольник переходит в подобный (по ССС, с коэффициентом |k|); окружность — в окружность радиуса |k|R; площади меняются в k<sup>2</sup> раз.', '<b>Consequences:</b> a line goes to a parallel line; angles are kept; a triangle goes to a similar triangle (by SSS, with factor |k|); a circle of radius R goes to a circle of radius |k|R; areas are multiplied by k<sup>2</sup>.'),
      L('<b>O‘xshashlikning yangi ta’rifi.</b> Endi biz aytamiz: F va F′ shakllar o‘xshash, agar F ni gomotetiya bilan F′ ga teng shaklga o‘tkazish mumkin bo‘lsa. Boshqacha aytganda, <b>o‘xshashlik almashtirishi = gomotetiya + harakat</b>. Avval kattalashtiramiz yoki kichraytiramiz, so‘ng kerakli joyga siljitamiz, buramiz yoki aks ettiramiz. Bu ta’rif ixtiyoriy shakllar — egri chiziqlar, aylanalar, xaritalar uchun ham ishlaydi.', '<b>Новое определение подобия.</b> Теперь скажем: фигуры F и F′ подобны, если F гомотетией можно перевести в фигуру, равную F′. Иначе говоря, <b>преобразование подобия = гомотетия + движение</b>. Сначала увеличиваем или уменьшаем, затем сдвигаем, поворачиваем или отражаем на нужное место. Это определение работает для любых фигур — кривых, окружностей, карт.', '<b>A new definition of similarity.</b> We now say: figures F and F′ are similar if a dilation can turn F into a figure congruent to F′. In other words, <b>a similarity transformation = dilation + isometry</b>. First enlarge or shrink, then slide, rotate or reflect into place. This definition works for any figures — curves, circles, maps.')
    ] },
    { kind: 'steps', h: L('Gomotetik shaklni yasash', 'Построение гомотетичной фигуры', 'Constructing a dilated figure'), list: [
      L('1. Markaz O ni va koeffitsiyent k ni belgilang.', '1. Отметьте центр O и коэффициент k.', '1. Mark the centre O and note the factor k.'),
      L('2. O ni shaklning har bir uchi bilan nur orqali tutashtiring.', '2. Соедините O лучом с каждой вершиной фигуры.', '2. Draw a ray from O through each vertex of the figure.'),
      L('3. k &gt; 0 bo‘lsa, nurda OA′ = k · OA kesmani qo‘ying; k &lt; 0 bo‘lsa, kesmani qarama-qarshi nurda qo‘ying.', '3. Если k &gt; 0, отложите на луче OA′ = k · OA; если k &lt; 0 — на противоположном луче.', '3. If k &gt; 0, mark OA′ = k · OA on the ray; if k &lt; 0, mark it on the opposite ray.'),
      L('4. Yangi uchlarni tutashtiring. Koordinatalarda esa har bir koordinatani k ga ko‘paytiring (markaz koordinata boshida bo‘lsa).', '4. Соедините новые вершины. В координатах умножьте каждую координату на k (если центр в начале).', '4. Join the new vertices. In coordinates, multiply each coordinate by k (if the centre is the origin).'),
      L('5. Tekshiring: mos tomonlar parallel va nisbati |k|.', '5. Проверьте: соответственные стороны параллельны и их отношение |k|.', '5. Check that corresponding sides are parallel and in ratio |k|.')
    ], after: [
      L('Teskari masala: ikki gomotetik shakl berilsa, markazni topish uchun ikki juft mos uchlarni to‘g‘ri chiziqlar bilan tutashtiring — ular markazda kesishadi.', 'Обратная задача: если даны две гомотетичные фигуры, чтобы найти центр, соедините прямыми две пары соответственных вершин — они пересекутся в центре.', 'The reverse task: given two homothetic figures, join two pairs of corresponding vertices with lines — they meet at the centre.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Markazi koordinata boshida, k = −2 bo‘lgan gomotetiyada A(3; −1) nuqta qayerga o‘tadi? OA va OA′ ni solishtiring.', 'Куда переходит A(3; −1) при гомотетии с центром в начале и k = −2? Сравните OA и OA′.', 'Where does A(3; −1) go under the dilation centred at the origin with k = −2? Compare OA and OA′.'),
        s: L('A′ = (−2 · 3; −2 · (−1)) = (−6; 2). OA = √(9 + 1) = √10, OA′ = √(36 + 4) = √40 = 2√10. Masofa 2 marta oshdi, A′ esa O ning narigi tomonida.', 'A′ = (−2 · 3; −2 · (−1)) = (−6; 2). OA = √(9 + 1) = √10, OA′ = √(36 + 4) = √40 = 2√10. Расстояние выросло в 2 раза, а A′ — по другую сторону от O.', 'A′ = (−2 · 3; −2 · (−1)) = (−6; 2). OA = √(9 + 1) = √10 and OA′ = √(36 + 4) = √40 = 2√10. The distance doubled, and A′ is on the other side of O.') },
      { q: L('Markazi M(1; 2), k = 3 bo‘lgan gomotetiyada B(3; 1) qayerga o‘tadi?', 'Куда переходит B(3; 1) при гомотетии с центром M(1; 2) и k = 3?', 'Where does B(3; 1) go under the dilation with centre M(1; 2) and k = 3?'),
        s: L('MB vektori = (2; −1). MB′ = 3 · (2; −1) = (6; −3). B′ = M + (6; −3) = (7; −1).', 'Вектор MB = (2; −1). MB′ = 3 · (2; −1) = (6; −3). B′ = M + (6; −3) = (7; −1).', 'The vector MB = (2; −1). MB′ = 3 · (2; −1) = (6; −3). So B′ = M + (6; −3) = (7; −1).') },
      { q: L('Yuzi 10 cm<sup>2</sup> bo‘lgan uchburchak k = −1,5 gomotetiyada qanday yuzli uchburchakka o‘tadi?', 'В треугольник какой площади переходит треугольник площадью 10 см<sup>2</sup> при гомотетии с k = −1,5?', 'A triangle of area 10 cm<sup>2</sup> undergoes a dilation with k = −1.5. What is the new area?'),
        s: L('Yuz k<sup>2</sup> marta o‘zgaradi: (−1,5)<sup>2</sup> = 2,25. S′ = 10 · 2,25 = 22,5 cm<sup>2</sup>. Manfiy ishora faqat tasvirni «ag‘daradi», o‘lchamga ta’sir qilmaydi.', 'Площадь меняется в k<sup>2</sup> раз: (−1,5)<sup>2</sup> = 2,25. S′ = 10 · 2,25 = 22,5 см<sup>2</sup>. Знак минус лишь «переворачивает» изображение и не влияет на размер.', 'Area is multiplied by k<sup>2</sup>: (−1.5)<sup>2</sup> = 2.25. S′ = 10 · 2.25 = 22.5 cm<sup>2</sup>. The minus sign only “flips” the image; it does not affect size.') },
      { q: L('Yasash: berilgan △ABC ga shunday kvadrat ichki chizingki, ikki uchi AC asosda, qolganlari AB va BC da yotsin.', 'Построение: впишите в данный △ABC квадрат так, чтобы две вершины лежали на основании AC, а остальные — на AB и BC.', 'Construction: inscribe a square in a given △ABC with two vertices on base AC and the others on AB and BC.'),
        s: L('Avval «yordamchi» kvadrat chizamiz: ikki uchi AC da, bir uchi AB da, to‘rtinchisi esa qayerga tushsa — BC da bo‘lishi shart emas. Endi A markazli gomotetiya qo‘llaymiz: A ni yordamchi kvadratning to‘rtinchi uchi bilan tutashtirib, nurni BC bilan kesishguncha davom ettiramiz. Kesishish nuqtasi izlangan kvadratning uchi bo‘ladi, qolgan uchlar parallel chiziqlar bilan topiladi. Gomotetiya kvadratni kvadratga o‘tkazgani uchun yechim to‘g‘ri.', 'Сначала строим «вспомогательный» квадрат: две вершины на AC, одна на AB, а четвёртая — где получится, не обязательно на BC. Теперь применим гомотетию с центром A: соединим A с четвёртой вершиной вспомогательного квадрата и продолжим луч до пересечения с BC. Точка пересечения — вершина искомого квадрата, остальные находим параллельными прямыми. Гомотетия переводит квадрат в квадрат, поэтому решение верно.', 'First draw a “helper” square with two vertices on AC and one on AB; the fourth lands wherever it lands, not necessarily on BC. Now use a dilation centred at A: join A to the helper square’s fourth vertex and extend the ray until it meets BC. That point is a vertex of the required square, and the others follow with parallel lines. A dilation maps squares to squares, so the construction works.') }
    ] },
    { kind: 'table', h: L('Almashtirishlarni solishtirish', 'Сравнение преобразований', 'Comparing transformations'), table: {
      head: [L('Almashtirish', 'Преобразование', 'Transformation'), L('Formula (O markaz)', 'Формула (центр O)', 'Formula (centre O)'), L('Uzunlik', 'Длины', 'Lengths'), L('Yuz', 'Площадь', 'Area')],
      rows: [
        [L('parallel ko‘chirish', 'параллельный перенос', 'translation'), F('(x + a; y + b)'), L('saqlanadi', 'сохраняются', 'kept'), L('saqlanadi', 'сохраняется', 'kept')],
        [L('markaziy simmetriya', 'центральная симметрия', 'point symmetry'), F('(−x; −y)'), L('saqlanadi', 'сохраняются', 'kept'), L('saqlanadi', 'сохраняется', 'kept')],
        [L('90° ga burish', 'поворот на 90°', '90° rotation'), F('(−y; x)'), L('saqlanadi', 'сохраняются', 'kept'), L('saqlanadi', 'сохраняется', 'kept')],
        [L('gomotetiya', 'гомотетия', 'dilation'), F('(kx; ky)'), L('|k| marta', 'в |k| раз', '× |k|'), L('k² marta', 'в k² раз', '× k²')]
      ] }, after: [
      L('Gomotetiya va harakatlar birga o‘xshashlik almashtirishlarini tashkil qiladi. Kleyn tilida: o‘xshashlik geometriyasi — bu almashtirishlarda saqlanadigan xossalar, ya’ni burchaklar va uzunliklar nisbatlari.', 'Гомотетии и движения вместе образуют преобразования подобия. На языке Клейна: геометрия подобия — это свойства, сохраняющиеся при этих преобразованиях, то есть углы и отношения длин.', 'Dilations and isometries together form the similarity transformations. In Klein’s language, similarity geometry studies what they keep: angles and ratios of lengths.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Manfiy k ni «kichraytirish» deb o‘ylash.</b> k = −3 — bu 3 marta kattalashtirish va markazdan narigi tomonga ag‘darish. O‘lchamni |k| belgilaydi.', '<b>Считать отрицательное k «уменьшением».</b> k = −3 — это увеличение в 3 раза с переворотом через центр. Размер определяет |k|.', '<b>Thinking a negative k means shrinking.</b> k = −3 enlarges three times and flips through the centre. Size is decided by |k|.'),
      L('<b>Markaz koordinata boshida emasligini unutish.</b> M(a; b) markazda (kx; ky) formulasi ishlamaydi — avval M dan nuqtagacha vektorni toping, uni k ga ko‘paytiring, so‘ng M ga qo‘shing.', '<b>Забывать, что центр не в начале координат.</b> При центре M(a; b) формула (kx; ky) не работает — сначала найдите вектор от M до точки, умножьте его на k и прибавьте к M.', '<b>Forgetting the centre is not the origin.</b> With centre M(a; b), (kx; ky) does not work — find the vector from M to the point, multiply it by k, then add it to M.'),
      L('<b>Yuzni k marta o‘zgartirish.</b> Yuz k<sup>2</sup> marta, perimetr |k| marta o‘zgaradi.', '<b>Менять площадь в k раз.</b> Площадь меняется в k<sup>2</sup> раз, периметр — в |k| раз.', '<b>Scaling area by k.</b> Area scales by k<sup>2</sup>, perimeter by |k|.'),
      L('<b>Har qanday o‘xshash shakllarni gomotetik deb hisoblash.</b> O‘xshash shakllar gomotetik bo‘lishi uchun ular «bir xil yo‘nalishda» joylashishi (mos tomonlar parallel) kerak; aks holda gomotetiyadan keyin harakat ham kerak bo‘ladi.', '<b>Считать любые подобные фигуры гомотетичными.</b> Подобные фигуры гомотетичны, только если они «одинаково ориентированы» (соответственные стороны параллельны); иначе после гомотетии нужно ещё движение.', '<b>Treating all similar figures as homothetic.</b> Similar figures are homothetic only when they are “lined up” (corresponding sides parallel); otherwise an isometry is needed after the dilation.')
    ] },
    { kind: 'life', h: L('Hayotda gomotetiya', 'Гомотетия в жизни', 'Dilations in real life'), p: [
      L('<b>Fotografiya va optika.</b> Fotoapparat linzasi markaz vazifasini bajaradi: manzaraning har bir nuqtasidan chiqqan nur linza orqali o‘tib, sensorda teskari tasvir beradi — bu manfiy koeffitsiyentli gomotetiya. Ko‘zimizning to‘r pardasida ham tasvir teskari tushadi, miyamiz uni «to‘g‘rilab» qo‘yadi.', '<b>Фотография и оптика.</b> Объектив фотоаппарата играет роль центра: луч от каждой точки пейзажа проходит через линзу и даёт на матрице перевёрнутое изображение — это гомотетия с отрицательным коэффициентом. На сетчатке нашего глаза изображение тоже перевёрнуто, а мозг его «исправляет».', '<b>Photography and optics.</b> A camera lens acts as the centre: a ray from each point of the scene passes through the lens and forms an inverted image on the sensor — a dilation with a negative factor. The image on the retina of our eye is inverted too, and our brain “turns it the right way up”.'),
      L('<b>Kompyuter va telefon.</b> Rasmni ikki barmoq bilan kattalashtirganda, telefon barmoqlar orasidagi nuqtani markaz qilib gomotetiya bajaradi. Vektor grafikadagi shriftlar va ikonkalar istalgan o‘lchamda tiniq qoladi, chunki ular koordinatalarni k ga ko‘paytirish orqali qayta chiziladi.', '<b>Компьютер и телефон.</b> Когда вы увеличиваете фото двумя пальцами, телефон выполняет гомотетию с центром в точке между пальцами. Шрифты и значки векторной графики остаются чёткими при любом размере, потому что перерисовываются умножением координат на k.', '<b>Computers and phones.</b> When you pinch-zoom a photo, the phone performs a dilation centred at the point between your fingers. Vector fonts and icons stay sharp at any size because they are redrawn by multiplying coordinates by k.'),
      L('<b>Teatr va kino.</b> Soya teatrida chiroq — markaz, qo‘g‘irchoq — asl shakl, ekrandagi soya — kattalashtirilgan tasvir. Qo‘g‘irchoqni chiroqqa yaqinlashtirib, rassom «dev»larni yaratadi. Kinoproyektor va planetariy ham shu tamoyilga asoslanadi.', '<b>Театр и кино.</b> В театре теней лампа — центр, кукла — исходная фигура, тень на экране — увеличенный образ. Приближая куклу к лампе, артист создаёт «великанов». На том же принципе работают кинопроектор и планетарий.', '<b>Theatre and film.</b> In a shadow theatre the lamp is the centre, the puppet is the original and the shadow on the screen is the enlarged image. Moving the puppet closer to the lamp, the artist creates “giants”. Film projectors and planetariums work on the same principle.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Har qanday ikki aylana gomotetik: radiuslari har xil bo‘lsa, ularning ikkita gomotetiya markazi bor — biri k &gt; 0, ikkinchisi k &lt; 0 uchun. Bu markazlar umumiy urinmalar kesishgan joyda yotadi.', 'Любые две окружности гомотетичны: если радиусы различны, у них два центра гомотетии — для k &gt; 0 и для k &lt; 0. Эти центры лежат там, где пересекаются общие касательные.', 'Any two circles are homothetic: if their radii differ, they have two centres of homothety, one for k &gt; 0 and one for k &lt; 0. These lie where the common tangents cross.'),
      L('Uchburchak medianalari kesishish nuqtasi markazli, k = −½ gomotetiya uchburchakni uning o‘rta chiziqlaridan tuzilgan uchburchakka o‘tkazadi.', 'Гомотетия с центром в точке пересечения медиан и k = −½ переводит треугольник в треугольник из его средних линий.', 'The dilation centred at the meeting point of the medians with k = −½ maps a triangle onto the triangle formed by its midlines.'),
      L('Quyosh tutilishini teshikli karton orqali kuzatish xavfsiz usuli — kichik kamera-obskura. Daraxt barglari orasidan tushgan quyosh dog‘lari tutilish paytida o‘roqsimon shaklga kiradi.', 'Безопасный способ наблюдать солнечное затмение — картон с дыркой, маленькая камера-обскура. Солнечные зайчики под листвой деревьев во время затмения становятся серповидными.', 'A safe way to watch a solar eclipse is a card with a pinhole — a tiny camera obscura. During an eclipse the spots of sunlight under trees turn crescent-shaped.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. O markaz, k = ½. A(8; −6) → ?', '1. Центр O, k = ½. A(8; −6) → ?', '1. Centre O, k = ½. A(8; −6) → ?'),
      L('2. A(2; 3) nuqta A′(−4; −6) ga o‘tdi (markaz O). k = ?', '2. Точка A(2; 3) перешла в A′(−4; −6) (центр O). k = ?', '2. A(2; 3) went to A′(−4; −6) (centre O). k = ?'),
      L('3. Radiusi 4 bo‘lgan aylana k = −3 gomotetiyada qanday radiusli aylanaga o‘tadi?', '3. В окружность какого радиуса переходит окружность радиуса 4 при k = −3?', '3. A circle of radius 4 undergoes a dilation with k = −3. The new radius?'),
      L('4. Kvadrat yuzi 5 dan 45 ga oshdi. |k| = ?', '4. Площадь квадрата выросла с 5 до 45. |k| = ?', '4. A square’s area grew from 5 to 45. |k| = ?')
    ], after: [
      L('Javoblar: 1) (4; −3); 2) k = −2; 3) 12; 4) √9 = 3.', 'Ответы: 1) (4; −3); 2) k = −2; 3) 12; 4) √9 = 3.', 'Answers: 1) (4; −3); 2) k = −2; 3) 12; 4) √9 = 3.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Gomotetiya: OX′ = k · OX; koordinatalarda (x; y) → (kx; ky).', 'Гомотетия: OX′ = k · OX; в координатах (x; y) → (kx; ky).', 'Dilation: OX′ = k · OX; in coordinates (x; y) → (kx; ky).'),
      L('Masofalar |k| marta, yuzlar k<sup>2</sup> marta o‘zgaradi; burchaklar saqlanadi.', 'Расстояния меняются в |k| раз, площади — в k<sup>2</sup> раз; углы сохраняются.', 'Distances scale by |k|, areas by k<sup>2</sup>; angles are kept.'),
      L('To‘g‘ri chiziq parallel to‘g‘ri chiziqqa, aylana aylanaga o‘tadi.', 'Прямая переходит в параллельную, окружность — в окружность.', 'Lines go to parallel lines, circles to circles.'),
      L('k &lt; 0 — tasvir markazdan narigi tomonda; k = −1 — markaziy simmetriya.', 'k &lt; 0 — образ по другую сторону от центра; k = −1 — центральная симметрия.', 'k &lt; 0 puts the image on the far side of the centre; k = −1 is point symmetry.'),
      L('O‘xshashlik = gomotetiya + harakat.', 'Подобие = гомотетия + движение.', 'Similarity = dilation + isometry.'),
      L('Kamera-obskura, pantograf, proyektor va fotoapparat — gomotetiya qurilmalari.', 'Камера-обскура, пантограф, проектор и фотоаппарат — устройства гомотетии.', 'The camera obscura, pantograph, projector and camera are all dilation machines.')
    ] }
  ] });

  // ---------- t8. 0° dan 180° gacha burchakning sinusi, kosinusi va tangensi ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('O‘tmas burchakning sinusi bormi?', 'Есть ли синус у тупого угла?', 'Does an obtuse angle have a sine?'), p: [
      L('8-sinfda biz sinus, kosinus va tangensni to‘g‘ri burchakli uchburchak orqali ta’rifladik: sin α — qarshi katetning gipotenuzaga nisbati, cos α — yopishgan katetning gipotenuzaga nisbati. Lekin to‘g‘ri burchakli uchburchakda o‘tkir burchaklar faqat 0° dan 90° gacha. 120° li burchakda «qarshi katet» ham, «yopishgan katet» ham yo‘q! Ammo o‘tmas burchakli uchburchaklar ham bor va ularni ham hisoblash kerak.', 'В 8 классе мы определили синус, косинус и тангенс через прямоугольный треугольник: sin α — отношение противолежащего катета к гипотенузе, cos α — прилежащего катета к гипотенузе. Но острые углы прямоугольного треугольника бывают только от 0° до 90°. У угла 120° нет ни «противолежащего», ни «прилежащего» катета! А тупоугольные треугольники существуют, и их тоже нужно вычислять.', 'In grade 8 we defined sine, cosine and tangent through a right triangle: sin α is the opposite leg over the hypotenuse and cos α the adjacent leg over the hypotenuse. But the acute angles of a right triangle only go from 0° to 90°. An angle of 120° has no “opposite” or “adjacent” leg! Yet obtuse triangles exist, and we need to compute with them too.'),
      L('Matematiklar bu muammoni chiroyli hal qildi: ular burchakni <b>birlik yarim aylana</b> ustidagi nuqta yordamida o‘lchashni taklif qilishdi. Nuqtaning koordinatalari burchakning kosinusi va sinusi bo‘ladi. O‘tkir burchaklar uchun bu eski ta’rif bilan bir xil natija beradi, o‘tmas burchaklar uchun esa yangi, mantiqiy qiymatlar hosil qiladi.', 'Математики красиво решили эту проблему: они предложили измерять угол с помощью точки на <b>единичной полуокружности</b>. Координаты точки и будут косинусом и синусом угла. Для острых углов это даёт то же, что старое определение, а для тупых — новые, логичные значения.', 'Mathematicians solved this neatly: they measure an angle using a point on the <b>unit semicircle</b>. The coordinates of the point become the cosine and sine of the angle. For acute angles this agrees with the old definition, and for obtuse angles it gives new, sensible values.'),
      L('Bu kengaytma sinuslar va kosinuslar teoremalari, uchburchak yuzi formulasi va vektorlarning skalyar ko‘paytmasi uchun zarur. Bu mavzuda biz yangi ta’rifni, asosiy ayniyatni, keltirish formulalarini va asosiy burchaklar qiymatlari jadvalini o‘rganamiz.', 'Это расширение необходимо для теорем синусов и косинусов, формулы площади треугольника и скалярного произведения векторов. В этой теме мы изучим новое определение, основное тождество, формулы приведения и таблицу значений основных углов.', 'This extension is essential for the sine and cosine rules, the triangle area formula and the dot product of vectors. In this topic we learn the new definition, the main identity, the reduction formulas and the table of key values.')
    ] },
    { kind: 'def', h: L('Birlik yarim aylana orqali ta’rif', 'Определение через единичную полуокружность', 'Definition via the unit semicircle'), p: [
      L('Koordinata tekisligida markazi O(0; 0), radiusi 1 bo‘lgan yuqori yarim aylanani chizamiz. Ox o‘qining musbat yo‘nalishidan soat miliga teskari yo‘nalishda α burchak (0° ≤ α ≤ 180°) qo‘yamiz. Burchak tomoni yarim aylanani M(x; y) nuqtada kesadi. U holda:', 'На координатной плоскости построим верхнюю полуокружность с центром O(0; 0) и радиусом 1. От положительного направления оси Ox против часовой стрелки отложим угол α (0° ≤ α ≤ 180°). Сторона угла пересекает полуокружность в точке M(x; y). Тогда:', 'On the coordinate plane draw the upper semicircle with centre O(0; 0) and radius 1. From the positive x-axis, turning anticlockwise, mark an angle α (0° ≤ α ≤ 180°). The arm of the angle meets the semicircle at M(x; y). Then:')
    ], list: [
      L('<b>cos α = x</b> — M nuqtaning abssissasi;', '<b>cos α = x</b> — абсцисса точки M;', '<b>cos α = x</b>, the x-coordinate of M;'),
      L('<b>sin α = y</b> — M nuqtaning ordinatasi;', '<b>sin α = y</b> — ордината точки M;', '<b>sin α = y</b>, the y-coordinate of M;'),
      L('<b>tg α = sin α / cos α = y / x</b> (α ≠ 90°); <b>ctg α = cos α / sin α</b> (α ≠ 0°, 180°).', '<b>tg α = sin α / cos α = y / x</b> (α ≠ 90°); <b>ctg α = cos α / sin α</b> (α ≠ 0°, 180°).', '<b>tan α = sin α / cos α = y / x</b> (α ≠ 90°); <b>cot α = cos α / sin α</b> (α ≠ 0°, 180°).'),
      L('0° &lt; α &lt; 90° da bu ta’rif eski ta’rifga mos: M dan Ox ga perpendikulyar tushirsak, gipotenuzasi 1 bo‘lgan to‘g‘ri burchakli uchburchak hosil bo‘ladi, katetlari esa x va y.', 'При 0° &lt; α &lt; 90° это определение совпадает со старым: опустив перпендикуляр из M на Ox, получаем прямоугольный треугольник с гипотенузой 1 и катетами x и y.', 'For 0° &lt; α &lt; 90° this matches the old definition: dropping a perpendicular from M to Ox gives a right triangle with hypotenuse 1 and legs x and y.'),
      L('Qiymatlar oralig‘i: 0 ≤ sin α ≤ 1, −1 ≤ cos α ≤ 1. O‘tmas burchakda cos α &lt; 0 va tg α &lt; 0, chunki M nuqta ikkinchi chorakda.', 'Пределы значений: 0 ≤ sin α ≤ 1, −1 ≤ cos α ≤ 1. Для тупого угла cos α &lt; 0 и tg α &lt; 0, так как M во второй четверти.', 'Ranges: 0 ≤ sin α ≤ 1 and −1 ≤ cos α ≤ 1. For an obtuse angle cos α &lt; 0 and tan α &lt; 0, because M is in the second quadrant.')
    ] },
    { kind: 'history', h: L('Tarixdan: Ptolemey vatarlari va Abul-Vafo', 'Из истории: хорды Птолемея и Абу-ль-Вафа', 'History: Ptolemy’s chords and Abu’l-Wafa'), p: [
      L('Trigonometriya astronomiya ehtiyojlaridan tug‘ildi. II asrda Iskandariyada yashagan <b>Klavdiy Ptolemey</b> «Almagest» asarida 0° dan 180° gacha har yarim gradus uchun aylana <b>vatarlari jadvalini</b> tuzdi. Radiusi 60 birlik bo‘lgan aylanada α markaziy burchakka tiralgan vatar uzunligi, bugungi tilda, 120 · sin(α/2) ga teng. Ptolemey shunday qilib o‘tmas burchaklar bilan ham bemalol ishlagan.', 'Тригонометрия родилась из нужд астрономии. Во II веке <b>Клавдий Птолемей</b> из Александрии составил в «Альмагесте» <b>таблицу хорд</b> окружности для углов от 0° до 180° через каждые полградуса. В окружности радиуса 60 единиц хорда, стягивающая центральный угол α, по-современному равна 120 · sin(α/2). Так Птолемей свободно работал и с тупыми углами.', 'Trigonometry was born from the needs of astronomy. In the 2nd century <b>Claudius Ptolemy</b> of Alexandria compiled, in the Almagest, a <b>table of chords</b> of a circle for angles from 0° to 180° in half-degree steps. In a circle of radius 60, the chord of a central angle α is, in modern terms, 120 · sin(α/2). In this way Ptolemy worked freely with obtuse angles too.'),
      L('Hind olimlari vatar o‘rniga yarim vatar — «jya»dan foydalanishni boshladi; bu bizning sinusimiz. Arab tiliga «jayb» shaklida o‘tgan so‘z lotin tiliga «sinus» (qo‘ltiq, egilish) deb tarjima qilindi. X asrda Bag‘dodda ishlagan xurosonlik olim <b>Abul-Vafo al-Buzjoniy</b> (940–998) trigonometriyani tubdan yangiladi: u radiusi 1 bo‘lgan aylanadan foydalanishni taklif qildi, tangens va sekansni alohida funksiya sifatida kiritdi, sinuslar teoremasini sferik uchburchaklar uchun isbotladi va sinuslar jadvalini 15′ qadam bilan, 8 xona aniqlikda tuzdi. <b>Beruniy</b> «Qonuni Mas’udiy» asarida bu natijalarni rivojlantirdi.', 'Индийские учёные стали использовать вместо хорды полухорду — «джья»; это наш синус. Слово, перешедшее в арабский как «джайб», было переведено на латынь как «sinus» (пазуха, изгиб). В X веке хорасанский учёный <b>Абу-ль-Вафа аль-Бузджани</b> (940–998), работавший в Багдаде, обновил тригонометрию: он предложил использовать окружность радиуса 1, ввёл тангенс и секанс как отдельные функции, доказал теорему синусов для сферических треугольников и составил таблицу синусов с шагом 15′ с точностью до 8 знаков. <b>Беруни</b> развил эти результаты в «Кануне Масуда».', 'Indian scholars replaced the chord with the half-chord, “jya” — our sine. The word passed into Arabic as “jayb” and was translated into Latin as “sinus” (a bay or fold). In the 10th century <b>Abu’l-Wafa al-Buzjani</b> (940–998), a scholar from Khorasan working in Baghdad, renewed trigonometry: he proposed using a circle of radius 1, introduced the tangent and secant as separate functions, proved the sine rule for spherical triangles and computed a sine table in steps of 15′ to about 8 decimal places. <b>Al-Biruni</b> developed these results in his Mas’udic Canon.')
    ] },
    { kind: 'rule', h: L('Asosiy ayniyat va keltirish formulalari', 'Основное тождество и формулы приведения', 'The main identity and reduction formulas'), p: [
      L('<b>Asosiy trigonometrik ayniyat:</b> <b>sin<sup>2</sup>α + cos<sup>2</sup>α = 1</b>. <b>Isbot:</b> M(x; y) nuqta markazi O, radiusi 1 bo‘lgan aylanada yotadi, demak OM<sup>2</sup> = x<sup>2</sup> + y<sup>2</sup> = 1 — bu masofa formulasi, ya’ni Pifagor teoremasi. Ayniyatdan: 1 + tg<sup>2</sup>α = 1 / cos<sup>2</sup>α.', '<b>Основное тригонометрическое тождество:</b> <b>sin<sup>2</sup>α + cos<sup>2</sup>α = 1</b>. <b>Доказательство:</b> точка M(x; y) лежит на окружности с центром O и радиусом 1, значит, OM<sup>2</sup> = x<sup>2</sup> + y<sup>2</sup> = 1 — это формула расстояния, то есть теорема Пифагора. Из тождества: 1 + tg<sup>2</sup>α = 1 / cos<sup>2</sup>α.', '<b>The main identity:</b> <b>sin<sup>2</sup>α + cos<sup>2</sup>α = 1</b>. <b>Proof:</b> M(x; y) lies on the circle with centre O and radius 1, so OM<sup>2</sup> = x<sup>2</sup> + y<sup>2</sup> = 1 — the distance formula, that is, Pythagoras. From it: 1 + tan<sup>2</sup>α = 1 / cos<sup>2</sup>α.'),
      L('<b>Keltirish formulalari:</b> <b>sin(180° − α) = sin α</b>, <b>cos(180° − α) = −cos α</b>, <b>tg(180° − α) = −tg α</b>. <b>Isbot g‘oyasi:</b> α va 180° − α burchaklarga mos M(x; y) va N nuqtalar Oy o‘qqa nisbatan simmetrik (bu t6 dagi o‘q simmetriyasi!). Shuning uchun N(−x; y): ordinata (sinus) bir xil, abssissa (kosinus) qarama-qarshi.', '<b>Формулы приведения:</b> <b>sin(180° − α) = sin α</b>, <b>cos(180° − α) = −cos α</b>, <b>tg(180° − α) = −tg α</b>. <b>Идея доказательства:</b> точки M(x; y) и N, соответствующие углам α и 180° − α, симметричны относительно оси Oy (это осевая симметрия из t6!). Поэтому N(−x; y): ордината (синус) та же, абсцисса (косинус) противоположна.', '<b>Reduction formulas:</b> <b>sin(180° − α) = sin α</b>, <b>cos(180° − α) = −cos α</b>, <b>tan(180° − α) = −tan α</b>. <b>Proof idea:</b> the points M(x; y) and N for the angles α and 180° − α are mirror images in the y-axis (the reflection from t6!). So N is (−x; y): the y-coordinate (sine) is the same and the x-coordinate (cosine) changes sign.'),
      L('Shuningdek: sin(90° − α) = cos α, cos(90° − α) = sin α — bu to‘g‘ri burchakli uchburchakning ikki o‘tkir burchagi uchun ma’lum fakt. Kosinusning ishorasi burchak turini aniqlaydi: cos α &gt; 0 — o‘tkir, cos α = 0 — to‘g‘ri, cos α &lt; 0 — o‘tmas burchak. Sinus esa 0° &lt; α &lt; 180° da doim musbat, shuning uchun sinus bo‘yicha burchak ikki xil bo‘lishi mumkin: sin α = ½ bo‘lsa, α = 30° yoki 150°.', 'А также: sin(90° − α) = cos α, cos(90° − α) = sin α — известный факт о двух острых углах прямоугольного треугольника. Знак косинуса определяет вид угла: cos α &gt; 0 — острый, cos α = 0 — прямой, cos α &lt; 0 — тупой. Синус же при 0° &lt; α &lt; 180° всегда положителен, поэтому по синусу угол может быть двояким: если sin α = ½, то α = 30° или 150°.', 'Also: sin(90° − α) = cos α and cos(90° − α) = sin α — the familiar fact about the two acute angles of a right triangle. The sign of the cosine tells the type of angle: cos α &gt; 0 acute, cos α = 0 right, cos α &lt; 0 obtuse. The sine, however, is always positive for 0° &lt; α &lt; 180°, so a sine value can give two angles: if sin α = ½, then α = 30° or 150°.')
    ] },
    { kind: 'table', h: L('Asosiy burchaklar qiymatlari', 'Значения для основных углов', 'Values for key angles'), table: {
      head: [F('α'), F('sin α'), F('cos α'), L('tg α', 'tg α', 'tan α')],
      rows: [
        [F('0°'), F('0'), F('1'), F('0')],
        [F('30°'), F('1/2'), F('√3/2'), F('√3/3')],
        [F('45°'), F('√2/2'), F('√2/2'), F('1')],
        [F('60°'), F('√3/2'), F('1/2'), F('√3')],
        [F('90°'), F('1'), F('0'), L('mavjud emas', 'не существует', 'undefined')],
        [F('120°'), F('√3/2'), F('−1/2'), F('−√3')],
        [F('135°'), F('√2/2'), F('−√2/2'), F('−1')],
        [F('150°'), F('1/2'), F('−√3/2'), F('−√3/3')],
        [F('180°'), F('0'), F('−1'), F('0')]
      ] }, after: [
      L('Jadvalning pastki yarmi yuqori yarmidan keltirish formulalari bilan olinadi: masalan, sin 150° = sin 30°, cos 150° = −cos 30°. Yodlash uchun: sinus 0°, 30°, 45°, 60°, 90° da √0/2, √1/2, √2/2, √3/2, √4/2 ko‘rinishida yoziladi.', 'Нижняя половина таблицы получается из верхней по формулам приведения: например, sin 150° = sin 30°, cos 150° = −cos 30°. Для запоминания: синус при 0°, 30°, 45°, 60°, 90° записывается как √0/2, √1/2, √2/2, √3/2, √4/2.', 'The bottom half of the table follows from the top half by the reduction formulas: for example sin 150° = sin 30° and cos 150° = −cos 30°. A memory aid: the sines of 0°, 30°, 45°, 60°, 90° are √0/2, √1/2, √2/2, √3/2, √4/2.')
    ] },
    { kind: 'steps', h: L('O‘tmas burchak qiymatini topish', 'Как найти значение для тупого угла', 'Finding a value for an obtuse angle'), list: [
      L('1. Burchak 90° dan katta ekanini tekshiring va unga qo‘shni burchakni toping: β = 180° − α.', '1. Убедитесь, что угол больше 90°, и найдите смежный угол: β = 180° − α.', '1. Check that the angle is more than 90° and find its supplement: β = 180° − α.'),
      L('2. β uchun qiymatni jadvaldan yoki kalkulyatordan oling.', '2. Возьмите значение для β из таблицы или с калькулятора.', '2. Take the value for β from the table or a calculator.'),
      L('3. Sinus uchun ishora o‘zgarmaydi: sin α = sin β.', '3. Для синуса знак не меняется: sin α = sin β.', '3. For the sine, the sign stays: sin α = sin β.'),
      L('4. Kosinus va tangens uchun minus qo‘ying: cos α = −cos β, tg α = −tg β.', '4. Для косинуса и тангенса поставьте минус: cos α = −cos β, tg α = −tg β.', '4. For the cosine and tangent, add a minus: cos α = −cos β, tan α = −tan β.'),
      L('5. Tekshirish: sin<sup>2</sup>α + cos<sup>2</sup>α = 1 bajarilishi kerak.', '5. Проверка: должно выполняться sin<sup>2</sup>α + cos<sup>2</sup>α = 1.', '5. Check that sin<sup>2</sup>α + cos<sup>2</sup>α = 1.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('sin 135°, cos 135° va tg 135° ni toping.', 'Найдите sin 135°, cos 135° и tg 135°.', 'Find sin 135°, cos 135° and tan 135°.'),
        s: L('180° − 135° = 45°. sin 135° = sin 45° = √2/2; cos 135° = −cos 45° = −√2/2; tg 135° = −tg 45° = −1. Tekshirish: ½ + ½ = 1.', '180° − 135° = 45°. sin 135° = sin 45° = √2/2; cos 135° = −cos 45° = −√2/2; tg 135° = −tg 45° = −1. Проверка: ½ + ½ = 1.', '180° − 135° = 45°. sin 135° = sin 45° = √2/2; cos 135° = −cos 45° = −√2/2; tan 135° = −tan 45° = −1. Check: ½ + ½ = 1.') },
      { q: L('cos α = −0,6 va 0° ≤ α ≤ 180°. sin α va tg α ni toping. Burchak qanday?', 'cos α = −0,6 и 0° ≤ α ≤ 180°. Найдите sin α и tg α. Каков угол?', 'cos α = −0.6 and 0° ≤ α ≤ 180°. Find sin α and tan α. What kind of angle is it?'),
        s: L('sin<sup>2</sup>α = 1 − 0,36 = 0,64. 0° ≤ α ≤ 180° da sin α ≥ 0, demak sin α = 0,8. tg α = 0,8 / (−0,6) = −4/3. cos α &lt; 0, shuning uchun α o‘tmas burchak (≈ 126,9°).', 'sin<sup>2</sup>α = 1 − 0,36 = 0,64. При 0° ≤ α ≤ 180° sin α ≥ 0, значит, sin α = 0,8. tg α = 0,8 / (−0,6) = −4/3. cos α &lt; 0, поэтому α — тупой угол (≈ 126,9°).', 'sin<sup>2</sup>α = 1 − 0.36 = 0.64. For 0° ≤ α ≤ 180°, sin α ≥ 0, so sin α = 0.8. tan α = 0.8 / (−0.6) = −4/3. Since cos α &lt; 0, α is obtuse (about 126.9°).') },
      { q: L('M(−5/13; 12/13) nuqta birlik yarim aylanada yotadimi? Agar yotsa, mos burchakning sinusi, kosinusi va tangensi nimaga teng?', 'Лежит ли точка M(−5/13; 12/13) на единичной полуокружности? Если да, найдите синус, косинус и тангенс соответствующего угла.', 'Does M(−5/13; 12/13) lie on the unit semicircle? If so, find the sine, cosine and tangent of the matching angle.'),
        s: L('(−5/13)<sup>2</sup> + (12/13)<sup>2</sup> = 25/169 + 144/169 = 1, y &gt; 0 — yotadi. cos α = −5/13, sin α = 12/13, tg α = −12/5. Bu 5, 12, 13 Pifagor uchligiga asoslangan o‘tmas burchak.', '(−5/13)<sup>2</sup> + (12/13)<sup>2</sup> = 25/169 + 144/169 = 1, y &gt; 0 — лежит. cos α = −5/13, sin α = 12/13, tg α = −12/5. Это тупой угол, построенный на пифагоровой тройке 5, 12, 13.', '(−5/13)<sup>2</sup> + (12/13)<sup>2</sup> = 25/169 + 144/169 = 1 and y &gt; 0, so yes. cos α = −5/13, sin α = 12/13 and tan α = −12/5. It is an obtuse angle built on the 5, 12, 13 triple.') },
      { q: L('Ifodani soddalashtiring: sin 160° − sin 20° + cos 110° + cos 70°.', 'Упростите: sin 160° − sin 20° + cos 110° + cos 70°.', 'Simplify: sin 160° − sin 20° + cos 110° + cos 70°.'),
        s: L('sin 160° = sin 20°, cos 110° = −cos 70°. Demak sin 20° − sin 20° − cos 70° + cos 70° = 0.', 'sin 160° = sin 20°, cos 110° = −cos 70°. Значит, sin 20° − sin 20° − cos 70° + cos 70° = 0.', 'sin 160° = sin 20° and cos 110° = −cos 70°. So sin 20° − sin 20° − cos 70° + cos 70° = 0.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>O‘tmas burchak sinusini manfiy deb olish.</b> 0° dan 180° gacha sinus manfiy bo‘lmaydi: sin 150° = +½. Manfiy bo‘ladigani kosinus va tangens.', '<b>Считать синус тупого угла отрицательным.</b> От 0° до 180° синус не бывает отрицательным: sin 150° = +½. Отрицательны косинус и тангенс.', '<b>Taking the sine of an obtuse angle as negative.</b> Between 0° and 180° the sine is never negative: sin 150° = +½. It is the cosine and tangent that are negative.'),
      L('<b>sin α dan burchakni bir qiymatli topish.</b> sin α = √3/2 bo‘lsa, α = 60° yoki 120°. Uchburchak masalasida ikkala variantni tekshirish kerak.', '<b>Однозначно находить угол по синусу.</b> Если sin α = √3/2, то α = 60° или 120°. В задаче о треугольнике нужно проверить оба варианта.', '<b>Finding the angle from its sine as if unique.</b> If sin α = √3/2, then α = 60° or 120°. In a triangle problem check both options.'),
      L('<b>Ildizdan oldin ishorani unutish.</b> sin α = √(1 − cos<sup>2</sup>α) — bu yerda «+» olinadi, cos α = ±√(1 − sin<sup>2</sup>α) da esa ishora burchak turiga bog‘liq.', '<b>Забывать про знак перед корнем.</b> sin α = √(1 − cos<sup>2</sup>α) — здесь берётся «+», а в cos α = ±√(1 − sin<sup>2</sup>α) знак зависит от вида угла.', '<b>Forgetting the sign before the root.</b> sin α = √(1 − cos<sup>2</sup>α) takes “+”, but in cos α = ±√(1 − sin<sup>2</sup>α) the sign depends on the type of angle.'),
      L('<b>tg 90° ni hisoblashga urinish.</b> cos 90° = 0 va nolga bo‘lib bo‘lmaydi — tg 90° mavjud emas.', '<b>Пытаться вычислить tg 90°.</b> cos 90° = 0, а делить на ноль нельзя — tg 90° не существует.', '<b>Trying to compute tan 90°.</b> cos 90° = 0 and you cannot divide by zero — tan 90° is undefined.'),
      L('<b>Kalkulyator rejimi.</b> Kalkulyator «RAD» rejimida bo‘lsa, sin 30 = −0,988 chiqadi. Gradus uchun «DEG» rejimini yoqing.', '<b>Режим калькулятора.</b> Если калькулятор в режиме «RAD», sin 30 даст −0,988. Для градусов включите режим «DEG».', '<b>Calculator mode.</b> In “RAD” mode a calculator gives sin 30 = −0.988. Switch to “DEG” for degrees.')
    ] },
    { kind: 'life', h: L('Hayotda trigonometriya', 'Тригонометрия в жизни', 'Trigonometry in real life'), p: [
      L('<b>Astronomiya va navigatsiya.</b> Abul-Vafo va Beruniy jadvallari yulduzlar balandligi, Makka yo‘nalishi (qibla) va namoz vaqtlarini hisoblash uchun tuzilgan. Bugun GPS sun’iy yo‘ldoshlari koordinatalarni aynan sinus va kosinuslar orqali hisoblaydi.', '<b>Астрономия и навигация.</b> Таблицы Абу-ль-Вафы и Беруни составляли для вычисления высоты звёзд, направления на Мекку (киблы) и времени молитв. Сегодня спутники GPS вычисляют координаты именно через синусы и косинусы.', '<b>Astronomy and navigation.</b> The tables of Abu’l-Wafa and al-Biruni were made to compute star altitudes, the direction of Mecca (the qibla) and prayer times. Today GPS satellites compute positions using exactly sines and cosines.'),
      L('<b>Fizika va texnika.</b> Kuch qiya yo‘nalishda ta’sir qilsa, uning gorizontal qismi F cos α, vertikal qismi F sin α. α o‘tmas bo‘lsa, cos α &lt; 0 — demak kuch harakatga qarshi yo‘nalgan, masalan, chana tortayotganda arqon orqaga og‘ib qolsa.', '<b>Физика и техника.</b> Если сила действует под углом, её горизонтальная часть F cos α, вертикальная — F sin α. При тупом α cos α &lt; 0 — сила направлена против движения, например если верёвка санок отклонилась назад.', '<b>Physics and engineering.</b> When a force acts at an angle, its horizontal part is F cos α and its vertical part F sin α. If α is obtuse, cos α &lt; 0 — the force points against the motion, as when a sled rope leans backwards.'),
      L('<b>Kompyuter grafikasi.</b> O‘yinlarda obyektni burish uchun (x; y) → (x cos α − y sin α; x sin α + y cos α) formulasi ishlatiladi. α = 90° da u t6 dagi (−y; x) formulasini beradi.', '<b>Компьютерная графика.</b> Для поворота объекта в играх используют формулу (x; y) → (x cos α − y sin α; x sin α + y cos α). При α = 90° она даёт формулу (−y; x) из t6.', '<b>Computer graphics.</b> Games rotate objects with (x; y) → (x cos α − y sin α; x sin α + y cos α). For α = 90° this gives the (−y; x) formula from t6.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Sinus» so‘zi tarjima xatosidan kelib chiqqan: arabcha «jyb» (unlilarsiz yozilgan) «jayb» — «qo‘yin, qo‘ltiq» deb o‘qilgan va lotincha «sinus» deb tarjima qilingan.', 'Слово «синус» возникло из ошибки перевода: арабское «джйб» (записанное без гласных) прочли как «джайб» — «пазуха», и перевели на латынь как «sinus».', 'The word “sine” comes from a translation slip: the Arabic “jyb” (written without vowels) was read as “jayb”, meaning “fold” or “bosom”, and translated into Latin as “sinus”.'),
      L('«Kosinus» — «complementi sinus», ya’ni «to‘ldiruvchi burchak sinusi»: cos α = sin(90° − α).', '«Косинус» — от «complementi sinus», «синус дополнительного угла»: cos α = sin(90° − α).', '“Cosine” comes from “complementi sinus”, the sine of the complementary angle: cos α = sin(90° − α).'),
      L('Beruniy sin 1° ni juda aniq hisoblagan; Ulug‘bek rasadxonasida esa al-Koshiy uni 16 o‘nli xona aniqlikda topgan — Yevropada bunday aniqlikka ancha keyin erishilgan.', 'Беруни очень точно вычислил sin 1°, а в обсерватории Улугбека аль-Каши нашёл его с точностью до 16 знаков — такой точности в Европе достигли гораздо позже.', 'Al-Biruni computed sin 1° very accurately, and at Ulugh Beg’s observatory al-Kashi found it to 16 decimal places — a precision Europe reached only much later.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. cos 150° = ?', '1. cos 150° = ?', '1. cos 150° = ?'),
      L('2. sin α = 0,6, α o‘tmas. cos α = ?', '2. sin α = 0,6, α тупой. cos α = ?', '2. sin α = 0.6 and α is obtuse. cos α = ?'),
      L('3. sin<sup>2</sup>125° + cos<sup>2</sup>125° = ?', '3. sin<sup>2</sup>125° + cos<sup>2</sup>125° = ?', '3. sin<sup>2</sup>125° + cos<sup>2</sup>125° = ?'),
      L('4. Qaysi burchaklar uchun sin α = 1/2?', '4. Для каких углов sin α = 1/2?', '4. For which angles is sin α = 1/2?')
    ], after: [
      L('Javoblar: 1) −√3/2; 2) −0,8; 3) 1; 4) 30° va 150°.', 'Ответы: 1) −√3/2; 2) −0,8; 3) 1; 4) 30° и 150°.', 'Answers: 1) −√3/2; 2) −0.8; 3) 1; 4) 30° and 150°.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Birlik yarim aylanadagi M(x; y) nuqta uchun cos α = x, sin α = y, tg α = y/x.', 'Для точки M(x; y) единичной полуокружности cos α = x, sin α = y, tg α = y/x.', 'For M(x; y) on the unit semicircle: cos α = x, sin α = y, tan α = y/x.'),
      L('0° ≤ α ≤ 180° da 0 ≤ sin α ≤ 1, −1 ≤ cos α ≤ 1.', 'При 0° ≤ α ≤ 180°: 0 ≤ sin α ≤ 1, −1 ≤ cos α ≤ 1.', 'For 0° ≤ α ≤ 180°: 0 ≤ sin α ≤ 1 and −1 ≤ cos α ≤ 1.'),
      L('sin<sup>2</sup>α + cos<sup>2</sup>α = 1 — Pifagor teoremasining trigonometrik ko‘rinishi.', 'sin<sup>2</sup>α + cos<sup>2</sup>α = 1 — тригонометрическая форма теоремы Пифагора.', 'sin<sup>2</sup>α + cos<sup>2</sup>α = 1 is Pythagoras in trigonometric form.'),
      L('sin(180° − α) = sin α, cos(180° − α) = −cos α, tg(180° − α) = −tg α.', 'sin(180° − α) = sin α, cos(180° − α) = −cos α, tg(180° − α) = −tg α.', 'sin(180° − α) = sin α, cos(180° − α) = −cos α, tan(180° − α) = −tan α.'),
      L('Kosinus ishorasi burchak turini ko‘rsatadi; sinus bo‘yicha burchak ikki xil bo‘lishi mumkin.', 'Знак косинуса показывает вид угла; по синусу угол может быть двояким.', 'The sign of the cosine shows the type of angle; a sine value may give two angles.'),
      L('Ptolemey vatarlari, hind «jya»si, Abul-Vafo va Beruniy jadvallari — bugungi trigonometriyaning ildizlari.', 'Хорды Птолемея, индийская «джья», таблицы Абу-ль-Вафы и Беруни — корни современной тригонометрии.', 'Ptolemy’s chords, the Indian “jya” and the tables of Abu’l-Wafa and al-Biruni are the roots of today’s trigonometry.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '9-2';
  function F(x) { return L(x, x, x); }

  // ---------- t9. Uchburchak yuzini sinus yordamida hisoblash ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Balandliksiz yuz', 'Площадь без высоты', 'Area without a height'), p: [
      L('Uchburchak yuzi uchun eng mashhur formula — S = ½ah. Lekin amalda balandlikni o‘lchash ko‘pincha qiyin. Tasavvur qiling: fermer uchburchak shaklidagi yer uchastkasining yuzini bilmoqchi. U ikki chegara bo‘ylab yurib, ularning uzunligini o‘lchay oladi, burchakdagi qoziq yonida turib esa teodolit (yoki hatto telefon ilovasi) bilan ikki chegara orasidagi burchakni o‘lchaydi. Ammo dala o‘rtasidan perpendikulyar tortish — noqulay ish.', 'Самая известная формула площади треугольника — S = ½ah. Но на практике высоту часто трудно измерить. Представьте: фермер хочет узнать площадь треугольного участка. Он может пройти вдоль двух границ и измерить их длины, а стоя у углового колышка — измерить угол между границами теодолитом (или даже приложением на телефоне). А вот провести перпендикуляр через середину поля — неудобно.', 'The best-known formula for the area of a triangle is S = ½ah. But in practice the height is often hard to measure. Imagine a farmer who wants the area of a triangular plot. He can walk along two boundaries and measure their lengths, and standing at the corner post he can measure the angle between them with a theodolite (or even a phone app). Running a perpendicular across the middle of the field, though, is awkward.'),
      L('Oldingi mavzuda biz sinusni 0° dan 180° gacha istalgan burchak uchun ta’rifladik. Endi uning birinchi katta foydasini ko‘ramiz: uchburchak yuzini <b>ikki tomon va ular orasidagi burchak</b> orqali topish formulasi. U ½ah formulasidan bir qadamda kelib chiqadi, lekin balandlikni o‘lchash zaruratini butunlay yo‘qotadi.', 'В прошлой теме мы определили синус для любого угла от 0° до 180°. Теперь увидим его первую большую пользу: формулу площади треугольника через <b>две стороны и угол между ними</b>. Она получается из ½ah за один шаг, но полностью избавляет от необходимости измерять высоту.', 'In the previous topic we defined the sine for any angle from 0° to 180°. Now we see its first big payoff: the formula for a triangle’s area from <b>two sides and the angle between them</b>. It follows from ½ah in one step, yet it removes the need to measure a height at all.'),
      L('Bu mavzuda formulani isbotlaymiz (o‘tkir, to‘g‘ri va o‘tmas burchak uchun), undan parallelogramm va ixtiyoriy to‘rtburchak yuzi formulalarini keltirib chiqaramiz, yuzlar nisbati haqidagi foydali teoremani o‘rganamiz va ko‘plab amaliy masalalarni yechamiz.', 'В этой теме мы докажем формулу (для острого, прямого и тупого угла), выведем из неё формулы площади параллелограмма и произвольного четырёхугольника, изучим полезную теорему об отношении площадей и решим много практических задач.', 'In this topic we prove the formula (for acute, right and obtuse angles), derive from it the area formulas for a parallelogram and any quadrilateral, learn a useful theorem on ratios of areas and solve many practical problems.')
    ] },
    { kind: 'def', h: L('Formula va uning a’zolari', 'Формула и её элементы', 'The formula and its parts'), p: [
      L('△ABC da odatdagidek a = BC, b = CA, c = AB, burchaklar esa A, B, C bilan belgilanadi. <b>Teorema.</b> Uchburchak yuzi ikki tomoni va ular orasidagi burchak sinusi ko‘paytmasining yarmiga teng:', 'В △ABC, как обычно, a = BC, b = CA, c = AB, а углы обозначены A, B, C. <b>Теорема.</b> Площадь треугольника равна половине произведения двух его сторон на синус угла между ними:', 'In △ABC we write, as usual, a = BC, b = CA, c = AB and call the angles A, B, C. <b>Theorem.</b> The area of a triangle is half the product of two sides and the sine of the angle between them:')
    ], list: [
      F('S = ½ ab sin C'),
      F('S = ½ bc sin A'),
      F('S = ½ ac sin B')
    ], after: [
      L('<b>Muhim:</b> burchak aynan shu ikki tomon <i>orasida</i> bo‘lishi kerak. Masalan, a va b tomonlar C uchida uchrashadi, shuning uchun ular bilan C burchak ishlatiladi.', '<b>Важно:</b> угол должен лежать именно <i>между</i> этими двумя сторонами. Например, стороны a и b сходятся в вершине C, поэтому с ними используется угол C.', '<b>Important:</b> the angle must lie <i>between</i> the two sides. For example, sides a and b meet at vertex C, so the angle C goes with them.'),
      L('Uchta formuladan foydali natija: ½ab sin C = ½bc sin A, bundan a/sin A = c/sin C — bu keyingi mavzudagi <b>sinuslar teoremasi</b>ning bir qismi.', 'Из трёх формул следует полезный факт: ½ab sin C = ½bc sin A, откуда a/sin A = c/sin C — часть <b>теоремы синусов</b> из следующей темы.', 'A useful consequence of the three formulas: ½ab sin C = ½bc sin A, so a/sin A = c/sin C — part of the <b>sine rule</b> from the next topic.')
    ] },
    { kind: 'history', h: L('Tarixdan: yer o‘lchovchilardan Regiomontangacha', 'Из истории: от землемеров до Региомонтана', 'History: from land surveyors to Regiomontanus'), p: [
      L('Yer uchastkalari yuzini hisoblash geometriyaning eng qadimgi vazifasi: «geometriya» so‘zining o‘zi yunoncha «yerni o‘lchash» degani. Misrda Nil toshqinidan keyin chegaralarni qayta tiklash uchun «arqon tortuvchilar» uchburchak va trapetsiyalar yuzini hisoblashgan. I asrda <b>Geron Iskandariyalik</b> «Metrika» asarida uchburchak yuzini faqat uch tomon bo‘yicha topish formulasini isbotlagan. <b>Al-Xorazmiy</b> esa «Al-jabr» kitobining o‘lchash bo‘limida uchburchak va to‘rtburchak shaklidagi yerlarni o‘lchash usullarini bergan.', 'Вычисление площадей земельных участков — древнейшая задача геометрии: само слово «геометрия» по-гречески значит «землемерие». В Египте после разливов Нила «натягиватели верёвок» восстанавливали границы и вычисляли площади треугольников и трапеций. В I веке <b>Герон Александрийский</b> в «Метрике» доказал формулу площади треугольника только по трём сторонам. А <b>аль-Хорезми</b> в разделе об измерениях своей «Книги об алгебре» дал способы измерения треугольных и четырёхугольных участков.', 'Computing the areas of plots of land is the oldest task of geometry: the word “geometry” itself means “earth measuring” in Greek. In Egypt, after the Nile floods, “rope-stretchers” restored boundaries and computed the areas of triangles and trapeziums. In the 1st century <b>Heron of Alexandria</b>, in his Metrica, proved a formula for a triangle’s area from its three sides alone. <b>Al-Khwarizmi</b>, in the measurement section of his book on algebra, gave methods for measuring triangular and four-sided plots.'),
      L('Trigonometriya astronomiyadan mustaqil fanga aylangach, uchburchakni sinuslar bilan to‘liq «yechish» mumkin bo‘ldi. XIII asrda <b>Nasiriddin Tusiy</b> «To‘liq to‘rtburchak haqida risola»da tekis va sferik trigonometriyani birinchi marta alohida fan sifatida bayon qildi. 1464-yilda nemis olimi <b>Regiomontan</b> «Har xil uchburchaklar haqida» asarini yozdi: unda ikki tomon va burchak bo‘yicha yuzni topishga oid masalalar ham bor. Bu kitob Yevropada trigonometriyaning asosiy darsligiga aylandi.', 'Когда тригонометрия выделилась из астрономии в самостоятельную науку, треугольник стало возможно полностью «решать» с помощью синусов. В XIII веке <b>Насир ад-Дин ат-Туси</b> в «Трактате о полном четырёхстороннике» впервые изложил плоскую и сферическую тригонометрию как отдельную науку. В 1464 году немецкий учёный <b>Региомонтан</b> написал «О треугольниках всех видов»: там есть и задачи на площадь по двум сторонам и углу. Эта книга стала в Европе главным учебником тригонометрии.', 'Once trigonometry had become a science in its own right rather than a part of astronomy, triangles could be fully “solved” with sines. In the 13th century <b>Nasir al-Din al-Tusi</b>, in his Treatise on the Complete Quadrilateral, presented plane and spherical trigonometry as a separate subject for the first time. In 1464 the German scholar <b>Regiomontanus</b> wrote On Triangles of All Kinds, which includes problems on the area from two sides and an angle. It became Europe’s main trigonometry textbook.')
    ] },
    { kind: 'rule', h: L('Isbot: o‘tkir, to‘g‘ri va o‘tmas burchak', 'Доказательство: острый, прямой и тупой угол', 'Proof: acute, right and obtuse angle'), p: [
      L('B uchidan AC to‘g‘ri chizig‘iga BH balandlik tushiramiz; S = ½ · b · BH. Endi BH ni a va C orqali ifodalaymiz.', 'Опустим из вершины B высоту BH на прямую AC; S = ½ · b · BH. Выразим BH через a и C.', 'Drop the height BH from B to the line AC; S = ½ · b · BH. Now express BH through a and C.'),
      L('<b>C o‘tkir bo‘lsa:</b> H nuqta CA nurida yotadi, △BHC to‘g‘ri burchakli, gipotenuzasi BC = a. Demak BH = a sin C va S = ½ ab sin C.', '<b>Если C острый:</b> точка H лежит на луче CA, △BHC прямоугольный с гипотенузой BC = a. Значит, BH = a sin C и S = ½ ab sin C.', '<b>If C is acute:</b> H lies on ray CA, and △BHC is right-angled with hypotenuse BC = a. So BH = a sin C and S = ½ ab sin C.'),
      L('<b>C to‘g‘ri bo‘lsa:</b> H = C, BH = a, va sin 90° = 1, shuning uchun S = ½ ab = ½ ab sin 90°. Formula yana to‘g‘ri.', '<b>Если C прямой:</b> H = C, BH = a, а sin 90° = 1, поэтому S = ½ ab = ½ ab sin 90°. Формула снова верна.', '<b>If C is right:</b> H = C and BH = a, and sin 90° = 1, so S = ½ ab = ½ ab sin 90°. The formula holds again.'),
      L('<b>C o‘tmas bo‘lsa:</b> H nuqta AC ning C dan tashqaridagi davomida yotadi. △BHC da C uchidagi burchak 180° − C ga teng (qo‘shni burchak). Demak BH = a sin(180° − C) = a sin C — t8 dagi keltirish formulasi ishlaydi! Yana S = ½ ab sin C. Aynan shu uchun sinusni o‘tmas burchaklar uchun ham ta’riflash kerak edi.', '<b>Если C тупой:</b> точка H лежит на продолжении AC за точку C. В △BHC угол при C равен 180° − C (смежный). Значит, BH = a sin(180° − C) = a sin C — работает формула приведения из t8! Снова S = ½ ab sin C. Именно для этого и нужно было определить синус тупого угла.', '<b>If C is obtuse:</b> H lies on the extension of AC beyond C. In △BHC the angle at C is 180° − C (the supplementary angle). So BH = a sin(180° − C) = a sin C — the reduction formula from t8 at work! Again S = ½ ab sin C. This is exactly why we needed the sine of an obtuse angle.')
    ] },
    { kind: 'rule', h: L('Natijalar: parallelogramm, to‘rtburchak va yuzlar nisbati', 'Следствия: параллелограмм, четырёхугольник и отношение площадей', 'Consequences: parallelogram, quadrilateral and area ratios'), p: [
      L('<b>Parallelogramm:</b> diagonal uni ikkita teng uchburchakka bo‘ladi, har birining yuzi ½ ab sin α. Demak <b>S = ab sin α</b>, bu yerda a, b — qo‘shni tomonlar, α — ular orasidagi burchak (o‘tkir yoki o‘tmas — sinus bir xil!). Romb uchun S = a<sup>2</sup> sin α.', '<b>Параллелограмм:</b> диагональ делит его на два равных треугольника площадью ½ ab sin α каждый. Значит, <b>S = ab sin α</b>, где a, b — смежные стороны, α — угол между ними (острый или тупой — синус одинаков!). Для ромба S = a<sup>2</sup> sin α.', '<b>Parallelogram:</b> a diagonal splits it into two congruent triangles, each of area ½ ab sin α. So <b>S = ab sin α</b>, where a and b are adjacent sides and α is the angle between them (acute or obtuse — the sine is the same!). For a rhombus S = a<sup>2</sup> sin α.'),
      L('<b>Ixtiyoriy qavariq to‘rtburchak:</b> <b>S = ½ d<sub>1</sub>d<sub>2</sub> sin φ</b>, bu yerda d<sub>1</sub>, d<sub>2</sub> — diagonallar, φ — ular orasidagi burchak. Isbot g‘oyasi: diagonallar to‘rtburchakni to‘rtta uchburchakka bo‘ladi, har birida diagonallar bo‘laklari va φ yoki 180° − φ burchak bor; yuzlarni qo‘shib, umumiy ko‘paytuvchini qavsdan chiqaramiz. φ = 90° da romb formulasi ½ d<sub>1</sub>d<sub>2</sub> hosil bo‘ladi.', '<b>Произвольный выпуклый четырёхугольник:</b> <b>S = ½ d<sub>1</sub>d<sub>2</sub> sin φ</b>, где d<sub>1</sub>, d<sub>2</sub> — диагонали, φ — угол между ними. Идея доказательства: диагонали делят четырёхугольник на четыре треугольника, в каждом есть части диагоналей и угол φ или 180° − φ; сложив площади, выносим общий множитель за скобки. При φ = 90° получается формула ромба ½ d<sub>1</sub>d<sub>2</sub>.', '<b>Any convex quadrilateral:</b> <b>S = ½ d<sub>1</sub>d<sub>2</sub> sin φ</b>, where d<sub>1</sub> and d<sub>2</sub> are the diagonals and φ the angle between them. Proof idea: the diagonals cut it into four triangles, each with two diagonal pieces and the angle φ or 180° − φ; add the areas and factor out the common terms. With φ = 90° we get the rhombus formula ½ d<sub>1</sub>d<sub>2</sub>.'),
      L('<b>Yuzlar nisbati teoremasi:</b> agar ikki uchburchakda bittadan burchak teng (yoki ularning yig‘indisi 180°) bo‘lsa, ularning yuzlari nisbati shu burchakni tashkil etuvchi tomonlar ko‘paytmalari nisbatiga teng: S<sub>1</sub>/S<sub>2</sub> = (a<sub>1</sub>b<sub>1</sub>)/(a<sub>2</sub>b<sub>2</sub>). Sinuslar qisqarib ketadi. <b>Teng tomonli uchburchak:</b> S = ½ a<sup>2</sup> sin 60° = a<sup>2</sup>√3/4.', '<b>Теорема об отношении площадей:</b> если у двух треугольников по одному углу равны (или их сумма 180°), то их площади относятся как произведения сторон, заключающих эти углы: S<sub>1</sub>/S<sub>2</sub> = (a<sub>1</sub>b<sub>1</sub>)/(a<sub>2</sub>b<sub>2</sub>). Синусы сокращаются. <b>Равносторонний треугольник:</b> S = ½ a<sup>2</sup> sin 60° = a<sup>2</sup>√3/4.', '<b>Area ratio theorem:</b> if two triangles have an equal angle (or angles adding up to 180°), their areas are in the ratio of the products of the sides enclosing those angles: S<sub>1</sub>/S<sub>2</sub> = (a<sub>1</sub>b<sub>1</sub>)/(a<sub>2</sub>b<sub>2</sub>). The sines cancel. <b>Equilateral triangle:</b> S = ½ a<sup>2</sup> sin 60° = a<sup>2</sup>√3/4.')
    ] },
    { kind: 'steps', h: L('Formula bilan ishlash tartibi', 'Порядок работы с формулой', 'How to use the formula'), list: [
      L('1. Ikki ma’lum tomonni va ular orasidagi burchakni toping. Burchak boshqa joyda bo‘lsa, avval uchburchak burchaklari yig‘indisi (180°) yordamida kerakli burchakni hisoblang.', '1. Найдите две известные стороны и угол между ними. Если угол дан в другом месте, сначала вычислите нужный угол по сумме углов треугольника (180°).', '1. Identify two known sides and the angle between them. If the angle given is elsewhere, first work out the needed angle using the 180° angle sum.'),
      L('2. Burchak sinusini jadvaldan yoki kalkulyatordan oling (DEG rejimi!). O‘tmas burchak uchun sin α = sin(180° − α).', '2. Возьмите синус угла из таблицы или с калькулятора (режим DEG!). Для тупого угла sin α = sin(180° − α).', '2. Get the sine from the table or a calculator (DEG mode!). For an obtuse angle, sin α = sin(180° − α).'),
      L('3. Formulaga qo‘ying: S = ½ · birinchi tomon · ikkinchi tomon · sinus.', '3. Подставьте в формулу: S = ½ · первая сторона · вторая сторона · синус.', '3. Substitute: S = ½ · first side · second side · sine.'),
      L('4. Teskari masalada (yuz ma’lum) formuladan noma’lumni ifodalang: sin C = 2S/(ab) yoki a = 2S/(b sin C).', '4. В обратной задаче (площадь известна) выразите неизвестное: sin C = 2S/(ab) или a = 2S/(b sin C).', '4. In a reverse problem (area known), solve for the unknown: sin C = 2S/(ab) or a = 2S/(b sin C).'),
      L('5. Burchakni sinus bo‘yicha topsangiz, ikkita javob bo‘lishi mumkinligini unutmang: C va 180° − C.', '5. Находя угол по синусу, помните: ответов может быть два — C и 180° − C.', '5. When finding an angle from its sine, remember there may be two answers: C and 180° − C.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Uchburchakning ikki tomoni 10 cm va 7 cm, ular orasidagi burchak 150°. Yuzini toping.', 'Две стороны треугольника 10 см и 7 см, угол между ними 150°. Найдите площадь.', 'Two sides of a triangle are 10 cm and 7 cm with an angle of 150° between them. Find the area.'),
        s: L('sin 150° = sin 30° = ½. S = ½ · 10 · 7 · ½ = 17,5 cm<sup>2</sup>.', 'sin 150° = sin 30° = ½. S = ½ · 10 · 7 · ½ = 17,5 см<sup>2</sup>.', 'sin 150° = sin 30° = ½. S = ½ · 10 · 7 · ½ = 17.5 cm<sup>2</sup>.') },
      { q: L('Parallelogramm tomonlari 6 va 8, bir burchagi 135°. Yuzini toping.', 'Стороны параллелограмма 6 и 8, один угол 135°. Найдите площадь.', 'A parallelogram has sides 6 and 8 and one angle of 135°. Find its area.'),
        s: L('S = ab sin α = 6 · 8 · sin 135° = 48 · √2/2 = 24√2 ≈ 33,9. O‘tkir burchak 45° ni olsak ham natija bir xil, chunki sin 45° = sin 135°.', 'S = ab sin α = 6 · 8 · sin 135° = 48 · √2/2 = 24√2 ≈ 33,9. С острым углом 45° результат тот же, ведь sin 45° = sin 135°.', 'S = ab sin α = 6 · 8 · sin 135° = 48 · √2/2 = 24√2 ≈ 33.9. Using the acute angle 45° gives the same result, since sin 45° = sin 135°.') },
      { q: L('Uchburchak yuzi 12√3, ikki tomoni 6 va 8. Ular orasidagi burchakni toping.', 'Площадь треугольника 12√3, две стороны 6 и 8. Найдите угол между ними.', 'A triangle has area 12√3 and two sides 6 and 8. Find the angle between them.'),
        s: L('sin C = 2S/(ab) = 24√3/48 = √3/2. Demak C = 60° yoki C = 120°. Ikkala uchburchak ham mavjud — ular bir xil yuzli, lekin shakli turlicha.', 'sin C = 2S/(ab) = 24√3/48 = √3/2. Значит, C = 60° или C = 120°. Оба треугольника существуют — у них одинаковая площадь, но разная форма.', 'sin C = 2S/(ab) = 24√3/48 = √3/2. So C = 60° or C = 120°. Both triangles exist — same area, different shapes.') },
      { q: L('△ABC da AB = 12, AC = 15. AB da M nuqta, AM = 4; AC da N nuqta, AN = 9. △AMN yuzi △ABC yuzining qanday qismini tashkil etadi?', 'В △ABC AB = 12, AC = 15. На AB точка M, AM = 4; на AC точка N, AN = 9. Какую часть площади △ABC составляет площадь △AMN?', 'In △ABC, AB = 12 and AC = 15. M is on AB with AM = 4, and N is on AC with AN = 9. What fraction of the area of △ABC is △AMN?'),
        s: L('Ikkala uchburchakda A burchak umumiy. S<sub>AMN</sub>/S<sub>ABC</sub> = (AM · AN)/(AB · AC) = (4 · 9)/(12 · 15) = 36/180 = 1/5. A burchakni bilish shart emas!', 'У обоих треугольников общий угол A. S<sub>AMN</sub>/S<sub>ABC</sub> = (AM · AN)/(AB · AC) = (4 · 9)/(12 · 15) = 36/180 = 1/5. Знать угол A не нужно!', 'Both triangles share angle A. S<sub>AMN</sub>/S<sub>ABC</sub> = (AM · AN)/(AB · AC) = (4 · 9)/(12 · 15) = 36/180 = 1/5. We never need to know angle A!') },
      { q: L('To‘rtburchak diagonallari 10 va 14, ular orasidagi burchak 30°. Yuzini toping.', 'Диагонали четырёхугольника 10 и 14, угол между ними 30°. Найдите площадь.', 'A quadrilateral has diagonals 10 and 14 meeting at 30°. Find its area.'),
        s: L('S = ½ d<sub>1</sub>d<sub>2</sub> sin φ = ½ · 10 · 14 · ½ = 35.', 'S = ½ d<sub>1</sub>d<sub>2</sub> sin φ = ½ · 10 · 14 · ½ = 35.', 'S = ½ d<sub>1</sub>d<sub>2</sub> sin φ = ½ · 10 · 14 · ½ = 35.') }
    ] },
    { kind: 'table', h: L('Sinus orqali yuz formulalari', 'Формулы площади через синус', 'Area formulas with the sine'), table: {
      head: [L('Shakl', 'Фигура', 'Figure'), L('Formula', 'Формула', 'Formula'), L('Izoh', 'Пояснение', 'Note')],
      rows: [
        [L('uchburchak', 'треугольник', 'triangle'), F('S = ½ ab sin C'), L('C — a va b orasida', 'C — между a и b', 'C lies between a and b')],
        [L('teng tomonli uchburchak', 'равносторонний треугольник', 'equilateral triangle'), F('S = a²√3/4'), F('sin 60° = √3/2')],
        [L('parallelogramm', 'параллелограмм', 'parallelogram'), F('S = ab sin α'), L('α — qo‘shni tomonlar orasida', 'α — между смежными сторонами', 'α between adjacent sides')],
        [L('romb', 'ромб', 'rhombus'), F('S = a² sin α'), L('barcha tomonlar teng', 'все стороны равны', 'all sides equal')],
        [L('qavariq to‘rtburchak', 'выпуклый четырёхугольник', 'convex quadrilateral'), F('S = ½ d₁d₂ sin φ'), L('φ — diagonallar orasida', 'φ — между диагоналями', 'φ between the diagonals')],
        [L('to‘g‘ri burchakli uchburchak', 'прямоугольный треугольник', 'right triangle'), F('S = ½ ab'), F('sin 90° = 1')]
      ] }, after: [
      L('E’tibor bering: formulalar sinusning eng katta qiymati 1 ekanini ko‘rsatadi. Ikki tomoni berilgan uchburchaklar orasida eng katta yuzga to‘g‘ri burchakli uchburchak ega: S ≤ ½ ab.', 'Заметьте: формулы показывают, что наибольшее значение синуса равно 1. Среди треугольников с данными двумя сторонами наибольшую площадь имеет прямоугольный: S ≤ ½ ab.', 'Notice that, since the sine is at most 1, among triangles with two given sides the right-angled one has the greatest area: S ≤ ½ ab.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Noto‘g‘ri burchakni olish.</b> a va b tomonlar bilan A yoki B burchakni ishlatish xato. Burchak aynan ikki tomon tutashgan uchda bo‘lishi kerak.', '<b>Брать не тот угол.</b> Использовать со сторонами a и b угол A или B — ошибка. Угол должен быть в вершине, где эти стороны сходятся.', '<b>Using the wrong angle.</b> Pairing sides a and b with angle A or B is wrong. The angle must be at the vertex where the two sides meet.'),
      L('<b>½ ni unutish.</b> Uchburchak uchun ½ ab sin C, parallelogramm uchun esa ab sin α — ½ siz. Ularni adashtirmang.', '<b>Забывать ½.</b> Для треугольника ½ ab sin C, а для параллелограмма ab sin α — без ½. Не путайте их.', '<b>Forgetting the ½.</b> A triangle uses ½ ab sin C; a parallelogram uses ab sin α, without the ½. Do not mix them up.'),
      L('<b>O‘tmas burchak sinusini manfiy olish.</b> sin 120° = +√3/2. Yuz hech qachon manfiy bo‘lmaydi!', '<b>Брать синус тупого угла отрицательным.</b> sin 120° = +√3/2. Площадь никогда не бывает отрицательной!', '<b>Making the sine of an obtuse angle negative.</b> sin 120° = +√3/2. An area is never negative!'),
      L('<b>Teskari masalada bitta javob berish.</b> sin C = ½ dan C = 30° ham, C = 150° ham chiqadi. Agar masala shartida qo‘shimcha ma’lumot bo‘lmasa, ikkalasini yozing.', '<b>Давать один ответ в обратной задаче.</b> Из sin C = ½ получается и C = 30°, и C = 150°. Если в условии нет дополнительных данных, запишите оба.', '<b>Giving only one answer in a reverse problem.</b> sin C = ½ gives C = 30° and C = 150°. Unless the problem rules one out, give both.')
    ] },
    { kind: 'life', h: L('Hayotda: dala, tom va yelkan', 'В жизни: поле, крыша и парус', 'In real life: fields, roofs and sails'), p: [
      L('<b>Yer tuzish va geodeziya.</b> Kadastr xizmati xodimlari murakkab shakldagi yerni uchburchaklarga bo‘ladi va har birida ikki tomon va burchakni o‘lchab, S = ½ ab sin C bilan yuzni hisoblaydi. Masalan, chegaralari 80 m va 60 m bo‘lib, 70° burchak hosil qilgan uchastka yuzi ½ · 80 · 60 · sin 70° ≈ 2255 m<sup>2</sup>, ya’ni taxminan 22,5 sotix.', '<b>Землеустройство и геодезия.</b> Сотрудники кадастра делят участок сложной формы на треугольники и в каждом, измерив две стороны и угол, считают площадь по S = ½ ab sin C. Например, участок с границами 80 м и 60 м под углом 70° имеет площадь ½ · 80 · 60 · sin 70° ≈ 2255 м<sup>2</sup>, то есть около 22,5 сотки.', '<b>Land registry and surveying.</b> Surveyors split an irregular plot into triangles and, measuring two sides and an angle in each, compute the area with S = ½ ab sin C. For instance, a plot with boundaries 80 m and 60 m meeting at 70° has area ½ · 80 · 60 · sin 70° ≈ 2,255 m<sup>2</sup>, about 0.23 hectares.'),
      L('<b>Qurilish va dizayn.</b> Uyning uchburchak shaklidagi frontoni (tom ostidagi devor) uchun qancha g‘isht yoki bo‘yoq kerakligini hisoblashda usta qiya tomonlar uzunligini va ular orasidagi burchakni o‘lchaydi. Yelkanli qayiq yelkani, kaytsyorfing qanoti va bayroqlar uchun mato miqdori ham shunday hisoblanadi.', '<b>Строительство и дизайн.</b> Чтобы рассчитать, сколько кирпича или краски нужно на треугольный фронтон дома, мастер измеряет длины скатов и угол между ними. Так же считают ткань для паруса яхты, крыла кайта и флагов.', '<b>Building and design.</b> To work out how many bricks or how much paint a triangular gable needs, a builder measures the two sloping edges and the angle between them. Fabric for yacht sails, kite wings and flags is calculated the same way.'),
      L('<b>Fizika.</b> Ikki vektor «yasagan» parallelogramm yuzi |a||b| sin α — bu kuch momenti va magnit maydonidagi kuchni hisoblashda ishlatiladigan vektor ko‘paytmaning uzunligi. Gayka kalitini 90° burchak ostida tortsangiz, sin 90° = 1 bo‘lgani uchun moment eng katta bo‘ladi.', '<b>Физика.</b> Площадь параллелограмма, построенного на двух векторах, равна |a||b| sin α — это длина векторного произведения, которое используют для момента силы и силы в магнитном поле. Если тянуть гаечный ключ под углом 90°, момент максимален, потому что sin 90° = 1.', '<b>Physics.</b> The area of the parallelogram spanned by two vectors is |a||b| sin α — the length of the cross product, used for torque and for the force in a magnetic field. Pulling a spanner at 90° gives the greatest torque because sin 90° = 1.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Tomonlari a va b bo‘lgan parallelogrammning burchagini o‘zgartirsak (masalan, sharnirli rom), yuzi 0 dan ab gacha o‘zgaradi: eng kattasi — to‘g‘ri to‘rtburchak. Shuning uchun deraza romlari diagonal reyka bilan mustahkamlanadi.', 'Если менять угол параллелограмма со сторонами a и b (например, шарнирной рамки), площадь меняется от 0 до ab, наибольшая — у прямоугольника. Поэтому оконные рамы укрепляют диагональной рейкой.', 'If you change the angle of a parallelogram with sides a and b (a hinged frame, say), its area ranges from 0 to ab, with the maximum for the rectangle. That is why window frames are braced with a diagonal strip.'),
      L('Bir xil perimetrli uchburchaklar orasida eng katta yuzga teng tomonli uchburchak ega. Perimetri 12 bo‘lsa, uning yuzi 4√3 ≈ 6,93.', 'Среди треугольников с одинаковым периметром наибольшая площадь у равностороннего. При периметре 12 его площадь 4√3 ≈ 6,93.', 'Among triangles with the same perimeter, the equilateral one has the greatest area. With perimeter 12 its area is 4√3 ≈ 6.93.'),
      L('Muntazam n-burchak yuzini ham shu formula beradi: uni markazdan n ta teng yonli uchburchakka bo‘lsak, S = ½ n R<sup>2</sup> sin(360°/n). n juda katta bo‘lganda bu πR<sup>2</sup> ga yaqinlashadi.', 'Площадь правильного n-угольника даёт та же формула: разрежем его из центра на n равнобедренных треугольников, S = ½ n R<sup>2</sup> sin(360°/n). При очень большом n это приближается к πR<sup>2</sup>.', 'The same formula gives the area of a regular n-gon: cut it from the centre into n isosceles triangles to get S = ½ n R<sup>2</sup> sin(360°/n). For very large n this approaches πR<sup>2</sup>.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. a = 4, b = 9, C = 30°. S = ?', '1. a = 4, b = 9, C = 30°. S = ?', '1. a = 4, b = 9, C = 30°. S = ?'),
      L('2. Rombning tomoni 5, burchagi 150°. Yuzi?', '2. Сторона ромба 5, угол 150°. Площадь?', '2. A rhombus has side 5 and angle 150°. Its area?'),
      L('3. Teng tomonli uchburchak tomoni 6. Yuzi?', '3. Сторона равностороннего треугольника 6. Площадь?', '3. An equilateral triangle has side 6. Its area?'),
      L('4. Ikki uchburchakda A burchak umumiy, tomonlari mos ravishda 3, 4 va 6, 10. Yuzlar nisbati?', '4. У двух треугольников общий угол A, прилежащие стороны 3, 4 и 6, 10. Отношение площадей?', '4. Two triangles share angle A, with enclosing sides 3, 4 and 6, 10. The ratio of areas?')
    ], after: [
      L('Javoblar: 1) ½ · 4 · 9 · ½ = 9; 2) 25 · ½ = 12,5; 3) 36√3/4 = 9√3 ≈ 15,6; 4) 12/60 = 1/5.', 'Ответы: 1) ½ · 4 · 9 · ½ = 9; 2) 25 · ½ = 12,5; 3) 36√3/4 = 9√3 ≈ 15,6; 4) 12/60 = 1/5.', 'Answers: 1) ½ · 4 · 9 · ½ = 9; 2) 25 · ½ = 12.5; 3) 36√3/4 = 9√3 ≈ 15.6; 4) 12/60 = 1/5.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Uchburchak yuzi: S = ½ ab sin C — ikki tomon va ular orasidagi burchak.', 'Площадь треугольника: S = ½ ab sin C — две стороны и угол между ними.', 'Triangle area: S = ½ ab sin C, from two sides and the angle between them.'),
      L('Isbot: balandlik h = a sin C; o‘tmas burchakda sin(180° − C) = sin C yordam beradi.', 'Доказательство: высота h = a sin C; для тупого угла помогает sin(180° − C) = sin C.', 'Proof: the height is h = a sin C; for an obtuse angle, sin(180° − C) = sin C does the job.'),
      L('Parallelogramm: S = ab sin α; romb: S = a<sup>2</sup> sin α.', 'Параллелограмм: S = ab sin α; ромб: S = a<sup>2</sup> sin α.', 'Parallelogram: S = ab sin α; rhombus: S = a<sup>2</sup> sin α.'),
      L('Qavariq to‘rtburchak: S = ½ d<sub>1</sub>d<sub>2</sub> sin φ.', 'Выпуклый четырёхугольник: S = ½ d<sub>1</sub>d<sub>2</sub> sin φ.', 'Convex quadrilateral: S = ½ d<sub>1</sub>d<sub>2</sub> sin φ.'),
      L('Umumiy burchakli uchburchaklar yuzlari burchakni tashkil etuvchi tomonlar ko‘paytmalari kabi nisbatda.', 'Площади треугольников с общим углом относятся как произведения сторон, заключающих этот угол.', 'Triangles with a common angle have areas in the ratio of the products of the sides enclosing it.'),
      L('Teskari masalada sinus bo‘yicha burchak ikki xil bo‘lishi mumkin: C yoki 180° − C.', 'В обратной задаче угол по синусу может быть двояким: C или 180° − C.', 'In reverse problems the angle from a sine may be C or 180° − C.')
    ] }
  ] });
})(this);
